public class Main {
    static class Rib {
        long b, u, c, f;
        int back;

        Rib(long b, long u, long c, long f, int back) {
            this.b = b;
            this.u = u;
            this.c = c;
            this.f = f;
            this.back = back;
        }
    }

    static void addRib(List<List<Rib>> g, long a, long b, long u, long c) {
        Rib r1 = new Rib(b, u, c, 0, g.get((int)b).size());
        Rib r2 = new Rib(a, 0, -c, 0, g.get((int)a).size());
        g.get((int)a).add(r1);
        g.get((int)b).add(r2);
    }

    static class K {
        static long n, m, k, c, d;
    }

    static List<List<Rib>> g;
    static List<Long> vr[] = new List[55];
    static long lr[] = new long[50];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        K.n = sc.nextLong();
        K.m = sc.nextLong();
        K.k = sc.nextLong();
        K.c = sc.nextLong();
        K.d = sc.nextLong();

        long n = 50 * 99 + 1;
        g = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            g.add(new ArrayList<>());
        }

        for (int i = 0; i < 55; i++) {
            vr[i] = new ArrayList<>();
        }

        long s, t;
        s = 0;
        t = 1;

        for (int i = 1; i <= K.k; i++) {
            lr[i] = sc.nextLong();
            addRib(g, 0, lr[i], 1, 0);
        }

        long tim = 99;
        for (int j = 0; j < tim - 1; j++) {
            for (int i = 2; i <= K.n; i++) {
                addRib(g, j * 50 + i, (j + 1) * 50 + i, 50, K.c);
            }
        }

        for (int j = 1; j < tim; j++) {
            addRib(g, j * 50 + 1, 1, 50, 0);
        }

        for (int i = 0; i < K.m; i++) {
            long x = sc.nextLong();
            long y = sc.nextLong();
            vr[(int)x].add(y);
            vr[(int)y].add(x);

            for (int j = 0; j < tim - 1; j++) {
                for (int l = 0; l < 50; l++) {
                    long cost1 = K.c + K.d * ((l + 1) * (l + 1) - (l * l));
                    addRib(g, j * 50 + x, (j + 1) * 50 + y, 1, cost1);
                    addRib(g, j * 50 + y, (j + 1) * 50 + x, 1, cost1);
                }
            }
        }

        long flow = 0, cost = 0;
        while (flow < K.k) {
            long[] id = new long[(int)n];
            long[] d = new long[(int)n];
            long[] q = new long[(int)n];
            long[] p = new long[(int)n];
            int[] p_rib = new int[(int)n];

            for (int i = 0; i < n; i++) {
                d[(int)i] = Long.MAX_VALUE;
            }

            int qh = 0, qt = 0;
            q[qt++] = s;
            d[(int)s] = 0;

            while (qh != qt) {
                long v = q[qh++];
                id[(int)v] = 2;
                if (qh == n) qh = 0;

                for (int i = 0; i < g.get((int)v).size(); i++) {
                    Rib r = g.get((int)v).get(i);
                    if (r.f < r.u && d[(int)v] + r.c < d[(int)r.b]) {
                        d[(int)r.b] = d[(int)v] + r.c;
                        if (id[(int)r.b] == 0) {
                            q[qt++] = r.b;
                            if (qt == n) qt = 0;
                        } else if (id[(int)r.b] == 2) {
                            if (--qh == -1) qh = (int)n - 1;
                            q[qh] = r.b;
                        }
                        id[(int)r.b] = 1;
                        p[(int)r.b] = v;
                        p_rib[(int)r.b] = i;
                    }
                }
            }

            if (d[(int)t] == Long.MAX_VALUE) break;

            long addflow = K.k - flow;
            for (long v = t; v != s; v = p[(int)v]) {
                long pv = p[(int)v];
                int pr = p_rib[(int)v];
                Rib rib = g.get((int)pv).get(pr);
                addflow = Math.min(addflow, rib.u - rib.f);
            }

            for (long v = t; v != s; v = p[(int)v]) {
                long pv = p[(int)v];
                int pr = p_rib[(int)v];
                int r = g.get((int)pv).get(pr).back;
                Rib rib1 = g.get((int)pv).get(pr);
                Rib rib2 = g.get((int)v).get(r);
                rib1.f += addflow;
                rib2.f -= addflow;
                cost += rib1.c * addflow;
            }

            flow += addflow;
        }

        System.out.println(cost);
    }
