import java.util.*;

public class Main {
    static final int N = 10000;
    static final int M = N * 100;
    static final long inf = Long.MAX_VALUE >> 5;

    static class FlowGraph {
        private int[] head = new int[N];
        private int[] v = new int[M];
        private int[] nxt = new int[M];
        private int[] c = new int[M];
        private int ptr = 0;
        private int t;
        private long[] w = new long[M];
        private long cost = 0;

        private void padd_edge(int uu, int vv, long ww, int cc) {
            v[ptr] = vv;
            w[ptr] = ww;
            c[ptr] = cc;
            nxt[ptr] = head[uu];
            head[uu] = ptr++;
        }

        private int[] dis = new int[N];
        private int[] id = new int[N];
        private int[] cur = new int[N];
        private boolean[] vis = new boolean[N];

        private boolean spfa(int s, int t) {
            Arrays.fill(vis, false);
            Arrays.fill(dis, -1);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            dis[s] = 0;
            id[s] = 1;

            while (!q.isEmpty()) {
                int nd = q.poll();
                vis[nd] = false;
                for (int i = head[nd]; i != -1; i = nxt[i]) {
                    if (w[i] > 0 && (dis[v[i]] == -1 || dis[v[i]] > dis[nd] + c[i])) {
                        dis[v[i]] = dis[nd] + c[i];
                        if (!vis[v[i]]) {
                            vis[v[i]] = true;
                            q.offer(v[i]);
                        }
                    }
                }
            }
            return dis[t] != -1;
        }

        private long dfs(int pos, long flow) {
            if (pos == t) return flow;
            vis[pos] = true;
            long tmp = flow;
            int start = cur[pos] != -1 ? cur[pos] : head[pos];
            for (int i = start; i != -1; i = nxt[i]) {
                if (!vis[v[i]] && w[i] > 0 && dis[v[i]] == dis[pos] + c[i]) {
                    cur[pos] = i;
                    long fl = dfs(v[i], Math.min(flow, w[i]));
                    cost += fl * c[i];
                    w[i] -= fl;
                    w[i ^ 1] += fl;
                    flow -= fl;
                    if (flow == 0) break;
                }
            }
            return tmp - flow;
        }

        public FlowGraph() {
            Arrays.fill(head, -1);
            Arrays.fill(nxt, -1);
        }

        public void add_edge(int uu, int vv, long ww, int cc) {
            padd_edge(uu, vv, ww, cc);
            padd_edge(vv, uu, 0, -cc);
        }

        public long dinic(int s, int t) {
            this.cost = 0;
            this.t = t;
            while (spfa(s, t)) {
                Arrays.fill(cur, -1);
                dfs(s, inf);
            }
            return cost;
        }
    }

