    static void add_edge(int u, int v, int cap, int cost) {
        edges.add(new Edge(head.get(u), v, cap, cost));
        head.set(u, e_idx);
        e_idx++;
        edges.add(new Edge(head.get(v), u, 0, -cost));
        head.set(v, e_idx);
        e_idx++;
    }

    static int[] prev_v = new int[MAX_V];
    static int[] prev_e = new int[MAX_V];
    static int[] min_flow = new int[MAX_V];
