#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>
using namespace std;

using llong = long long;

struct Arc {
    int to;
    int capacity;
    int flow;
    int cost;
    Arc(int t, int cap, int flo, int cst) : to(t), capacity(cap), flow(flo), cost(cst) {}
};

vector<Arc> arcs;
vector<vector<int>> adjacencyList;
const int NODE_LIMIT = 14043;
llong shortestPath[NODE_LIMIT];
int predecessorNode[NODE_LIMIT];
int predecessorArc[NODE_LIMIT];
bool visited[NODE_LIMIT];

const llong HUGE = (llong)(1e18);

int src = NODE_LIMIT - 2;
int dst = NODE_LIMIT - 1;

int getResidual(int idx) {
    return arcs[idx].capacity - arcs[idx].flow;
}

void dijkstraLike() {
    fill(shortestPath, shortestPath + NODE_LIMIT, HUGE);
    fill(predecessorNode, predecessorNode + NODE_LIMIT, -1);
    fill(predecessorArc, predecessorArc + NODE_LIMIT, -1);
    fill(visited, visited + NODE_LIMIT, false);
    shortestPath[src] = 0;
    queue<int> q;
    q.push(src);
    visited[src] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        visited[u] = false;
        for (int idx : adjacencyList[u]) {
            if (!getResidual(idx)) continue;
            int v = arcs[idx].to;
            int cost = arcs[idx].cost;
            if (shortestPath[v] > shortestPath[u] + cost) {
                shortestPath[v] = shortestPath[u] + cost;
                predecessorNode[v] = u;
                predecessorArc[v] = idx;
                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
    }
}

void sendFlow() {
    dijkstraLike();
    int cur = dst;
    while (cur != src) {
        arcs[predecessorArc[cur]].flow += 1;
        arcs[predecessorArc[cur] ^ 1].flow -= 1;
        cur = predecessorNode[cur];
    }
}

void link(int u, int v, int cap, int cst) {
    adjacencyList[u].push_back(arcs.size());
    arcs.emplace_back(v, cap, 0, cst);
    adjacencyList[v].push_back(arcs.size());
    arcs.emplace_back(u, 0, 0, -cst);
}

int main() {
    ios_base::sync_with_stdio(false);
