            this.reverse = reverse;
        }
    }

    static int total_nodes, start_node, end_node;
    static ArrayList<Stream>[] network = new ArrayList[CAPACITY];
    static long[] potential = new long[CAPACITY];
    static int[] ancestor_node = new int[CAPACITY];
    static int[] ancestor_edge = new int[CAPACITY];
    static boolean[] queued = new boolean[CAPACITY];

    static void erase_structure(int n, int s, int t) {
        for (int i = 0; i <= n; ++i) {
            network[i].clear();
        }
        total_nodes = n;
        start_node = s;
        end_node = t;
    }

    static void insert_link(int u, int v, int cap, int weight) {
        network[u].add(new Stream(v, cap, weight, network[v].size()));
        network[v].add(new Stream(u, 0, -weight, network[u].size() - 1));
    }

    static long minimum_cost_flow(int demand) {
        long overall = 0;
        while (demand > 0) {
            Arrays.fill(potential, INFINITY);
            potential[start_node] = 0;
            Queue<Integer> pending = new LinkedList<>();
            pending.add(start_node);
            Arrays.fill(queued, false);
            queued[start_node] = true;

            while (!pending.isEmpty()) {
                int u = pending.poll();
                queued[u] = false;
                for (int idx = 0; idx < network[u].size(); ++idx) {
                    Stream link = network[u].get(idx);
                    if (link.limit > 0 && potential[u] + link.fee < potential[link.end]) {
                        potential[link.end] = potential[u] + link.fee;
                        ancestor_node[link.end] = u;
                        ancestor_edge[link.end] = idx;
                        if (!queued[link.end]) {
                            queued[link.end] = true;
                            pending.add(link.end);
                        }
                    }
                }
            }

            if (potential[end_node] == INFINITY) return -1;

            int throughput = demand;
            for (int cur = end_node; cur != start_node; cur = ancestor_node[cur]) {
                throughput = Math.min(throughput, network[ancestor_node[cur]].get(ancestor_edge[cur]).limit);
            }
            demand -= throughput;
            overall += (long) throughput * potential[end_node];

            for (int cur = end_node; cur != start_node; cur = ancestor_node[cur]) {
                Stream e = network[ancestor_node[cur]].get(ancestor_edge[cur]);
                e.limit -= throughput;
                network[cur].get(e.reverse).limit += throughput;
            }
        }
        return overall;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int M = scanner.nextInt();
        int K = scanner.nextInt();
        int C = scanner.nextInt();
        int D = scanner.nextInt();

        int[] demand_at = new int[58];
        ArrayList<Integer>[] connections = new ArrayList[58];
        for (int i = 0; i < 58; ++i) {
            connections[i] = new ArrayList<>();
        }

        for (int i = 0; i < K; ++i) {
            int x = scanner.nextInt();
            demand_at[x]++;
        }
        for (int i = 0; i < M; ++i) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            connections[u].add(v);
            connections[v].add(u);
        }

        for (int i = 0; i < CAPACITY; ++i) {
            network[i] = new ArrayList<>();
        }
        erase_structure(5103, 0, 5101);

        for (int i = 2; i <= N; ++i) {
            insert_link(0, i, demand_at[i], 0);
        }

        for (int stage = 0; stage <= 100; ++stage) {
            for (int place = 1; place <= N; ++place) {
                insert_link(50 * stage + place, 50 * (stage + 1) + place, K, 0);
                for (int neighbor : connections[place]) {
                    for (int k = 1; k <= K; ++k) {
                        insert_link(50 * stage + place, 50 * (stage + 1) + neighbor, 1, D * (2 * k - 1));
                    }
                }
            }
        }

        for (int stage = 1; stage <= 101; ++stage) {
            insert_link(50 * stage + 1, 5101, K, C * stage);
        }

        System.out.println(minimum_cost_flow(K));
    }
