            m = 0;
            Arrays.fill(first, -1);
            Arrays.fill(flo, 0);
        }

        void add_edge(int a, int b, long c, long p) {
            nxt[m] = first[ep[m] = a];
            first[ep[m]] = m;
            cap[m] = c;
            cost[m] = p;
            ++m;

            nxt[m] = first[ep[m] = b];
            first[ep[m]] = m;
            cap[m] = 0;
            cost[m] = -p;
            ++m;
        }

        int[] q = new int[N];
        int[] inq = new int[N];
        boolean[] vis = new boolean[N];
        long[] pot = new long[N];
        long[] dist = new long[N];

        void mcf_pot_init(int n) {
            Arrays.fill(pot, 0);
            for (int k = 1; k < n; ++k) {
                for (int e = 0; e < m; ++e) {
                    if (cap[e] > 0) {
                        pot[ep[e ^ 1]] = Math.min(pot[ep[e ^ 1]], pot[ep[e]] + cost[e]);
                    }
                }
            }
        }

        long mcf_update(int s, int t, long[] price, int n) {
            Arrays.fill(vis, false);
            Arrays.fill(dist, Long.MAX_VALUE / 2);
            dist[s] = 0;
            Arrays.fill(inq, -1);

            int qs = 0;
            inq[q[qs++] = s] = 0;

            while (qs > 0) {
                int u = q[0];
                inq[u] = -1;
