                    }
                    if (dist[q[j]] >= dist[q[i]]) {
                        break;
                    }
                    // Swap in q array
                    temp = q[i];
                    q[i] = q[j];
                    q[j] = temp;
                    // Swap in inq array
                    temp = inq[q[i]];
                    inq[q[i]] = inq[q[j]];
                    inq[q[j]] = temp;
                }

                if (vis[u]) {
                    continue;
                }
                vis[u] = true;

                for (int e = first[u]; e != -1; e = nxt[e]) {
                    int v = ep[e ^ 1];
                    if (flo[e] < cap[e] && dist[v] > dist[u] + pot[u] - pot[v] + cost[e]) {
