import java.util.*;

public class Main {
    static final int MX = 5500;
    static final long INF = 1_000_000_007L;

    static int n, m, k, c, d;
    static int u, v, mx, s = MX - 2, t = MX - 1, mf = 0;
    static long[] dis = new long[MX];
    static int[] tr = new int[MX];
    static long ans = 0;

    static class Edge {
        int v, c, ind, cap;
        Edge(int v, int c, int ind, int cap) {
            this.v = v;
            this.c = c;
            this.ind = ind;
            this.cap = cap;
        }
    }

    static List<Edge>[] adj = new List[MX];

    static void add_edge(int u, int v, int c, int cap) {
        int s1 = adj[u].size(), s2 = adj[v].size();
        adj[u].add(new Edge(v, c, s2, cap));
        adj[v].add(new Edge(u, -c, s1, 0));
    }

    static void dijkstra() {
        Arrays.fill(dis, INF);
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
        dis[s] = 0;
        pq.offer(new long[]{0, s});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            long dist = cur[0];
            int u = (int) cur[1];

            if (dist > dis[u]) continue;

            for (Edge ed : adj[u]) {
                if (ed.cap > 0 && dis[ed.v] > dist + ed.c) {
                    tr[ed.v] = ed.ind;
