        adjacencyList[from].add(flowEdges.size());
        flowEdges.add(new FlowEdge(to, capacity, 0, cost));
        adjacencyList[to].add(flowEdges.size());
        flowEdges.add(new FlowEdge(from, 0, 0, -cost));
    }

    static boolean computeShortestPath(int source, int sink) {
        Arrays.fill(shortestDist, INFINITY);
        Arrays.fill(predecessorNode, -1);
        Arrays.fill(predecessorEdge, -1);
        Arrays.fill(visitedQueue, false);

        Queue<Integer> q = new LinkedList<>();
        q.offer(source);
        shortestDist[source] = 0;
        visitedQueue[source] = true;

        while (!q.isEmpty()) {
            int u = q.poll();
            visitedQueue[u] = false;

            for (int idx : adjacencyList[u]) {
                FlowEdge e = flowEdges.get(idx);
                if (e.maxCap - e.currentFlow <= 0) continue;
                int v = e.target;
                long alt = shortestDist[u] + e.unitCost;
                if (alt < shortestDist[v]) {
                    shortestDist[v] = alt;
                    predecessorNode[v] = u;
                    predecessorEdge[v] = idx;
                    if (!visitedQueue[v]) {
                        visitedQueue[v] = true;
                        q.offer(v);
                    }
                }
            }
        }

        if (shortestDist[sink] == INFINITY) return false;

        int cur = sink;
        while (cur != source) {
            flowEdges.get(predecessorEdge[cur]).currentFlow++;
            flowEdges.get(predecessorEdge[cur] ^ 1).currentFlow--;
            cur = predecessorNode[cur];
        }

        return true;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int numVertices = scanner.nextInt();
        int numConnections = scanner.nextInt();
        int numCommodities = scanner.nextInt();
        int basePrice = scanner.nextInt();
        int timePenalty = scanner.nextInt();

        for (int i = 0; i < MAX_VERTEX; i++) {
            adjacencyList[i] = new ArrayList<>();
        }

        final int source = 9998;
        final int sink = 9999;

        for (int i = 0; i < numCommodities; i++) {
            int vertex = scanner.nextInt();
            vertex--;
            connectNodes(source, vertex, 1, 0);
        }

        for (int layer = 1; layer <= 101; layer++) {
            connectNodes((layer - 1) * numVertices, sink, numCommodities, (layer - 1) * basePrice);
        }

        for (int i = 0; i < numConnections; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            u--;
            v--;
            for (int layer = 1; layer <= 100; layer++) {
                for (int k = 1; k <= numCommodities; k++) {
                    int cost = timePenalty * ((k - 1) * 2 + 1);
                    connectNodes(u + (layer - 1) * numVertices, v + (layer - 1) * numVertices + numVertices, 1, cost);
                    connectNodes(v + (layer - 1) * numVertices, u + (layer - 1) * numVertices + numVertices, 1, cost);
                }
            }
        }

        for (int node = 0; node < numVertices; node++) {
            for (int layer = 1; layer <= 100; layer++) {
                connectNodes(node + (layer - 1) * numVertices, node + (layer - 1) * numVertices + numVertices, numCommodities, 0);
            }
        }

        long totalCost = 0;
        for (int i = 0; i < numCommodities; i++) {
            if (computeShortestPath(source, sink)) {
                totalCost += shortestDist[sink];
            }
        }

        System.out.println(totalCost);
    }
}

