#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <algorithm>
using namespace std;
using ll = long long;
using pii = pair<int, int>;

const int MAX_NODES = 5010;
const int INF = 1 << 30;

struct Edge {
    int to, capacity, cost, reverse;
};

class NetworkFlow {
public:
    int nodeCount;
    vector<Edge> edges[MAX_NODES];
    int potential[MAX_NODES];
    int distance[MAX_NODES];
    int parentVertex[MAX_NODES], parentEdge[MAX_NODES];

    void configure(int nodes) { nodeCount = nodes; }

    void connect(int from, int to, int cap, int cst) {
        edges[from].push_back({to, cap, cst, (int)edges[to].size()});
        edges[to].push_back({from, 0, -cst, (int)edges[from].size() - 1});
    }

    int compute(int source, int sink, int requiredFlow) {
        int result = 0;
        memset(potential, 0, sizeof(potential));
        while (requiredFlow > 0) {
            priority_queue<pii, vector<pii>, greater<pii>> pq;
            fill(distance, distance + nodeCount, INF);
            distance[source] = 0;
            pq.emplace(0, source);
            while (!pq.empty()) {
                auto [d, u] = pq.top(); pq.pop();
                if (distance[u] < d) continue;
                for (int i = 0; i < edges[u].size(); ++i) {
                    auto& e = edges[u][i];
                    if (e.capacity > 0 && distance[e.to] > distance[u] + e.cost + potential[u] - potential[e.to]) {
                        distance[e.to] = distance[u] + e.cost + potential[u] - potential[e.to];
                        parentVertex[e.to] = u;
                        parentEdge[e.to] = i;
                        pq.emplace(distance[e.to], e.to);
                    }
                }
            }
            if (distance[sink] == INF) return -1;
            for (int i = 0; i < nodeCount; ++i) potential[i] += distance[i];
            int flow = requiredFlow;
            for (int v = sink; v != source; v = parentVertex[v])
                flow = min(flow, edges[parentVertex[v]][parentEdge[v]].capacity);
