    static class Edge {
        int to, rev;
        int cap, cost;

        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static List<List<Edge>> graph;
    static int[] visited, current, dist, potential;
    static int node_count;

    static int add_node() {
        graph.add(new ArrayList<>());
        return node_count++;
    }

    static void add_edge(int u, int v, int cap, int cost) {
        graph.get(u).add(new Edge(v, graph.get(v).size(), cap, cost));
        graph.get(v).add(new Edge(u, graph.get(u).size() - 1, 0, -cost));
    }

    static boolean dijkstra(int s, int t) {
        Arrays.fill(dist, INF);
        Arrays.fill(visited, 0);
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{dist[s] = 0, s});
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int du = top[0], u = top[1];
            if (visited[u] == 1) continue;
            visited[u] = 1;
            for (Edge e : graph.get(u)) {
                int v = e.to;
                int dv = du + potential[u] + e.cost - potential[v];
                if (e.cap == 0 || visited[v] == 1 || dist[v] <= dv) continue;
                pq.offer(new int[]{dist[v] = dv, v});
            }
        }
        return visited[t] == 1;
    }

    static boolean dinic_bfs(int s, int t) {
        Arrays.fill(visited, 0);
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        visited[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (Edge e : graph.get(u)) {
                int v = e.to;
                if (visited[v] != 0 || e.cap == 0) continue;
                if (dist[v] != dist[u] + e.cost - potential[v] + potential[u]) continue;
                visited[v] = visited[u] + 1;
                q.offer(v);
            }
        }
        return visited[t] != 0;
    }

    static int dinic_dfs(int u, int t, int f) {
        if (u == t) return f;
        int pushed = 0;
        for (int i = current[u]; i < graph.get(u).size(); ++i) {
            current[u] = i;
            Edge e = graph.get(u).get(i);
