import java.util.*;
import java.io.*;

public class Main {
    static final int T = 99;
    static final int C = 12;

    static class Edge {
        int v, r;
        long f, c, p;
        Edge(int v, int r, long f, long c, long p) {
            this.v = v;
            this.r = r;
            this.f = f;
            this.c = c;
            this.p = p;
        }
    }

    static class Flow {
        static final int MAX_N = 50 * T + 2;
        static Edge[][] adj = new Edge[MAX_N][];
        static int[] sz = new int[MAX_N];
        static long mc = 0;

        static void init(int n) {
            mc = 0;
            for (int i = 0; i < n; i++) {
                sz[i] = 0;
                adj[i] = new Edge[0];
            }
        }

        static void add_edge(int a, int b, long c, long p) {
            mc = Math.max(mc, c);
            adj[a] = Arrays.copyOf(adj[a], sz[a] + 1);
            adj[a][sz[a]] = new Edge(b, sz[b], 0, c, p);
            sz[a]++;

            adj[b] = Arrays.copyOf(adj[b], sz[b] + 1);
            adj[b][sz[b]] = new Edge(a, sz[a] - 1, 0, 0, -p);
            sz[b]++;
        }

        static boolean[] vis = new boolean[MAX_N];
        static int[] par = new int[MAX_N];
        static long[] pot = new long[MAX_N];
        static long[] dist = new long[MAX_N];

        static void pot_init(int n) {
            Arrays.fill(pot, 0, n, 0);
            for (int i = 1; i < n; i++) {
                for (int u = 0; u < n; u++) {
                    for (int j = 0; j < sz[u]; j++) {
                        Edge e = adj[u][j];
                        if (e.c > 0) {
                            pot[e.v] = Math.min(pot[e.v], pot[u] + e.p);
                        }
                    }
                }
            }
        }

        static long mcf(int s, int t, long[] price, int n, boolean sparse, long lb) {
            Arrays.fill(vis, 0, n, false);
            Arrays.fill(dist, 0, n, Long.MAX_VALUE / 2);
            dist[s] = 0;

            if (sparse) {
                PriorityQueue<long[]> dk = new PriorityQueue<>((a, b) -> Long.compare(b[0], a[0]));
                dk.offer(new long[]{0, s});
                while (!dk.isEmpty()) {
                    long[] cur = dk.poll();
                    int u = (int) cur[1];
                    if (vis[u]) continue;
                    for (int j = 0; j < sz[u]; j++) {
                        Edge e = adj[u][j];
                        if (e.f <= e.c - lb && dist[e.v] > dist[u] + pot[u] - pot[e.v] + e.p) {
                            dist[e.v] = dist[u] + pot[u] - pot[e.v] + e.p;
                            par[e.v] = e.r;
                            dk.offer(new long[]{-dist[e.v], e.v});
                        }
                    }
                }
            } else {
                for (int u = s; u != -1; ) {
                    vis[u] = true;
                    for (int j = 0; j < sz[u]; j++) {
                        Edge e = adj[u][j];
                        if (e.f <= e.c - lb && dist[e.v] > dist[u] + pot[u] - pot[e.v] + e.p) {
                            dist[e.v] = dist[u] + pot[u] - pot[e.v] + e.p;
                            par[e.v] = e.r;
                        }
                    }
                    u = -1;
                    long best = Long.MAX_VALUE / 2;
                    for (int i = 0; i < n; i++) {
                        if (!vis[i] && dist[i] < best) {
                            best = dist[u = i];
                        }
                    }
                }
            }

            if (dist[t] >= Long.MAX_VALUE / 2) {
                return 0;
            }
            long df = Long.MAX_VALUE / 2;
            for (int u = t; u != s; ) {
                Edge r = adj[u][par[u]];
                df = Math.min(df, adj[r.v][r.r].c - adj[r.v][r.r].f);
                u = r.v;
            }
            for (int u = t; u != s; ) {
                Edge r = adj[u][par[u]];
                Edge e = adj[r.v][r.r];
                e.f += df;
                r.f -= df;
                price[0] += df * e.p;
                u = r.v;
            }
            for (int i = 0; i < n; i++) {
                pot[i] = Math.min(Long.MAX_VALUE / 2, dist[i] + pot[i]);
            }
            return df;
        }

        static long min_cost_flow(int s, int t, long[] price, int n, boolean sparse) {
            pot_init(n);
            long flow = 0;
            price[0] = 0;
            for (long lb = 1L << 30; lb > 0; lb /= 2) {
                while (true) {
                    long df = mcf(s, t, price, n, sparse, lb);
                    if (df == 0) break;
                    flow += df;
                }
            }
            return flow;
        }
    }

