        visited[u] = true;
        int pushed = 0, left = flow;

        for (int i = head[u]; i != 0; i = edge[i].next) {
            int v = edge[i].dest, cap = edge[i].cap;
            if (visited[v] || cap == 0 || dist[v] != dist[u] + edge[i].cost) continue;
            int f = dfs_flow(v, Math.min(left, cap), visited);
            if (f > 0) {
                left -= f;
                edge[i].cap -= f;
                edge[i ^ 1].cap += f;
                pushed += f;
                if (left == 0) break;
            }
        }
        return pushed;
    }

    static int min_cost_flow() {
        int total = 0;
        while (bfs_shortest_path()) {
            boolean[] visited = new boolean[dst + 1];
            int flow = dfs_flow(src, INF, visited);
            if (flow > 0) total += flow * dist[dst];
        }
        return total;
    }

