                this.reverse = reverse;
                this.flow = flow;
                this.capacity = capacity;
                this.weight = weight;
            }
        }

        List<List<Connection>> graph;

        MinCostMaxFlow(int n) {
            vertexCount = n;
            distance = new long[n];
            potential = new long[n];
            bottleneck = new long[n];
            prevEdge = new int[n];
            prevVertex = new int[n];
            graph = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                graph.add(new ArrayList<>());
            }
            minHeap = new PriorityQueue<>(Comparator.comparingLong((Pair p) -> p.cost).thenComparingInt(p -> p.vertex));
        }

        void link(int u, int v, long cap, long cost) {
            graph.get(u).add(new Connection(v, graph.get(v).size(), 0, cap, cost));
            graph.get(v).add(new Connection(u, graph.get(u).size() - 1, 0, 0, -cost));
        }

        long[] minCostFlow(int source, int sink) {
            long totalFlow = 0;
            long totalCost = 0;

            while (true) {
                minHeap.add(new Pair(0, source));
                Arrays.fill(distance, INF_FLOW);
                distance[source] = 0;
                bottleneck[source] = INF_FLOW;

                while (!minHeap.isEmpty()) {
                    Pair top = minHeap.poll();
                    long dist = top.cost;
                    int u = top.vertex;

                    if (dist != distance[u]) continue;

                    for (int idx = 0; idx < graph.get(u).size(); ++idx) {
                        Connection edge = graph.get(u).get(idx);
                        int v = edge.target;

                        if (edge.capacity <= edge.flow) continue;

                        long newDist = distance[u] + edge.weight + potential[u] - potential[v];
                        if (distance[v] > newDist) {
                            distance[v] = newDist;
                            minHeap.add(new Pair(newDist, v));
                            prevVertex[v] = u;
                            prevEdge[v] = idx;
                            bottleneck[v] = Math.min(bottleneck[u], edge.capacity - edge.flow);
                        }
