                    for (int i = 0; i < g.get(u).size(); i++) {
                        Edge e = g.get(u).get(i);
                        int v = e.to;

                        if (e.flow >= e.cap) continue;

                        int nd = dist[u] + e.cost + pot[u] - pot[v];
                        if (dist[v] > nd) {
                            dist[v] = nd;
                            pq.offer(new int[]{nd, v});
                            parNode[v] = u;
