    static class MCMFGraph extends GraphBase {
        static class PQItem implements Comparable<PQItem> {
            int trg;
            long prio;

            PQItem(int trg, long prio) {
                this.trg = trg;
                this.prio = prio;
            }

            @Override
            public int compareTo(PQItem other) {
                return Long.compare(this.prio, other.prio);
            }
        }

        MCMFGraph(int size) {
            super(size);
