        void add(int a, int b, long cost, long cap, long rcap) {
            if (a == b) return;
            if (cap > 0 && rcap > 0) {
                add(a, b, cost, cap, 0);
                add(b, a, cost, cap, 0);
            } else if (rcap > 0) {
                add(b, a, cost, rcap, 0);
            } else {
                int da = size(a);
                int db = size(b);
                Node nodeA = get(a);
                Node nodeB = get(b);
                nodeA.edges.add(new Edge(b, cost, cap, db));
                nodeB.edges.add(new Edge(a, -cost, 0, da));
            }
        }

        long[] augment(int source, int sink) {
            int N = size();
            long big = Long.MAX_VALUE;
            long[] upby = new long[N];
            long[] prio = new long[N];
