        return nodes[id];
    }

    explicit GraphBase(std::size_t sz = 0) : nodes(sz) {}
};

template<typename NodeType = SimpleNode<SimpleEdge> >
class UGGraph : public GraphBase<SimpleEdge, NodeType>
{
public:
