using ll = long long;

struct MCF {
  struct Edge {
    int to;
    ll cap;
    ll cost;
    int rev;
  };

  vector<vector<Edge>> graph;
  int n;

public:
  MCF(int nodes) : n(nodes), graph(nodes) {}

  void add_edge(int from, int to, ll capacity, ll cost) {
    graph[from].emplace_back(Edge{to, capacity, cost, (int)graph[to].size()});
    graph[to].emplace_back(Edge{from, 0, -cost, (int)graph[from].size() - 1});
  }

  ll solve(int source, int sink, ll flow_needed) {
    vector<ll> dist(n, 1e18), potential(n, 0);
    vector<int> prev_node(n), prev_edge(n);

    ll total_cost = 0;
    while (flow_needed > 0) {
      priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
      dist.assign(n, 1e18);
      dist[source] = 0;
      pq.emplace(0, source);

      while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (int i = 0; i < graph[u].size(); ++i) {
          auto& e = graph[u][i];
          if (e.cap > 0 && dist[e.to] > dist[u] + e.cost + potential[u] - potential[e.to]) {
            dist[e.to] = dist[u] + e.cost + potential[u] - potential[e.to];
            prev_node[e.to] = u;
            prev_edge[e.to] = i;
            pq.emplace(dist[e.to], e.to);
          }
        }
      }

      if (dist[sink] == 1e18) return -1;
      for (int i = 0; i < n; ++i) potential[i] += dist[i];

      ll flow = flow_needed;
      for (int v = sink; v != source; v = prev_node[v]) {
        flow = min(flow, graph[prev_node[v]][prev_edge[v]].cap);
      }

      flow_needed -= flow;
      total_cost += flow * potential[sink];

      for (int v = sink; v != source; v = prev_node[v]) {
        auto& e = graph[prev_node[v]][prev_edge[v]];
        e.cap -= flow;
        graph[v][e.rev].cap += flow;
      }
    }
    return total_cost;
  }
};

int main() {
