inline void readInt(int &x) {
    x = 0;
    char c = getchar();
    while (c < '0' || c > '9') {
        if (c == '-') break;
        c = getchar();
    }
    bool neg = false;
    if (c == '-') {
        neg = true;
        c = getchar();
    }
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
    if (neg) x = -x;
}

