        }

        int[] spfa() {
            Arrays.fill(dist, INF);
            dist[source] = 0;
            boolean[] inq = new boolean[adj.size()];
            Queue<Integer> q = new LinkedList<>();
            q.offer(source);
            inq[source] = true;

            while (!q.isEmpty()) {
                int u = q.poll();
                inq[u] = false;

                for (int i = 0; i < adj.get(u).size(); ++i) {
                    Edge e = adj.get(u).get(i);
                    if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost) {
