                        preve[e.to] = i;
                        if (!inq[e.to]) {
                            inq[e.to] = true;
                            q.offer(e.to);
                        }
                    }
                }
            }

            if (dist[sink] == INF) {
                return new int[]{0, 0};
            }

            int flow = INF;
            for (int v = sink; v != source; v = prevv[v]) {
                flow = Math.min(flow, adj.get(prevv[v]).get(preve[v]).capacity);
