            for (int v = sink; v != source; v = prevv[v]) {
                Edge e = adj.get(prevv[v]).get(preve[v]);
                e.capacity -= flow;
                adj.get(v).get(e.rev).capacity += flow;
            }

            return new int[]{dist[sink] * flow, 1};
        }
    }

