#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

const int INF = 0x3f3f3f3f;
const int MOD = 1000000007;
const int MAX_TIME = 100;
const int MAX_NODES = MAX_TIME * MAX_TIME;
const int MAX_EDGES = MAX_NODES * MAX_NODES;

struct Edge {
    int to, cap, cost, rev;
    Edge(int t, int c, int co, int r) : to(t), cap(c), cost(co), rev(r) {}
};

vector<vector<Edge>> graph;
vector<int> dist, prevv, preve;

void add_edge(int from, int to, int cap, int cost) {
    graph[from].emplace_back(to, cap, cost, graph[to].size());
    graph[to].emplace_back(from, 0, -cost, graph[from].size() - 1);
}

bool spfa(int s, int t) {
    fill(dist.begin(), dist.end(), INF);
    queue<int> q;
    vector<bool> inq(graph.size(), false);
    dist[s] = 0;
    q.push(s);
    inq[s] = true;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = false;
        for (int i = 0; i < graph[u].size(); ++i) {
            auto& e = graph[u][i];
            if (e.cap > 0 && dist[e.to] > dist[u] + e.cost) {
                dist[e.to] = dist[u] + e.cost;
                prevv[e.to] = u;
                preve[e.to] = i;
                if (!inq[e.to]) {
                    inq[e.to] = true;
                    q.push(e.to);
                }
            }
        }
    }
    return dist[t] < INF;
}

int min_cost_flow(int s, int t) {
    int flow = 0, cost = 0;
    while (spfa(s, t)) {
        int f = INF;
        for (int v = t; v != s; v = prevv[v]) {
            f = min(f, graph[prevv[v]][preve[v]].cap);
        }
        flow += f;
        cost += dist[t] * f;
        for (int v = t; v != s; v = prevv[v]) {
            auto& e = graph[prevv[v]][preve[v]];
            e.cap -= f;
            graph[v][e.rev].cap += f;
        }
    }
    return cost;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

