    dist.resize(sink + 1);
    prevv.resize(sink + 1);
    preve.resize(sink + 1);

    // Connect each node's last time layer to sink with capacity 100, cost 0
    for (int i = 1; i <= n; ++i) {
        add_edge((i - 1) * MAX_TIME + MAX_TIME, sink, 100, 0);
    }

    // Connect source to starting positions at time 1
    for (int i = 0; i < k; ++i) {
