        add_edge(source, (v - 1) * MAX_TIME + 1, 1, 0);
    }

    // Time progression edges within each node
    for (int i = 1; i <= n; ++i) {
        for (int t = 1; t < MAX_TIME; ++t) {
            add_edge((i - 1) * MAX_TIME + t, (i - 1) * MAX_TIME + t + 1, 100, c);
        }
    }

