        to[++edge_idx] = u;
        next_edge[edge_idx] = first[v];
        first[v] = edge_idx;
        cap[edge_idx] = 0;
        wgt[edge_idx] = -weight;
    }

    static boolean find_path() {
        Arrays.fill(min_flow, 0);
        Arrays.fill(dist, INF);
        Arrays.fill(inq, false);
        Queue<Integer> q = new LinkedList<>();
        q.push(src);
        min_flow[src] = INF;
        dist[src] = 0;
        inq[src] = true;

        while (!q.isEmpty()) {
            int u = q.poll();
            inq[u] = false;
            for (int e = first[u]; e != 0; e = next_edge[e]) {
                if (cap[e] == 0 || dist[to[e]] <= dist[u] + wgt[e]) continue;
                dist[to[e]] = dist[u] + wgt[e];
                min_flow[to[e]] = Math.min(min_flow[u], cap[e]);
                parent_edge[to[e]] = e;
                if (!inq[to[e]]) {
                    inq[to[e]] = true;
                    q.push(to[e]);
                }
            }
        }
        return dist[dst] != INF;
    }

    static void push_flow() {
        int f = min_flow[dst];
        int cur = dst;
        while (cur != src) {
            int e = parent_edge[cur];
            cap[e] -= f;
            cap[e ^ 1] += f;
            cur = to[e ^ 1];
        }
        min_cost += f * dist[dst];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        dst = (n + k - 1) * n + 1;

        for (int i = 1; i <= k; i++) {
            int x = sc.nextInt();
            connect(src, x, 1, 0);
        }

        for (int i = 1; i <= m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            for (int layer = 1; layer <= n + k; layer++) {
                for (int hop = 1; hop <= k; hop++) {
                    int weight = d * hop * 2 - d + c;
                    connect(u + (layer - 1) * n, v + layer * n, 1, weight);
                    connect(v + (layer - 1) * n, u + layer * n, 1, weight);
                }
            }
        }

        for (int layer = 1; layer < n + k; layer++) {
            for (int node = 2; node <= n; node++) {
                connect(node + (layer - 1) * n, node + layer * n, 1000000000, c);
            }
            connect(1 + (layer - 1) * n, 1 + layer * n, 1000000000, 0);
        }

        while (find_path()) {
            push_flow();
        }

        System.out.println(min_cost);
        sc.close();
    }
}

