    cin.tie(0);

    int n,m,k,c,d,u,v;
    cin >> n >> m >> k >> c >> d;
    min_cost_max_flow<int,int> g((n+2)*102);
    for(int i=0;i<102;i++)
        g.add_edge((i*(n+2))+1,i*(n+2),100,(i*c));
    for(int i=0;i<101;i++)
        for(int j=0;j<n+1;j++)
            g.add_edge(j+(i*(n+2)),j+((i+1)*(n+2)),100,0);
    for(int i=0;i<k;i++)
    {
