public class Main {
    static class Edge {
        int src, dst, rev;
        long flow, cap;
        long cost;
        Edge(int src, int dst, int rev, long flow, long cap, long cost) {
            this.src = src;
            this.dst = dst;
            this.rev = rev;
            this.flow = flow;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MinCostMaxFlow {
        int n;
        List<List<Edge>> adj;
        long[] potential;
        long[] dist;
        Edge[] back;
        final long oo = Long.MAX_VALUE;

        MinCostMaxFlow(int n) {
            this.n = n;
            adj = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }
            potential = new long[n];
            dist = new long[n];
            back = new Edge[n];
        }

        void addEdge(int src, int dst, long cap, long cost) {
            adj.get(src).add(new Edge(src, dst, adj.get(dst).size(), 0, cap, cost));
            if (src == dst) {
                adj.get(src).get(adj.get(src).size() - 1).rev++;
            }
            adj.get(dst).add(new Edge(dst, src, adj.get(src).size() - 1, 0, 0, -cost));
        }

        long rcost(Edge e) {
            return e.cost + potential[e.src] - potential[e.dst];
        }

        long dijkstra(int source, int sink) {
            Arrays.fill(dist, oo);
            PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a.cost));
            dist[source] = 0;
            pq.offer(new Node(0, source));

            while (!pq.isEmpty()) {
                Node node = pq.poll();
                if (dist[node.vertex] < node.cost) continue;
