                    if (dist[u] < dist[sink]) {
                        potential[u] += dist[u] - dist[sink];
                    }
                }

                long f = Long.MAX_VALUE;
                for (Edge e = back[sink]; e != null; e = back[e.src]) {
                    f = Math.min(f, e.cap - e.flow);
                }

                for (Edge e = back[sink]; e != null; e = back[e.src]) {
                    e.flow += f;
                    adj.get(e.dst).get(e.rev).flow -= f;
                }

                flow += f;
                cost += f * (potential[sink] - potential[source]);
            }

            return new long[]{flow, cost};
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        MinCostMaxFlow g = new MinCostMaxFlow((n + 2) * 102);

        for (int i = 0; i < 102; i++) {
            g.addEdge(i * (n + 2) + 1, i * (n + 2), 100, (long) i * c);
        }

        for (int i = 0; i < 101; i++) {
            for (int j = 0; j < n + 1; j++) {
                g.addEdge(j + i * (n + 2), j + (i + 1) * (n + 2), 100, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            int u = sc.nextInt();
            g.addEdge(n + 1, u, 1, 0);
        }

        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
