                for (int f = 0; f < k; f++) {
                    g.addEdge(u + j * (n + 2), v + (j + 1) * (n + 2), 1, (long) ((2 * f) + 1) * d);
                    g.addEdge(v + j * (n + 2), u + (j + 1) * (n + 2), 1, (long) ((2 * f) + 1) * d);
                }
            }
        }

        long[] result = g.maxFlow(n + 1, 101 * (n + 2));
        System.out.println(result[1]);
    }
}

