        }

        connect(getNode(t + 1, 1), sink_node, Integer.MAX_VALUE, c * (t + 1));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        k = scanner.nextInt();
        c = scanner.nextInt();
        d = scanner.nextInt();
        total_nodes = n + 2;

        for (int i = 1; i <= k; ++i) {
            int a = scanner.nextInt();
            connect(source_node, getNode(0, a), 1, 0);
        }

        for (int i = 1; i <= n; ++i) {
            adj_list[i] = new ArrayList<>();
        }

