struct Edge {
    int to, cap, cost, type;
    Edge(int t, int c, int co, int ty) : to(t), cap(c), cost(co), type(ty) {}
};

vector<Edge> edges;
vector<int> graph[MAX_NODES];
int dist[MAX_NODES], prevv[MAX_NODES], preve[MAX_NODES], inq[MAX_NODES];
int queue_arr[MAX_NODES * 10];
int node_count, sink_node, C_param, d_param;

void init_graph(int n) {
    node_count = n;
    sink_node = n - 1;
    for (int i = 0; i < n; ++i) graph[i].clear();
    edges.clear();
}

void add_edge(int from, int to, int cap, int cost, int type) {
    graph[from].push_back(edges.size());
    edges.emplace_back(to, cap, cost, type);
    graph[to].push_back(edges.size());
    if (type == 1) {
        edges.emplace_back(from, 0, -C_param + d_param, type);
    } else {
        edges.emplace_back(from, 0, -cost, type);
    }
}

int spfa() {
    fill(dist, dist + node_count, INT_MAX);
    fill(inq, inq + node_count, 0);
    dist[0] = 0;
    int qh = 0, qt = 0;
    queue_arr[qt++] = 0;

