                if (!inq[e.to]) {
                    inq[e.to] = 1;
                    queue_arr[qt++] = e.to;
                }
            }
        }
    }

    if (dist[sink_node] == INT_MAX) return -1;

    int cur = sink_node;
    while (cur != 0) {
        int idx = preve[cur];
        if (edges[idx].type == 1) {
            if (idx & 1) {
                edges[idx].cost += 2 * d_param;
                edges[idx ^ 1].cost -= 2 * d_param;
