public class Main {
    static final int MOD = 1000000007;
    static final int MAX_NODES = 100000;
    static final int MAX_EDGES = 1000000;

    static class Edge {
        int dest, cap, cost, typ;
        Edge(int d, int c, int co, int t) {
            dest = d;
            cap = c;
            cost = co;
            typ = t;
        }
    }

    static List<Edge> edge_vec = new ArrayList<>();
    static List<Integer>[] adj;
    static int[] dist, prevv, preve, inq;
    static int[] qbuf;
    static int N, T, C_val, d_val;

    static void init(int n) {
        N = n;
        T = n - 1;
        adj = new List[n];
        for (int i = 0; i < n; ++i) {
            adj[i] = new ArrayList<>();
        }
        edge_vec.clear();
    }

    static void link(int u, int v, int c, int w, int t) {
        adj[u].add(edge_vec.size());
        edge_vec.add(new Edge(v, c, w, t));
        adj[v].add(edge_vec.size());
        if (t == 1) {
            edge_vec.add(new Edge(u, 0, -C_val + d_val, t));
        } else {
            edge_vec.add(new Edge(u, 0, -w, t));
        }
    }

    static int spfa_search() {
        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(inq, 0);
        dist[0] = 0;
        int h = 0, t = 0;
        qbuf[t++] = 0;

        while (h < t) {
            int u = qbuf[h++];
            inq[u] = 0;
            for (int idx : adj[u]) {
                Edge e = edge_vec.get(idx);
                if (e.cap > 0 && dist[u] != Integer.MAX_VALUE && dist[u] + e.cost < dist[e.dest]) {
                    dist[e.dest] = dist[u] + e.cost;
                    prevv[e.dest] = u;
                    preve[e.dest] = idx;
                    if (inq[e.dest] == 0) {
                        inq[e.dest] = 1;
                        qbuf[t++] = e.dest;
                    }
                }
            }
        }

        if (dist[T] == Integer.MAX_VALUE) return -1;

        int cur = T;
        while (cur != 0) {
            int idx = preve[cur];
            if (edge_vec.get(idx).typ == 1) {
                if (idx % 2 == 1) {
                    edge_vec.get(idx).cost += 2 * d_val;
                    edge_vec.get(idx ^ 1).cost -= 2 * d_val;
                } else {
                    edge_vec.get(idx).cost += 2 * d_val;
                    edge_vec.get(idx ^ 1).cost -= 2 * d_val;
                }
            }
            edge_vec.get(idx).cap--;
            edge_vec.get(idx ^ 1).cap++;
            cur = prevv[cur];
        }
        return dist[T];
    }

