        Arrays.fill(dist, Long.MAX_VALUE);
        Arrays.fill(prevV, -1);
        Arrays.fill(prevE, -1);
        Arrays.fill(inQ, false);

        dist[source] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(source);
        inQ[source] = true;

        while (!q.isEmpty()) {
            int u = q.poll();
            inQ[u] = false;

