                int v = edgeVec.get(idx).from;
                int w = edgeVec.get(idx).cost;
                if (dist[v] > dist[u] + w) {
                    dist[v] = dist[u] + w;
                    prevV[v] = u;
                    prevE[v] = idx;
                    if (!inQ[v]) {
