                if (e.c > e.f && dist[v] > dist[u] + e.d) {
                    dist[v] = dist[u] + e.d;
                    parentEdge[v] = idx;
                    flow[v] = Math.min(flow[u], e.c - e.f);
                    if (inq[v] == 0) {
