{
    if (a.empty()) {
        answer(0);
        return;
    }

    unsigned min_val = std::numeric_limits<unsigned>::max();
    unsigned max_val = 0;

    for (const auto& x : a) {
        if (x < min_val) min_val = x;
        if (x > max_val) max_val = x;
    }

    answer(min_val + (max_val - min_val) / 2);
}

