    static class BFS_Graph {
        List<List<int[]>> E;
        int[] IN;
        int N;

        public int is_cycle() {
            for (int i = 1; i <= N; i++) {
                if (IN[i] > 0) return 1;
            }
            return 0;
        }

        public BFS_Graph(int n) {
            N = n;
            E = new ArrayList<>();
            for (int i = 0; i <= n; i++) {
                E.add(new ArrayList<>());
            }
            IN = new int[n + 1];
        }

        public void insert(int u, int v, int w) {
            E.get(u).add(new int[]{v, w});
            IN[v]++;
        }

        public void insert_fb(int u, int v, int w) {
            E.get(u).add(new int[]{v, w});
            E.get(v).add(new int[]{u, w});
        }

        public long[] bfs(int start, int end, int min_weight) {
            boolean[] visited = new boolean[N + 1];
            long[] weight = new long[N + 1];
            Arrays.fill(weight, INF_LONG);
            Queue<Integer> Q = new LinkedList<>();
            visited[start] = true;
            weight[start] = 0;
            Q.offer(start);
            while (!Q.isEmpty()) {
                int u = Q.poll();
                long w = weight[u];
                if (u == end) break;
                for (int[] edge : E.get(u)) {
                    int v = edge[0];
                    int c = edge[1];
                    if (c >= min_weight && !visited[v]) {
                        Q.offer(v);
                        weight[v] = w + c;
                        visited[v] = true;
                    }
                }
            }
            return weight;
        }

        public List<Integer> topologicalSort() {
            List<Integer> order = new ArrayList<>();
            Queue<Integer> Q = new LinkedList<>();
            for (int i = 1; i <= N; i++) {
                if (IN[i] == 0) Q.offer(i);
            }
            while (!Q.isEmpty()) {
                int u = Q.poll();
                order.add(u);
                for (int[] edge : E.get(u)) {
                    int v = edge[0];
                    if (IN[v] > 0) {
                        IN[v]--;
                        if (IN[v] == 0) Q.offer(v);
                    }
                }
            }
            return order;
        }

        public List<Integer> topologicalSortPQ() {
            List<Integer> order = new ArrayList<>();
            PriorityQueue<Integer> pq = new PriorityQueue<>(Collections.reverseOrder());
            for (int i = 1; i <= N; i++) {
                if (IN[i] == 0) pq.offer(-i);
            }
            while (!pq.isEmpty()) {
                int u = -pq.poll();
                order.add(-u);
                for (int[] edge : E.get(u)) {
                    int v = edge[0];
                    if (IN[v] > 0) {
                        IN[v]--;
                        if (IN[v] == 0) pq.offer(-v);
                    }
                }
            }
            return order;
        }

        public int f() {
            int v, u, i;
            int[] IN2 = new int[N + 1];
            for (u = 1; u <= N; u++) {
                for (int[] edge : E.get(u)) {
                    v = edge[0];
                    if (IN[v] == 1) {
                        System.arraycopy(IN, 0, IN2, 0, IN.length);
                        IN[v]--;
                        topologicalSort();
                        if (is_cycle() == 0) return 1;
                        System.arraycopy(IN2, 0, IN, 0, IN.length);
                    }
                }
            }
            return 0;
        }

