    static class Comb {
        List<List<Long>> C;
        List<Long> F;
        int N;

        public Comb() {
        }

        public Comb(int n) {
            init(n);
        }

        public void init(int n) {
            N = n;
            C = new ArrayList<>();
            for (int i = 0; i <= N; i++) {
                C.add(new ArrayList<>());
                for (int j = 0; j <= i; j++) {
                    C.get(i).add(0L);
                }
            }
            for (int i = 0; i <= N; i++) {
                C.get(i).set(i, 1L);
                C.get(i).set(0, 1L);
            }
            for (int i = 1; i <= N; i++) {
                for (int j = 1; j < i; j++) {
                    C.get(i).set(j, (C.get(i - 1).get(j - 1) + C.get(i - 1).get(j)) % MOD);
                }
            }
            F = new ArrayList<>();
            for (int i = 0; i <= N; i++) F.add(0L);
            F.set(0, 1L);
            F.set(1, 1L);
            for (int i = 1; i <= n; i++) {
                F.set(i, (F.get(i - 1) * i) % MOD);
            }
        }

        public long getC(int n, int r) {
            return C.get(n).get(r);
        }

        public long getF(int n) {
            return F.get(n);
        }

        public long get_comb(int n, int r) {
            if (n == r || r == 0) return 1;
            if (n <= 1000) return getC(n, r);
            long ret = 1;
            int i;
            if (r > n / 2) r = n - r;
            for (i = n; i > n - r; i--) ret *= i;
            for (i = 2; i <= r; i++) ret /= i;
            return ret;
        }
    }

    static class Sort {
