        }

        public void merge_sort(List<Integer> x, int lo, int hi) {
            if (lo >= hi) return;
            int i, j, k, mid = (lo + hi) / 2;
            merge_sort(x, lo, mid);
            merge_sort(x, mid + 1, hi);
            for (i = lo, j = mid + 1, k = lo; i <= mid && j <= hi; k++) {
                if (x.get(i) < x.get(j)) {
                    tmp.set(k, x.get(i++));
                } else {
                    tmp.set(k, x.get(j++));
                }
            }
            if (i <= mid) {
                for (; i <= mid; i++, k++) tmp.set(k, x.get(i));
            }
            if (j <= hi) {
                for (; j <= hi; j++, k++) tmp.set(k, x.get(j));
            }
            for (i = lo; i <= hi; i++) x.set(i, tmp.get(i));
        }
    }

