    static class DisjointSet {
        int N;
        List<Integer> P, R, A;

        public DisjointSet(int n) {
            N = n;
            P = new ArrayList<>();
            R = new ArrayList<>();
            A = new ArrayList<>();
            for (int i = 0; i <= n; i++) {
                P.add(0);
                R.add(0);
                A.add(0);
            }
            for (int i = 1; i <= n; i++) {
                P.set(i, i);
                R.set(i, 0);
                A.set(i, 1);
            }
        }

        public int getA(int x) {
            return A.get(x);
        }

        public int find_set(int x) {
            if (P.get(x) == x) return x;
            int pa = find_set(P.get(x));
            P.set(x, pa);
            return pa;
        }

        public int union_set(int x, int y) {
            int px, py;
            px = find_set(x);
            py = find_set(y);
            if (px == py) return px;
            if (R.get(px) > R.get(py)) {
                P.set(py, px);
                A.set(px, A.get(px) + A.get(py));
                return px;
            } else {
                P.set(px, py);
                A.set(py, A.get(py) + A.get(px));
                if (R.get(px) == R.get(py)) R.set(py, R.get(py) + 1);
                return py;
            }
        }
    }

