                    if (idx < 0) idx = -idx - 1;
                    v.set(idx, A.get(i));
                    if (idx != 0) {
                        p.set(i, v1.get(idx - 1));
                    }
                    v1.set(idx, i);
                }
            }
            len[0] = v1.size();
            for (i = 0; i < len[0]; i++) ret.add(0);
            for (i = v1.get(v1.size() - 1), j = len[0] - 1; i != -1; i = p.get(i), j--) {
                ret.set(j, A.get(i));
            }
            return ret;
        }

