            int i, j, ret = 0;
            List<Integer> v = new ArrayList<>();
            for (i = 0; i < N; i++) v.add(0);
            for (i = 0; i < A.size(); i++) {
                for (j = 0; j < i; j++) {
                    if (A.get(j) < A.get(i) && v.get(i) < v.get(j)) v.set(i, v.get(j));
                }
                v.set(i, v.get(i) + 1);
            }
            for (i = 0; i < v.size(); i++) {
