    static class Point implements Comparable<Point> {
        int x, y, mx;

        public Point() {
        }

        public Point(int x, int y, int mx) {
            this.x = x;
            this.y = y;
            this.mx = mx;
        }

        @Override
        public int compareTo(Point other) {
