        public List<int[]> make(String str, int[] root) {
            int i, cur = 1;
            List<int[]> E = new ArrayList<>();
            for (i = 0; i < 10000; i++) E.add(new int[2]);
            Stack<Integer> S = new Stack<>();
            for (i = 0; i < str.length(); i++) {
                char cc = str.charAt(i);
                if (cc >= '1' && cc <= '9') {
                    E.get(cur)[0] = cc - '0';
                    E.get(cur)[1] = 0;
                    S.push(cur);
                    cur++;
                } else if (cc == ')') {
                    int a = S.pop();
                    int b = S.pop();
                    E.get(cur)[0] = a;
                    E.get(cur)[1] = b;
                    S.push(cur);
                    cur++;
                }
            }
            root[0] = cur - 1;
            return E;
        }
    }

