public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[1005];

        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        // Sort in descending order
        Integer[] tempArr = new Integer[n];
        for (int i = 0; i < n; i++) {
            tempArr[i] = arr[i];
