        Arrays.sort(tempArr, Collections.reverseOrder());

        // Copy back to original array
        for (int i = 0; i < n; i++) {
            arr[i] = tempArr[i];
        }

        if (n >= 2) {
            System.out.println(arr[n - 1 - n/2]);
        } else {
            System.out.println(arr[0]);
        }
    }
}

