public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] a = new int[11]; // indices 1 to 10
        int n = scanner.nextInt();

        for (int i = 1; i <= n; i++) {
            a[i] = scanner.nextInt();
        }

        // Find median using nth_element equivalent
        // We need to find the element at position (n-1)/2 in 0-based indexing
        // Since our array is 1-based, we work with indices 1 to n
        // The median position in 1-based is 1 + (n-1)/2
        // In 0-based terms for the subarray from index 1 to n, it's position (n-1)/2

        // Convert to 0-based for Arrays.sort or use nth_element logic
        // Since Java doesn't have nth_element, we'll use a partial sort approach
        // For small arrays, sorting is acceptable

        // Create a temporary array for the elements we care about (indices 1 to n)
        int[] temp = new int[n];
        for (int i = 0; i < n; i++) {
            temp[i] = a[i + 1];
        }

        // Sort and find the median
        Arrays.sort(temp);
        int medianIndex = (n - 1) / 2;
        System.out.println(temp[medianIndex]);
    }
}

