import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] a = new int[6];
        int n = sc.nextInt();
        int i, j, t;

        if (n - 0 > 0) a[0] = sc.nextInt();
        if (n - 1 > 0) a[1] = sc.nextInt();
        if (n - 2 > 0) a[2] = sc.nextInt();
        if (n - 3 > 0) a[3] = sc.nextInt();
        if (n-- == 5) a[4] = sc.nextInt();

        // Bubble sort
        for (i = 0; i <= n - 1; i++) {
            for (j = 0; j <= n - i - 1; j++) {
                if (a[j] > a[j + 1]) {
                    int temp = a[j];
                    a[j] = a[j + 1];
                    a[j + 1] = temp;
                }
            }
        }

        t = (a[0] + a[n]) >> 1;
        i = -1;
        j = n + 1;

        while (i < n && a[++i] <= t);
        while (j > 0 && a[--j] >= t);

        int result;
        if (a[i] - t < t - a[j] && a[i - 1] - t > a[i] - t) {
            result = a[i];
        } else if (i - 1 >= 0 && a[i - 1] - t < t - a[j] && a[i - 1] - t < t - a[j]) {
            result = a[i - 1];
        } else {
            result = a[j];
        }

        System.out.println(result);
    }
}

