public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] a = new int[n + 1];
        for (int i = 1; i <= n; ++i) {
            a[i] = scanner.nextInt();
        }

        // Create a subarray from index 1 to n (inclusive)
        int[] subArray = new int[n];
        System.arraycopy(a, 1, subArray, 0, n);

        // Sort the subarray to find the median
        Arrays.sort(subArray);

        // Calculate the median index (1-based position converted to 0-based)
        int medianIndex = (n / 2 + n % 2) - 1; // Convert to 0-based index
        System.out.println(subArray[medianIndex]);
    }
}

