    int n;
    cin >> n;
    vector<int> kn(n + 1);

    for (int i = 1; i <= n; i++) {
        cin >> kn[i];
    }

    // Insertion sort variant
    for (int i = 2; i <= n; i++) {
        int key = kn[i];
        int j = i - 1;
        while (j >= 1 && kn[j] > key) {
            kn[j + 1] = kn[j];
            j--;
        }
        kn[j + 1] = key;
    }

    cout << kn[(1 + n) / 2];
    return 0;
}

