public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int real_n = scanner.nextInt();
        int k = scanner.nextInt();

        double[] real_p = new double[123];
        double[] p = new double[123];
        double[] f = new double[2345678];
        double[] ans = new double[123];
        int[] id = new int[123];
        int[] kb = new int[2345678];

        int n = 0;
        for (int i = 0; i < real_n; i++) {
            real_p[i] = scanner.nextDouble();
            if (real_p[i] > 1e-4) {
                id[n] = i;
                p[n++] = real_p[i];
            }
        }

        k = Math.min(k, n);

        kb[0] = 0;
        for (int t = 1; t < (1 << n); t++) {
