    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        final int MAXN = 20;
        final int MAXMASK = 1 << MAXN;
        final double EPS = 1e-12;

        double[] dp = new double[MAXMASK];
        int[] cntBits = new int[MAXMASK];
        double[] ans = new double[MAXN];
        double[] prob = new double[MAXN];

        // Precompute bit counts
        for (int m = 1; m < MAXMASK; ++m) {
            cntBits[m] = cntBits[m >> 1] + (m & 1);
        }

        int n = sc.nextInt();
        int k = sc.nextInt();

        for (int i = 0; i < n; ++i) {
            prob[i] = sc.nextDouble();
        }

        dp[0] = 1.0;

        for (int mask = 0; mask < MAXMASK; ++mask) {
            double total = 0.0;
            for (int i = 0; i < n; ++i) {
                if ((mask & (1 << i)) == 0) {
                    total += prob[i];
                }
            }

            if (total < EPS) continue;

            for (int i = 0; i < n; ++i) {
                if ((mask & (1 << i)) == 0) {
                    if (cntBits[mask] < k) {
                        ans[i] += dp[mask] * prob[i] / total;
                    }
                    dp[mask | (1 << i)] += dp[mask] * prob[i] / total;
                }
            }
        }

        for (int i = 0; i < n; ++i) {
            System.out.printf("%.12f ", ans[i]);
        }
        System.out.println();
    }
}

