  return mp(f.fi - s.fi,
            f.se - s.se);
}

Val Mult(const Val& f, dbl w){
  return mp(f.fi * w,
            f.se * w);
}

Val Div(const Val& f, dbl w){
  return mp(f.fi / w,
            f.se / w);
}

Val dp[1 << 20];
