using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<double> p(n);
    for (int i = 0; i < n; i++) cin >> p[i];

    vector<vector<long double>> C(n+1, vector<long double>(n+1, 0));
    C[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++)
            C[i][j] = C[i-1][j-1] + C[i-1][j];
    }

    vector<int> bitcnt(1 << n, 0);
    vector<long double> subset_sum(1 << n, 0.0L);
    for (int mask = 0; mask < (1 << n); mask++) {
        for (int j = 0; j < n; j++) {
            if (mask >> j & 1) {
                bitcnt[mask]++;
                subset_sum[mask] += p[j];
            }
        }
    }

    vector<long double> coef(k, 0.0L);
    coef[k-1] = 1.0L;
    for (int i = k-2; i >= 0; i--) {
        long double tmp = 1.0L - coef[i];
        for (int j = i+1; j < k; j++) {
            tmp += C[n - 1 - i][j - i] * coef[j];
        }
        coef[i] = tmp;
    }

    for (int i = 0; i < n; i++) {
        long double ans = 0.0L;
        if (p[i] > 0.005) {
            for (int mask = 0; mask < (1 << n); mask++) {
                if (mask >> i & 1) continue;
                if (bitcnt[mask] >= k) continue;
                ans += coef[bitcnt[mask]] / (1.0L - subset_sum[mask]);
            }
        }
        cout << fixed << setprecision(12) << (double)(p[i] * ans) << " ";
    }
    cout << "\n";
    return 0;
}

