        long ans = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                ans = (ans * base) % MOD;
            }
            exp >>= 1;
            base = (base * base) % MOD;
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();

        if (k == 0) {
            System.out.println(powMod(p, p - 1));
            return;
        }
        if (k == 1) {
            System.out.println(powMod(p, p));
            return;
        }

        boolean[] seen = new boolean[1000020];
        Arrays.fill(seen, false);
        int count = 1;
        long state = k % p;
        seen[(int)state] = true;

        while (true) {
            state = (state * k) % p;
            if (seen[(int)state]) {
                break;
            }
            seen[(int)state] = true;
            count++;
        }

        int groups = (p - 1) / count;
        System.out.println(powMod(p, groups));
    }
}

