using namespace std;
typedef long long ll;
const int MAXN = 1000010;
const ll MOD = 1000000007LL;
bool visited[MAXN];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, k;
    cin >> p >> k;

    ll res = 1;

    if (k != 0) {
        // Find modular inverse of k mod p
        int invK = -1;
        for (int i = 1; i < p; ++i) {
            if ((1LL * i * k) % p == 1) {
                invK = i;
                break;
            }
        }

        // Process cycles in the mapping x -> k*x mod p
        for (int i = 1; i < p; ++i) {
            if (!visited[i]) {
                int cur = i;
                visited[i] = true;
                int len = 1;

                while (!visited[(ll)k * cur % p]) {
                    cur = (ll)k * cur % p;
                    visited[cur] = true;
                    len++;
                }

                // Check if the cycle closes after len steps with multiplier = 1
                ll multiplier = 1;
                for (int j = 0; j < len; ++j) {
                    multiplier = multiplier * invK % p;
                }

                if (multiplier == 1) {
                    res = res * p % MOD;
                }
            }
        }
    } else {
        // When k == 0, multiply by p (p-1) times
        for (int i = 1; i < p; ++i) {
            res = res * p % MOD;
        }
    }

    cout << res << endl;
    return 0;
}

