    cin >> P >> K;

    UnionFind uf(P);

    for (int i = 1; i < P; ++i) {
        int val = (1LL * K * i) % P;
        if (val == 0) val = P;
        uf.merge(i, val);
    }

    set<int> roots;
    for (int i = 1; i <= P; ++i) {
        roots.insert(uf.find(i));
    }

    i64 result;
    if (K == 0) {
        result = binpow(P, P - 1, MOD);
    } else if (K == 1) {
        result = binpow(P, P, MOD);
    } else {
        result = binpow(P, (i64)roots.size(), MOD);
    }

    cout << result << endl;

    return 0;
}

