import java.util.*;

public class Main {
    static final long MOD = 1000000007L; // 10^9 + 7
    static final long INF = Long.MAX_VALUE;

    // (base^power) % mod, safe for long near max
    static long pow_mod(long base, long power, long mod) {
        long r = 1;
        while (power > 0) {
            if (power % 2 == 1) {
                r = (r * base) % mod;
            }
            base = (base * base) % mod;
            power /= 2;
        }
        return r;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLong()) {
            long p = sc.nextLong();
