            for (long i = 1; i < p; i++) {
                if (bs[(int)i]) continue;

                long j = i;
                long w = 0;

                while (!bs[(int)j]) {
                    w++;
                    bs[(int)j] = true;
                    j = (j * k) % p;
                }

                if (pow_mod(k, w, p) == 1) {
                    pow++;
                }
            }

            System.out.println(pow_mod(p, pow, MOD));
        }
        sc.close();
    }
}

