import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;

    static long fastPow(long base, long exp) {
        long[] memo = new long[(int)exp + 1];
        Arrays.fill(memo, -1);

        class DP {
            long dp(long e) {
                if (e == 0) return 1;
                if (e == 1) return base % MOD;
                if (memo[(int)e] != -1) return memo[(int)e];
                long half = dp(e / 2);
                long res = (half * half) % MOD;
                if (e % 2 != 0) res = (res * base) % MOD;
                memo[(int)e] = res;
                return res;
            }
        }

        DP dpInstance = new DP();
        return dpInstance.dp(exp);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        long p = Long.parseLong(input[0]);
        long k = Long.parseLong(input[1]);

        if (k == 0) {
            System.out.println(fastPow(p, p - 1));
            return;
        }
        if (k == 1) {
            System.out.println(fastPow(p, p));
            return;
        }

        long q = k;
        int n = 1;
        while (q != 1) {
            q = (q * k) % p;
            n++;
        }

        System.out.println(fastPow(p, (p - 1) / n));
    }
}

