using ll = long long;
const ll MOD = 1000000007;

ll mod_exp(ll base, ll exp, ll mod) {
    ll result = 1;
    base %= mod;
    while (exp) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ll p_val, k_val;
    cin >> p_val >> k_val;

    if (k_val == 0) {
        cout << mod_exp(p_val, p_val - 1, MOD) << endl;
        return 0;
    }

    if (k_val == 1) {
        cout << mod_exp(p_val, p_val, MOD) << endl;
        return 0;
    }

    vector<bool> marked(p_val, false);
    int cycle_count = 0;

    for (int idx = 0; idx < p_val; ++idx) {
        if (marked[idx]) continue;

        int path_len = 0;
        ll current = idx;

        while (!marked[current]) {
            marked[current] = true;
            current = (current * k_val) % p_val;
            ++path_len;
        }

        if (path_len > 1) ++cycle_count;
    }

    cout << mod_exp(p_val, cycle_count, MOD) << endl;
    return 0;
}

