            if ((char)c == '-') f = -f;
        }
        while (c != -1 && Character.isDigit((char)c)) {
            x = x * 10 + (c - 48);
            c = in.read();
        }
        return x * f;
    }

    static void write(int x) {
        if (x < 0) {
            System.out.print('-');
            x = -x;
        }
        if (x == 0) {
            System.out.print('0');
            return;
        }
        char[] s = new char[20];
        int top = 0;
        while (x > 0) {
            s[top++] = (char)(x % 10 + 48);
            x /= 10;
        }
        while (top > 0) {
            System.out.print(s[--top]);
        }
    }

    public static void main(String[] args) throws Exception {
        InputStream in = System.in;
        OutputStream out = System.out;

        int P = readInt(in);
        int K = readInt(in);

        if (K == 0) {
            write(qpow(P, P - 1));
            System.out.println();
            return;
        }

        if (K == 1) {
            write(qpow(P, P));
            System.out.println();
            return;
        }

        boolean[] vis = new boolean[P + 1];
        int p = 1;
        int cycle_length = 0;
        while (!vis[p]) {
            vis[p] = true;
            p = (int)((long)K * p % P);
            cycle_length++;
        }

        write(qpow(P, P / cycle_length));
        System.out.println();
    }
}

