using namespace std;

const long double PI = 3.1415926535897932384626433832795028841971693992L;

#define pb emplace_back
#define mp make_pair
#define fi first
#define se second
#define ZERO(a) memset((a), 0, sizeof((a)))
#define INIT(a) memset((a), -1, sizeof((a)))
#define FOR(i, n) for (int i=0; i<int(n); ++i)
#define FORD(i, n) for (int i=int(n)-1; i>=0; --i)
#define FOR2(i, a, b) for (int i=int(a); i<int(b); ++i)
#define FOR2D(i, a, b) for (int i=int(b)-1; i>=int(a); --i)
#define BIT(i, m) ((m) & (1LL << (i)))
#define RBIT(i, m) ((m) & ~(1LL << (i)))
#define ABIT(i, m) ((m) | (1LL << (i)))
#define FORB(i, m) for (int i=0; i<32; ++i) if (BIT(i, m))
#define ALL(a) (a).begin(), (a).end()
#define OUT(i, n) ((i)<0 || (i)>=(n))
#define AT(a, i) ((a)[((i)+(int)(a).size())%(int)(a).size()])
#define IT(v, i) ((v).begin() + ((i)+(int)(v).size())%(int)(v).size())
#define IT2(v, i, j) IT(v, i), IT(v, j)
#define INSET(a, S) ((S).find((a)) != (S).end())

typedef vector<int> vi;
typedef long long ll;
typedef vector<ll> vll;
typedef pair<int, int> ii;
typedef vector<ii> vii;
typedef vector<string> vs;
typedef list<int> li;
typedef long double ld;

const ll MOD = 1000000007;

ll mod_pow(ll base, ll exp) {
    ll result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << mod_pow(p, p - 1) << '\n';
        return 0;
    }

    if (k == 1) {
        cout << mod_pow(p, p) << '\n';
        return 0;
    }

    ll order = 1;
    ll current = k % p;
    while (current != 1) {
        current = (current * k) % p;
        ++order;
    }

    cout << mod_pow(p, (p - 1) / order) << '\n';
    return 0;
}

