import java.util.*;

public class Main {
    static final long MOD = 1000000007L;

    static long fun1(long a, long b) {
        long tmp = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                tmp = (tmp * a) % MOD;
            }
            a = (a * a) % MOD;
            b >>= 1;
        }
        return tmp;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextLong()) {
            long p = scanner.nextLong();
            long k = scanner.nextLong();

            if (k == 0) {
                System.out.println(fun1(p, p - 1));
                continue;
            }
            if (k == 1) {
                System.out.println(fun1(p, p));
                continue;
            }
            long sum = 0;
            long tmp = 1;
            long next = -1;
            while (next != 1) {
                next = (k * tmp) % p;
                tmp = next;
                sum++;
            }
            System.out.println(fun1(p, (p - 1) / sum));
        }
        scanner.close();
    }
}

