import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;

    static long power(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        while (scanner.hasNextLong()) {
            long p = scanner.nextLong();
            long k = scanner.nextLong();

            if (k == 0) {
                System.out.println(power(p, p - 1, MOD));
            } else if (k == 1) {
                System.out.println(power(p, p, MOD));
            } else {
                long pos = 1;
                int ord = 0;
                do {
                    pos = (pos * k) % p;
                    ++ord;
                } while (pos != 1);
                System.out.println(power(p, (p - 1) / ord, MOD));
            }
        }

        scanner.close();
    }
}

import java.util.Scanner;

public class Main {
    private static final long MOD = 1000000007;

    private static long mod_pow(long b, long e, long m) {
        long r = 1;
        b %= m;
        while (e > 0) {
            if ((e & 1) == 1) {
                r = (r * b) % m;
            }
            b = (b * b) % m;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextLong()) {
            long p = scanner.nextLong();
            long k = scanner.nextLong();

            if (k == 0) {
                System.out.println(mod_pow(p, p - 1, MOD));
            } else if (k == 1) {
                System.out.println(mod_pow(p, p, MOD));
            } else {
                long idx = 1;
                long len = 0;
                do {
                    idx = (idx * k) % p;
                    ++len;
                } while (idx != 1);
                System.out.println(mod_pow(p, (p - 1) / len, MOD));
            }
        }
        scanner.close();
    }
}

