const long long MOD = 1000000007;

long long modPow(long long base, long long exp) {
    long long result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << modPow(p, p - 1) << '\n';
        return 0;
    }

