public class Main {
    static class DisjointSet {
        int[] id;
        int[] cnt;
        int compCount;

        DisjointSet(int n) {
            id = new int[n];
            cnt = new int[n];
            compCount = n;
            for (int i = 0; i < n; i++) {
                id[i] = i;
                cnt[i] = 1;
            }
        }

        int root(int x) {
            if (id[x] != x) {
                id[x] = root(id[x]);
            }
            return id[x];
        }

        boolean connect(int a, int b) {
            a = root(a);
            b = root(b);
            if (a == b) return false;
            if (cnt[a] < cnt[b]) {
                int temp = a;
                a = b;
                b = temp;
            }
            if (cnt[a] > 1 && cnt[b] > 1) {
                compCount--;
            }
            if (cnt[a] == 1 && cnt[b] == 1) {
                compCount++;
            }
            id[b] = a;
            cnt[a] += cnt[b];
            return true;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        final int MOD = 1000000007;
        int p = sc.nextInt();
        int k = sc.nextInt();

        int val = 1;
        if (k == 0) {
            for (int i = 0; i < p - 1; i++) {
                val = (int) ((long) val * p % MOD);
            }
        } else {
            DisjointSet ds = new DisjointSet(p);
            for (int i = 0; i < p; i++) {
                ds.connect(i, (int) ((long) k * i % p));
            }
            int groups;
            if (k > 1) {
                groups = ds.compCount;
            } else {
                groups = p - ds.cnt.length;
            }
            for (int i = 0; i < groups; i++) {
                val = (int) ((long) val * p % MOD);
            }
        }

        System.out.println(val);
    }
}

