struct DS {
    vector<int> p;
    vector<int> sz;
    int cc;
    DS(int n) : p(n), sz(n, 1), cc(n) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        if (p[x] != x) p[x] = find(p[x]);
        return p[x];
    }
    bool link(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return false;
        if (sz[x] < sz[y]) swap(x, y);
        cc -= (sz[x] > 1 && sz[y] > 1);
        cc += (sz[x] == 1 && sz[y] == 1);
        p[y] = x;
        sz[x] += sz[y];
        return true;
    }
};

