    ios_base::sync_with_stdio(false); cin.tie(nullptr); cout.tie(nullptr);
#endif

    const int MOD = 1000000007;
    int p, k;
    cin >> p >> k;

    int out = 1;
    if (k == 0) {
        for (int i = 0; i < p - 1; ++i)
            out = (ll)out * p % MOD;
    } else {
        DS ds(p);
        for (int i = 0; i < p; ++i)
            ds.link(i, (ll)k * i % p);
        int groups = (k > 1) ? ds.cc : p - ds.sz.size();
        for (int i = 0; i < groups; ++i)
