    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, k;
    cin >> p >> k;

    for (int i = 0; i < p; ++i) {
        if (!vis[i]) {
            int len = 0;
            long long cur = i;
            while (!vis[cur]) {
                vis[cur] = true;
                cur = (cur * k) % p;
                ++len;
            }
            ++freq[len];
        }
    }

    for (int i = 1; i <= p; ++i) {
        f[i] = (freq[i] * i) % MOD;
    }

    for (int i = 1; i <= p; ++i) {
        g[i] = (g[i] + f[i]) % MOD;
        for (int j = i << 1; j <= p; j += i) {
            g[j] = (g[j] + f[i]) % MOD;
        }
    }

    long long ans = 1;
    for (int i = 1; i <= p; ++i) {
        if (i == 1) {
            for (int j = 0; j < freq[i] - 1; ++j) {
                ans = (ans * freq[i]) % MOD;
            }
        } else {
            for (int j = 0; j < freq[i]; ++j) {
                ans = (ans * g[i]) % MOD;
            }
        }
    }

    if (k == 1) {
        ans = (ans * g[1]) % MOD;
    }

    cout << ans << '\n';
    return 0;
}

