using namespace std;

const long long MOD = 1000000007LL;
const int MAXN = 1000007;

long long P, K;
int visited[MAXN];
int countCycle[MAXN];

long long computeCyclePower(int len) {
    long long base = ((long long)len * countCycle[len]) % MOD;
    base = (base + 1) % MOD;
    long long result = 1;
    for (int i = 0; i < countCycle[len]; ++i) {
        result = (result * base) % MOD;
    }
    return result;
}

int main() {
    cin >> P >> K;

    memset(visited, 0, sizeof(visited));
    memset(countCycle, 0, sizeof(countCycle));

    if (K == 0) {
        long long ans = 1;
        for (int i = 0; i < P - 1; ++i) {
            ans = (ans * P) % MOD;
        }
        cout << ans << endl;
        return 0;
    }

    if (K == 1) {
        long long ans = 1;
        for (int i = 0; i < P; ++i) {
            ans = (ans * P) % MOD;
        }
        cout << ans << endl;
        return 0;
    }

    for (int start = 0; start < P; ++start) {
        if (!visited[start]) {
            int length = 0;
            int cur = start;
            while (!visited[cur]) {
                visited[cur] = 1;
                length++;
                cur = (K * cur) % P;
            }
            countCycle[length]++;
        }
    }

    long long result = 1;
    for (int len = 2; len < P; ++len) {
        if (countCycle[len] > 0) {
            result = (result * computeCyclePower(len)) % MOD;
        }
    }

