using namespace std;

typedef long long ll;

const ll MOD = 1000000007;


struct DSU
{
	vector<ll> parent;

	DSU(ll n)
	{
		parent = vector<ll>(n);
		for (ll i = 0LL; i < n; i++) {
			parent[i] = i;
		}
	}

	ll find_set(ll a)
	{
		if (a == parent[a]) {
			return a;
		}
		ll base = find_set(parent[a]);
		parent[a] = base;
		return base;
	}

	void union_set(ll a, ll b)
	{
		a = find_set(a);
		b = find_set(b);
		if (a != b) {
			if (rand() % 2) {
				swap(a, b);
			}
			parent[b] = a;
		}
	}
};

ll count_cycles(ll p, ll k)
{
	DSU dsu(p);
	for (ll i = 1LL; i < p; i++) {
		ll ki = (k * i) % p;
		dsu.union_set(i, ki);
	}

	vector<bool> found(p, false);
	ll count = 0LL;
	for (ll i = 1LL; i < p; i++) {
		ll base = dsu.find_set(i);
		if (!found[base]) {
			found[base] = true;
			count++;
		}
	}
	return count;
}

ll count_solutions(ll p, ll k)
{
	ll cycles;
	if (k == 0) {
		cycles = p - 1;
	}
	else if (k == 1) {
		cycles = p;
	}
	else {
		cycles = count_cycles(p, k);
	}

	ll count = 1LL;
	for (ll i = 0LL; i < cycles; i++) {
		count *= (ll)p;
		count %= MOD;
	}
	return (ll)count;
}

int main()
{
	ll p, k;
	cin >> p >> k;
	ll count = count_solutions(p, k);
	printf("%lld\n", count);

	int end;
	cin >> end;
	return 0;
}

