    long long cycles;
    if (k == 0LL) cycles = p - 1;
    else if (k == 1LL) cycles = p;
    else cycles = count_cycles(p, k);

    long long ans = 1;
    for (long long i = 0; i < cycles; ++i) {
        ans = (ans * p) % MOD;
