using ll = long long;
constexpr ll MOD = 1000000007;

ll modular_exponentiation(ll base, ll exponent, ll modulus) {
    ll result = 1;
    base %= modulus;
    while (exponent) {
        if (exponent & 1) result = (result * base) % modulus;
        base = (base * base) % modulus;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << modular_exponentiation(p, p - 1, MOD);
        return 0;
    }

    vector<int> root(p);
    vector<int> component_size(p, 1);
    for (int i = 0; i < p; ++i) root[i] = i;

    function<int(int)> find_root = [&](int node) -> int {
        if (root[node] != node) {
            root[node] = find_root(root[node]);
        }
        return root[node];
    };

    auto union_nodes = [&](int a, int b) {
        int ra = find_root(a), rb = find_root(b);
        if (ra != rb) {
            root[rb] = ra;
            component_size[ra] += component_size[rb];
        }
    };

    for (int i = 0; i < p; ++i) {
        union_nodes((1LL * k * i) % p, i);
    }

    ll answer = 1;
    for (int i = 0; i < p; ++i) {
        if (find_root(i) == i) {
            answer = (answer * modular_exponentiation(k, component_size[i], p)) % MOD;
        }
    }

    cout << answer;
    return 0;
}

