public class Main {
    static final long MOD = 1000000007;

    static long modularExponentiation(long base, long exponent, long modulus) {
        long result = 1;
        base %= modulus;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();

        if (k == 0) {
            System.out.println(modularExponentiation(p, p - 1, MOD));
            return;
        }

        int[] root = new int[p];
        int[] componentSize = new int[p];
        for (int i = 0; i < p; ++i) {
            root[i] = i;
            componentSize[i] = 1;
        }

        java.util.function.Function<Integer, Integer> findRoot = (node) -> {
            if (root[node] != node) {
                root[node] = findRoot.apply(root[node]);
            }
            return root[node];
        };

        java.util.function.BiConsumer<Integer, Integer> unionNodes = (a, b) -> {
            int ra = findRoot.apply(a);
            int rb = findRoot.apply(b);
