            if (size == 1) {
                int cnt = k == 1 ? p : 1;
                ans = (long long)ans * cnt % MOD;
            } else {
                assert(tmp == 1);
                ans = (long long)ans * p % MOD;
            }
        }
    }
    cout << ans << endl;
}

