const double EPS = 1e-8;
const int INF = (int) 2e9;
const ll LINF = (ll) 2e18;
const int MOD = (int) 1e9 + 7;
const int MAXN = (int) 3e6 + 10;

int p, k, t;
bool used[MAXN];

void dfs (int x) {
	used[x] = true;
	int to = ((ll) x * k) % p;
	if (!used[to]) {
		dfs(to);
	}
}

int main () {
	ios_base::sync_with_stdio(false);
	cin >> p >> k;
	for (int i = 0; i < p; i++) {
		if (!used[i]) {
			t++;
			dfs(i);
		}
	}
	ll ans = 1;
	for (int i = 1; i < t + (k == 1); i++) {
		ans *= p;
		ans %= MOD;
	}
	cout << ans;
}

