public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        int[] ts = new int[n];
        for (int i = 0; i < n; i++) {
            ts[i] = scanner.nextInt();
        }
        int T = scanner.nextInt();

        Arrays.sort(ts);

        int maxCount = 1;
        for (int i = 0; i < n; ++i) {
            int upperBound = ts[i] + T;
            int upperIdx = upperBoundSearch(ts, upperBound);
            maxCount = Math.max(maxCount, upperIdx - i);
        }

        System.out.println(maxCount);
    }

    private static int upperBoundSearch(int[] arr, int value) {
        int left = 0;
        int right = arr.length;
        while (left < right) {
            int mid = (left + right) / 2;
            if (arr[mid] > value) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

