import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int n = scanner.nextInt();
        int[] v = new int[n];
        for (int i = 0; i < n; ++i) {
            v[i] = scanner.nextInt();
        }

        Arrays.sort(v);

        int interval = scanner.nextInt();

        int result = 0;
        for (int i = 0; i < n; ++i) {
            int target = v[i] + interval;
            int upperIndex = binarySearchUpper(v, i, n - 1, target);
            int count = upperIndex - i;
            result = Math.max(result, count);
        }

        System.out.println(result);
    }

    private static int binarySearchUpper(int[] arr, int left, int right, int target) {
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] <= target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return left;
    }
}

