import java.util.*;

public class Main {
    static final int NN = 202;
    static final int INF = 0x3f3f3f3f;

    static int[][] flow = new int[NN][NN];
    static int[][] cap = new int[NN][NN];
    static int[] pre = new int[NN];
    static int[] que = new int[NN];
    static int[] d = new int[NN];

    static int edmondsKarp(int n, int source, int sink) {
        int p, q, t, i, j;
        while (true) {
            Arrays.fill(pre, -1);
            d[source] = INF;
            p = q = 0;
            que[q++] = source;
            while (p < q && pre[sink] < 0) {
                t = que[p++];
                for (i = 0; i < n; i++) {
                    if (pre[i] < 0 && (j = cap[t][i] - flow[t][i]) > 0) {
                        pre[que[q++] = i] = t;
                        d[i] = Math.min(d[t], j);
                    }
                }
            }
            if (pre[sink] < 0) break;
            for (i = sink; i != source; i = pre[i]) {
                flow[pre[i]][i] += d[sink];
                flow[i][pre[i]] -= d[sink];
            }
        }
        for (j = 0, i = 0; i < n; j += flow[source][i++]);
        return j;
    }

    static char[][] a = new char[11][11];
    static char[][] b = new char[11][11];
    static int bi, bj;
    static int[][] dir = {{0,1}, {0,-1}, {1,0}, {-1,0}};
    static int[][] mat = new int[101][101];
    static int n, t;
    static List<Integer> ca = new ArrayList<>();
    static List<Integer> cb = new ArrayList<>();

    static void solve(int A, int B, int[] vis, boolean check) {
        Queue<int[]> queue = new LinkedList<>();
        vis[A * n + B] = 0;
        queue.offer(new int[]{A, B});
        while (!queue.isEmpty()) {
            int[] now = queue.poll();
            int p = now[0] * n + now[1];
            int dis = vis[p];
            if (check && (mat[bi * n + bj][p] <= dis || t <= dis)) {
                if (mat[bi * n + bj][p] < dis || t < dis) vis[p] = INF + 1;
                continue;
            }
            for (int d = 0; d < 4; ++d) {
                int i = dir[d][0] + now[0];
                int j = dir[d][1] + now[1];
                if (i < 0 || j < 0 || i == n || j == n) continue;
                if (b[i][j] < '0' || b[i][j] > '9') continue;
                int q = i * n + j;
                if (vis[q] != INF) continue;
                vis[q] = dis + 1;
                queue.offer(new int[]{i, j});
            }
        }
    }

    static void build() {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (b[i][j] <= '0' || b[i][j] > '9') continue;
                ca.add(i);
                cb.add(j);
                int p = i * n + j;
                cap[p + 2 + n * n][1] = b[i][j] - '0';
            }
        }
        int z = bi * n + bj;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (a[i][j] <= '0' || a[i][j] > '9') continue;
                int p = i * n + j;
                cap[0][p + 2] = a[i][j] - '0';
                for (int k = 0; k < ca.size(); ++k) {
                    int ii = ca.get(k);
                    int jj = cb.get(k);
                    int q = ii * n + jj;
                    if (mat[p][q] < INF)
                        cap[p + 2][q + 2 + n * n] = INF;
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine();

        for (int i = 0; i < n; ++i) {
            a[i] = sc.nextLine().toCharArray();
        }
        for (int i = 0; i < n; ++i) {
            b[i] = sc.nextLine().toCharArray();
        }

        for (int i = 0; i < 101; ++i) {
            Arrays.fill(mat[i], INF);
        }

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (a[i][j] == 'Z') {
                    bi = i;
                    bj = j;
                }
            }
        }

        solve(bi, bj, mat[bi * n + bj], false);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (a[i][j] >= '1' && a[i][j] <= '9') {
                    solve(i, j, mat[i * n + j], true);
                }
            }
        }

        build();

        System.out.println(edmondsKarp(2 + n * n + n * n, 0, 1));
    }
}

