        for (int i = 0; i < n; i++) {
            String s = sc.next();
            inp[i] = s.toCharArray();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inp[i][j] == 'Y' || inp[i][j] == 'Z') {
                    plant[i][j][0] = inp[i][j] - 'X';
                    source_cap[i][j] = 0;
                } else {
                    plant[i][j][0] = 0;
                    source_cap[i][j] = inp[i][j] - '0';
                }
            }
        }
        for (int i = 0; i < n; i++) {
            String s = sc.next();
            inp[i] = s.toCharArray();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inp[i][j] == 'Y' || inp[i][j] == 'Z') {
                    plant[i][j][0] = inp[i][j] - 'X';
                    sink_cap[i][j] = 0;
                } else {
                    plant[i][j][0] = 0;
                    sink_cap[i][j] = inp[i][j] - '0';
                }
            }
        }
        for (int curr_time = 1; curr_time <= t; curr_time++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    plant[i][j][curr_time] = plant[i][j][curr_time - 1];
                }
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (plant[i][j][curr_time - 1] == 2) {
                        for (int k = 0; k < 4; k++) {
                            if (is_valid(i + dr[k], j + dc[k])) {
                                if (plant[i + dr[k]][j + dc[k]][curr_time - 1] == 0)
                                    plant[i + dr[k]][j + dc[k]][curr_time] = 2;
                            }
                        }
                    }
                }
            }
        }
        counter = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (source_cap[i][j] != 0) {
                    source_num[i][j] = counter;
                    counter++;
                } else {
                    source_num[i][j] = -1;
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (sink_cap[i][j] != 0) {
                    sink_num[i][j] = counter;
                    counter++;
                } else {
                    sink_num[i][j] = -1;
                }
            }
        }
        Queue<int[]> bfs = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (source_cap[i][j] == 0)
                    continue;
                bfs.offer(new int[]{0, i, j});
                int source = source_num[i][j];
                boolean[][] vis = new boolean[n][n];
                vis[i][j] = true;
                while (!bfs.isEmpty()) {
                    int[] top = bfs.poll();
                    int curr_time = top[0], r = top[1], c = top[2];
                    if (sink_cap[r][c] != 0)
                        flo[source][sink_num[r][c]] = 10000;
                    if (curr_time == t)
                        continue;
                    if (plant[r][c][curr_time] != 0)
                        continue;
                    for (int k = 0; k < 4; k++) {
                        if (is_valid(r + dr[k], c + dc[k]) && plant[r + dr[k]][c + dc[k]][curr_time] == 0 && !vis[r + dr[k]][c + dc[k]]) {
                            bfs.offer(new int[]{curr_time + 1, r + dr[k], c + dc[k]});
                            vis[r + dr[k]][c + dc[k]] = true;
                        }
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (source_cap[i][j] != 0)
                    flo[0][source_num[i][j]] = source_cap[i][j];
                if (sink_cap[i][j] != 0)
                    flo[sink_num[i][j]][counter] = sink_cap[i][j];
            }
        }
        int temp, ans = 0;
        while (true) {
            temp = get_path();
            if (temp == 0)
                break;
            ans += temp;
        }
        System.out.println(ans);
    }
}

