        while (!dfs.isEmpty()) {
            int top = dfs.pop();
            if (top == counter)
                break;
            for (int i = 0; i <= counter; i++) {
                if (flo[top][i] != 0 && parent[i] == -1) {
                    parent[i] = top;
                    dfs.push(i);
                }
            }
