typedef long long lint;
typedef pair<int,int> pii;
typedef pair<lint,lint> pll;

const int INF = 0x3f3f3f3f;
const lint LINF = 0x3f3f3f3f3f3f3f3fll;
const int MAXN = 20;
const int MAXV = 2*MAXN*MAXN;

char m1[MAXN][MAXN], m2[MAXN][MAXN];
int inf_time[MAXN][MAXN];
int n,t;

int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};

void bfs(int x,int y) {
    for(int a=0;a<n;++a)
        for(int b=0;b<n;++b)
            inf_time[a][b] = INF;
    inf_time[x][y] = 0;
    queue<pii> fila;
    fila.push(pii(x,y));
    while(!fila.empty()) {
        int cx = fila.front().first, cy = fila.front().second;
        fila.pop();
        for(int a=0;a<4;++a) {
            int nx = cx+dx[a], ny = cy+dy[a];
            if(nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if('0' <= m1[nx][ny] && m1[nx][ny] <= '9' && inf_time[nx][ny] == INF) {
                inf_time[nx][ny] = inf_time[cx][cy] + 1;
                fila.push(pii(nx,ny));
            }
        }
    }
}

bool foi[MAXN][MAXN];

vector<int> adj[MAXV];
int cap[MAXV][MAXV];

inline void insert_edge(int u,int v,int c) {
    adj[u].push_back(v);
    adj[v].push_back(u);
    cap[u][v] = c;
    cap[v][u] = 0;
}

int tempo[MAXN][MAXN];
bool dinic_foi[MAXV];
int dist[MAXV];

bool dinic_bfs(int s,int t) {
    memset(dist,-1,sizeof(dist));
    dist[s] = 0;
    queue<int> fila;
    fila.push(s);
    while(!fila.empty() && dist[t] == -1) {
        int v = fila.front();
        fila.pop();
        foreach(nxt,adj[v]) {
            if(!cap[v][*nxt] || dist[*nxt] != -1) continue;
            dist[*nxt] = dist[v] + 1;
            fila.push(*nxt);
        }
    }
    return dist[t] != -1;
}

