        }
    }
    bfs(ix,iy);
    for(int a=0;a<n;++a) {
        for(int b=0;b<n;++b) {
            scanf(" %c",&m2[a][b]);
            if('1' <= m2[a][b] && m2[a][b] <= '9')
                insert_edge(n*n + a*n+b,t,m2[a][b]-'0');
        }
    }
    for(int a=0;a<n;++a)
        for(int b=0;b<n;++b)
            if('1' <= m1[a][b] && m1[a][b] <= '9')
                bfs2(a,b);
    printf("%d\n",dinic(s,t));    
    return 0;
}

