        for (int a = 0; a < n; ++a)
            for (int b = 0; b < n; ++b)
                inf_time[a][b] = INF;
        inf_time[x][y] = 0;
        Queue<int[]> fila = new LinkedList<>();
        fila.offer(new int[]{x, y});
