#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>
using namespace std;

int N;
vector<string> A, B;
vector<vector<int>> dists;

struct Edge {
    int u, v, cap, w;
    Edge(int a, int b, int c, int d) : u(a), v(b), cap(c), w(d) {}
};

struct MCMF {
    int nodes;
    vector<int> d, f, p;
    vector<Edge> e;
    int flow, cost;

    void reset(int n) {
        nodes = n;
        d.assign(n, INT_MAX);
        f.assign(n, 0);
        p.assign(n, -1);
    }

    void connect(int a, int b, int c, int w) {
        e.emplace_back(a, b, c, w);
        e.emplace_back(b, a, 0, -w);
    }

    void find_path(int s, int t) {
        reset(nodes);
        f[s] = INT_MAX;
        d[s] = 0;
        queue<int> q;
        vector<bool> inq(nodes, false);
        q.push(s);
        inq[s] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = false;
            for (size_t i = 0; i < e.size(); ++i) {
                auto& ed = e[i];
                if (ed.cap > 0 && d[ed.v] > d[ed.u] + ed.w) {
                    d[ed.v] = d[ed.u] + ed.w;
                    f[ed.v] = min(f[ed.u], ed.cap);
                    p[ed.v] = i;
                    if (!inq[ed.v]) {
                        q.push(ed.v);
                        inq[ed.v] = true;
                    }
                }
            }
        }
    }

    void run(int s, int t) {
        if (s == t) {
            flow = INT_MAX;
            cost = 0;
            return;
        }
        flow = 0;
        cost = 0;
        while (true) {
            find_path(s, t);
            if (f[t] == 0) break;
            for (int cur = t; cur != s; cur = e[p[cur]].u) {
                int rev = p[cur] ^ 1;
                e[p[cur]].cap -= f[t];
                e[rev].cap += f[t];
                cost += e[p[cur]].w * f[t];
            }
            flow += f[t];
        }
    }
