    int n, m, s, t;
    vector<int> adj[MAXN];
    Edge edges[MAXM * 2];

    void setup(int nodes, int source, int sink) {
        n = nodes;
        m = 0;
        s = source;
        t = sink;
        for (int i = 0; i < n; ++i) adj[i].clear();
    }

    void link(int u, int v, int c) {
        edges[m].v = v;
        edges[m].cap = c;
        adj[u].push_back(m);
        edges[m+1].v = u;
        edges[m+1].cap = 0;
        adj[v].push_back(m+1);
        m += 2;
    }

    int cnt[MAXN];
    int dist[MAXN];
    int last[MAXN];
    int path[MAXN];
    int pathLen;

    void bfs() {
        queue<int> q;
        memset(cnt, 0, sizeof(cnt));
        fill(dist, dist + n, n);
        dist[t] = 0;
        q.push(t);
        while (!q.empty()) {
            int u = q.front();
            cnt[dist[u]]++;
            for (int i = 0; i < (int)adj[u].size(); ++i) {
                int id = adj[u][i];
                int v = edges[id].v;
                if (dist[v] == n && edges[id ^ 1].cap > 0) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
            q.pop();
        }
    }

