        cnt[dist[v]]--;
        dist[v] = n;
        for (int i = 0; i < (int)adj[v].size(); ++i) {
            Edge &e = edges[adj[v][i]];
            if (dist[v] > dist[e.v] + 1 && e.cap > 0) {
                dist[v] = dist[e.v] + 1;
                last[v] = i;
            }
        }
        cnt[dist[v]]++;
    }

    int augment() {
        int minNode = -1;
        int flow = 0x7fffff;
        for (int i = 0; i < pathLen; ++i) {
            Edge &e = edges[adj[path[i]][last[path[i]]]];
            if (e.cap < flow) {
                flow = e.cap;
                minNode = i;
            }
        }
        for (int i = 0; i < pathLen; ++i) {
            int id = adj[path[i]][last[path[i]]];
            edges[id].cap -= flow;
            edges[id ^ 1].cap += flow;
        }
        pathLen = minNode;
        return flow;
