    memset(dist, -1, sizeof(dist));
    dist[source] = 0;
    queue<int> q;
    q.push(source);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int idx : graph[u]) {
            const auto& e = edges[idx];
            if (dist[e.v] == -1 && e.flow < e.capacity) {
                dist[e.v] = dist[u] + 1;
                q.push(e.v);
                if (e.v == sink) return true;
            }
        }
    }
    return false;
}

