        for (int x = 0; x < N; x++) {
            for (int y = 0; y < N; y++) {
                if (grid1[x][y] == 'Z') {
                    for (int i = 0; i < 4; i++) {
                        int nx = x + dx[i];
                        int ny = y + dy[i];
                        if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y') {
                            A[nx][ny] = 1;
                            Q.add(new int[]{nx, ny});
                        }
                    }
                }
            }
        }

        while (!Q.isEmpty()) {
            int[] cell = Q.poll();
            int x = cell[0], y = cell[1];
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i];
                int ny = y + dy[i];
                if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y' && grid1[nx][ny] != 'Z' && A[nx][ny] == INF) {
                    A[nx][ny] = A[x][y] + 1;
                    Q.add(new int[]{nx, ny});
                }
            }
        }

        for (int x1 = 0; x1 < N; x1++) {
            for (int y1 = 0; y1 < N; y1++) {
                for (int x2 = 0; x2 < N; x2++) {
                    for (int y2 = 0; y2 < N; y2++) {
                        if (grid1[x1][y1] == 'Y' || grid1[x1][y1] == 'Z' || grid1[x2][y2] == 'Y' || grid1[x2][y2] == 'Z') {
                            B[x1][y1][x2][y2] = 0;
                            continue;
                        }
                        for (int i = 0; i < N; i++) {
                            for (int j = 0; j < N; j++) {
                                depth[i][j] = INF;
                            }
                        }
                        Queue<int[]> Q2 = new LinkedList<>();
                        depth[x1][y1] = 0;
                        Q2.add(new int[]{x1, y1});
                        int c = 0;
                        while (!Q2.isEmpty()) {
                            int[] cell = Q2.poll();
                            int x = cell[0], y = cell[1];
                            if (x == x2 && y == y2) {
                                c = 1;
                                break;
                            }
                            if (depth[x][y] >= T || depth[x][y] >= A[x][y]) {
                                continue;
                            }
                            for (int i = 0; i < 4; i++) {
                                int nx = x + dx[i];
                                int ny = y + dy[i];
                                if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y' && grid1[nx][ny] != 'Z' && depth[nx][ny] == INF && depth[x][y] + 1 <= A[nx][ny]) {
                                    depth[nx][ny] = depth[x][y] + 1;
                                    Q2.add(new int[]{nx, ny});
                                }
                            }
                        }
                        B[x1][y1][x2][y2] = c;
                    }
                }
            }
        }

        for (int i = 0; i < MAX_NETWORK_NODES; i++) {
            g[i] = new ArrayList<>();
        }

        buildNetwork();
        System.out.println(dinic());
    }
}

