        int t=dinic(y,min(k,a[i][1]));
        k-=t;
        a[i][1]-=t;
        a[i^1][1]+=t;
        if (k==0)
            return(flow);
    }
    if (k==flow)
        d[x]=-1;
    return(flow-k);
}
