        q.offer(s);
        now[s] = head[s];
        d[s] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int i = head[u]; i != -1; i = edge[i].next) {
                int v = edge[i].to;
                int w = edge[i].w;
                if (d[v] != 0) continue;
                if (w == 0) continue;
                d[v] = d[u] + 1;
                now[v] = head[v];
                q.offer(v);
                if (v == t) return true;
            }
        }
        return false;
    }

