        for (int j = 0; j < N; ++j)
            if (G1[i][j] == 'Z') rx = i, ry = j;

    auto dist_to_react = BFS(rx, ry, G1);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (!valid(i, j, G1)) continue;
            auto dist_from_src = BFS(i, j, G1);

            for (int x = 0; x < N; ++x) {
                for (int y = 0; y < N; ++y) {
                    if (!valid(x, y, G1)) continue;
                    if (dist_from_src[x][y] > T) continue;
                    if (dist_from_src[x][y] > dist_to_react[x][y]) continue;

                    bool special = (dist_from_src[x][y] == dist_to_react[x][y]);
                    if (special) {
                        bool escapable = false;
                        for (int d = 0; d < 4; ++d) {
