using namespace std;

using lli = long long;
using pii = pair<int, int>;
using vs = vector<string>;

const lli INF = (lli)1e18;
const int MAX_NODES = 1000;

const int dR[4] = {0, 0, -1, 1};
const int dC[4] = {-1, 1, 0, 0};

vector<int> graph[MAX_NODES];
bool visited[MAX_NODES];
