inline bool safe(int r, int c, const vs& grid) {
    int n = grid.size();
    return r >= 0 && c >= 0 && r < n && c < n && grid[r][c] != 'Y' && grid[r][c] != 'Z';
}

vector<vector<lli>> distance_field(int sr, int sc, const vs& grid) {
    int n = grid.size();
    vector<vector<lli>> dist(n, vector<lli>(n, INF));
    deque<pii> dq;
    dist[sr][sc] = 0;
    dq.emplace_back(sr, sc);

    while (!dq.empty()) {
        auto [r, c] = dq.front(); dq.pop_front();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dR[k], nc = c + dC[k];
            if (!safe(nr, nc, grid) || dist[nr][nc] != INF) continue;
            dist[nr][nc] = dist[r][c] + 1;
            dq.emplace_back(nr, nc);
        }
    }
    return dist;
}

void construct_graph() {
    int N, T;
