    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (!safe(i, j, A)) continue;
            auto dist_src = distance_field(i, j, A);

            for (int x = 0; x < N; ++x) {
                for (int y = 0; y < N; ++y) {
                    if (!safe(x, y, A)) continue;
                    if (dist_src[x][y] > T) continue;
                    if (dist_src[x][y] > dist_react[x][y]) continue;

                    bool critical = (dist_src[x][y] == dist_react[x][y]);
                    if (critical) {
                        bool able_to_escape = false;
                        for (int k = 0; k < 4; ++k) {
                            int nx = x + dR[k], ny = y + dC[k];
                            if (safe(nx, ny, A) && dist_src[nx][ny] < dist_react[nx][ny]) {
                                able_to_escape = true;
                                break;
                            }
                        }
                        if (!able_to_escape) continue;
                    }

                    int cap1 = A[i][j] - '0';
                    int cap2 = B[x][y] - '0';
                    for (int u = 1; u <= cap1; ++u) {
                        for (int v = 1; v <= cap2; ++v) {
                            int src_id = 100 * i + 10 * j + u;
                            int dst_id = 100 * x + 10 * y + v;
                            graph[src_id].push_back(dst_id);
                        }
                    }
                }
            }
        }
    }
}

bool try_augment(int u) {
    if (visited[u]) return false;
    visited[u] = true;
    for (int v : graph[u]) {
        if (!mate[v] || try_augment(mate[v])) {
            mate[v] = u;
