      for (int e : path) {
        int rev = (e % 2) ? e - 1 : e + 1;
        flow[e] += cap;
        flow[rev] -= cap;
      }
      total += cap;
    }

    for (int idx : residual.V[s].adj)
      total += flow[idx];
    return total;
  }
};

