import java.util.*;
import java.io.*;

public class Main {
    static class Fraction {
        long numerator;
        long denominator;

        Fraction(long num, long den) {
            numerator = num;
            denominator = den;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int x = Integer.parseInt(st.nextToken());
        int y = Integer.parseInt(st.nextToken());
        int n = Integer.parseInt(st.nextToken());

        List<Fraction> pool = new ArrayList<>();
        pool.ensureCapacity(2 * n);

        for (int b = 1; b <= n; ++b) {
            long[] approx = computeApproximations(x, y, b);
            pool.add(new Fraction(approx[0], b));
            pool.add(new Fraction(approx[1], b));
        }

        final int[] finalX = {x};
        final int[] finalY = {y};

        Comparator<Fraction> cmp = (a, b) -> {
            long da = distance(finalX[0], finalY[0], a.numerator, a.denominator);
            long db = distance(finalX[0], finalY[0], b.numerator, b.denominator);
            if (da != db) return Long.compare(da, db);
            if (a.denominator != b.denominator) return Long.compare(a.denominator, b.denominator);
            return Long.compare(a.numerator, b.numerator);
        };

        Collections.sort(pool, cmp);
        Fraction best = pool.get(0);

        System.out.println(best.numerator + "/" + best.denominator);
    }

    private static long[] computeApproximations(int x, int y, int b) {
        long num = (long) b * x;
        long lower = num / y;
        long upper = (num + y - 1) / y;
        return new long[]{lower, upper};
    }

    private static long distance(int x, int y, long num, long den) {
        return Math.abs((long) x * den - num * y);
    }
}

