        int x = scanner.nextInt();
        int y = scanner.nextInt();
        int n = scanner.nextInt();

        List<Candidate> pool = new ArrayList<>();
        pool.ensureCapacity(2 * n);

        for (int b = 1; b <= n; ++b) {
            long[] bounds = getBounds(x, y, b);
            pool.add(new Candidate(bounds[0], b));
            pool.add(new Candidate(bounds[1], b));
        }

        pool.sort((lhs, rhs) -> {
            long el = error(lhs, x, y);
            long er = error(rhs, x, y);
            if (el != er) {
                return Long.compare(el, er);
            }
            if (lhs.b != rhs.b) {
                return Long.compare(lhs.b, rhs.b);
            }
            return Long.compare(lhs.a, rhs.a);
        });

        System.out.println(pool.get(0).a + "/" + pool.get(0).b);
    }

    private static long[] getBounds(int x, int y, int b) {
        long num = (long) b * x;
        long lo = num / y;
        long hi = (num + y - 1) / y;
        return new long[]{lo, hi};
    }

    private static long error(Candidate c, int x, int y) {
        return Math.abs((long) x * c.b - c.a * y);
    }
}

