    long long int x, y, n;
    cin >> x >> y >> n;

    for (long long int i = 1; i <= n; i++) {
        function(x, y, i, (i * x) / y);
        function(x, y, i, (i * x) / y + 1);
        function(x, y, i, (i * x) / y - 1);
    }

    cout << ra << "/" << rb << endl;
