    return a / gcd(a, b) * b;
}

double fraction_diff(long long num1, long long den1, long long num2, long long den2) {
    long long common_den = lcm(den1, den2);
    long long n1 = common_den / den1 * num1;
    long long n2 = common_den / den2 * num2;
