import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();

        long ansA = 0, ansB = 0;
        double dif = 1e12;

        for (long b = 1; b <= n; b++) {
            long l = 0, r = 100 * 1000;
            long a = 0;

            while (l <= r) {
                long mid = (l + r) >> 1;
                if (mid * y <= x * b) {
                    a = mid;
                    l = mid + 1;
                } else {
                    r = mid - 1;
                }
            }

            l = 0;
            r = 100 * 1000;
            long aa = 0, bb = b;

            while (l <= r) {
                long mid = (l + r) >> 1;
                if (mid * y < x * b) {
                    l = mid + 1;
                } else {
                    aa = mid;
                    r = mid - 1;
                }
            }

            double curDif2 = Math.abs((double) aa / (double) bb - (double) x / (double) y);
            double curDif1 = Math.abs((double) a / (double) b - (double) x / (double) y);

            if (curDif2 + 1e-8 < curDif1) {
                a = aa;
                b = bb;
                curDif1 = curDif2;
            }

