            if (curDif1 < dif) {
                ansA = a / curGcd;
                ansB = b / curGcd;
                dif = curDif1;
            }
        }

        System.out.println(ansA + "/" + ansB);
    }

    public static long gcd(long a, long b) {
        while (b != 0) {
            long temp = a % b;
