#include <iostream>
#include <string>
#include <cstdlib>
#include <vector>
#include <cmath>
#include <algorithm>
using namespace std;

using i64 = long long;

#define len(c) static_cast<int>((c).size())

i64 compute_gcd(i64 u, i64 v) {
    while (v != 0) {
        u %= v;
        swap(u, v);
    }
    return u;
}

int main() {
    i64 numerator, denominator, limit;
    cin >> numerator >> denominator >> limit;

    i64 best_num = 0, best_den = 1;
    double min_diff = 1e18;

    for (i64 d = 1; d <= limit; ++d) {
        i64 num1 = 0;
        i64 lo = 0, hi = 100000;
        while (lo <= hi) {
            i64 mid = (lo + hi) / 2;
            if (mid * denominator <= numerator * d) {
                num1 = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        i64 num2 = 0;
        lo = 0, hi = 100000;
        while (lo <= hi) {
            i64 mid = (lo + hi) / 2;
            if (mid * denominator < numerator * d) {
                lo = mid + 1;
            } else {
                num2 = mid;
                hi = mid - 1;
            }
        }

        double diff1 = fabs(static_cast<double>(num1) / d - static_cast<double>(numerator) / denominator);
        double diff2 = fabs(static_cast<double>(num2) / d - static_cast<double>(numerator) / denominator);

        i64 candidate_num = num1;
        i64 candidate_den = d;
        double current_diff = diff1;

        if (diff2 + 1e-9 < current_diff) {
            candidate_num = num2;
            candidate_den = d;
            current_diff = diff2;
        }

        i64 g = compute_gcd(candidate_num, candidate_den);
        candidate_num /= g;
        candidate_den /= g;

        if (current_diff < min_diff) {
            best_num = candidate_num;
            best_den = candidate_den;
            min_diff = current_diff;
        }
    }

    cout << best_num << "/" << best_den << endl;
    return 0;
}

