#include <iostream>
#include <cmath>

int main() {
    long long x, y, n, a, b;
    std::cin >> x >> y >> n;

    double minError = 1e12;
    long long num = 0, den = 0;

    for (b = 1; b <= n; b++) {
        a = x * b / y;

        // Try three candidate numerators: a-1, a, a+1
        for (long long k = -1; k <= 1; k++) {
            long long candidate = a + k;
            if (candidate <= 0) continue;

            long long diff = x * b - candidate * y;
            double error = std::abs(static_cast<double>(diff) / (y * b));

            if (diff == 0) {
                std::cout << candidate << "/" << b << std::endl;
                return 0;
            }

            if (error < minError) {
                minError = error;
                num = candidate;
                den = b;
            }
        }
    }

    std::cout << num << "/" << den << std::endl;
    return 0;
}

