public class Main {
    static final long MOD = 1000000007L;
    static final int INF = 1000000000;
    static final long LINF = 1000000000000000000L;

    static long mygcd(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    static long mylcm(long a, long b) {
        return a / mygcd(a, b) * b;
    }

    static class Fraction {
        long num;
        long den;

        Fraction(long num, long den) {
            long g = mygcd(Math.abs(num), Math.abs(den));
            this.num = num / g;
            this.den = den / g;
            if (this.den < 0) {
                this.num = -this.num;
                this.den = -this.den;
            }
        }

        Fraction subtract(Fraction other) {
            long cz = mylcm(this.den, other.den);
            long ac = cz / this.den;
            long bc = cz / other.den;
            long rt = this.num * ac - other.num * bc;
            long gcdr = mygcd(Math.abs(rt), cz);
            return new Fraction(rt / gcdr, cz / gcdr);
        }

        Fraction abs() {
            if (this.num < 0) {
                return new Fraction(-this.num, this.den);
            }
            return this;
        }

        int compare(Fraction other) {
            long cz = mylcm(this.den, other.den);
            long ac = cz / this.den;
            long bc = cz / other.den;
            long na = this.num * ac;
            long nb = other.num * bc;
            if (na == nb) {
                return 0;
            }
            return na < nb ? -1 : 1;
        }
    }

    public static void main(String[] args) throws IOException {
