import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();

        if (y <= n) {
            long a = gcd(x, y);
            x = x / a;
            y = y / a;
            System.out.println(x + "/" + y);
            return;
        }

        if (x == y) {
            System.out.println("1/1");
            return;
        }

        double ans = 1e18;
        double xy = (double) x / (double) y;
        long ansx = 0, ansy = 0;
        long l = 0, r = y;

        for (long i = 1; i <= n; i++) {
            while (i * x > r) {
                l += y;
                r += y;
            }
            if (i * x >= l && i * x <= r) {
                long ll = l / y;
                long rr = r / y;
                double li = (double) ll / (double) i;
                double ri = (double) rr / (double) i;
                double tmp1 = Math.abs(xy - li);
                double tmp2 = Math.abs(xy - ri);
                if (tmp2 < tmp1) {
                    if ((float) tmp2 < (float) ans) {
                        ans = tmp2;
                        ansx = rr;
                        ansy = i;
                    }
                } else {
                    if ((float) tmp1 < (float) ans) {
                        ans = tmp1;
                        ansx = ll;
                        ansy = i;
                    }
                }
            }
        }

        long a = gcd(ansx, ansy);
        ansx /= a;
        ansy /= a;
        System.out.println(ansx + "/" + ansy);
