long long n, x, y;

long long gcd(long long a, long long b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

struct Fraction {
    long long numerator, denominator;

    Fraction() : numerator(0), denominator(1) {}
    Fraction(long long n, long long d) : numerator(n), denominator(d) {}

    void subtract(const Fraction& other) {
        numerator = numerator * other.denominator - other.numerator * denominator;
        denominator = denominator * other.denominator;
    }

    bool operator<(const Fraction& other) const {
        return numerator * other.denominator < other.numerator * denominator;
    }

    void simplify() {
        long long g = gcd(abs(numerator), abs(denominator));
        if (g > 0) {
            numerator /= g;
            denominator /= g;
        }
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
    }

    void display() const {
        cout << numerator << "/" << denominator;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> x >> y >> n;

    Fraction target(x, y);
    Fraction bestDiff(50, 1);
    Fraction bestFraction;

    for (long long i = 1; i <= n; ++i) {
        long long q = (target.numerator * i) / target.denominator;
        long long r = (target.numerator * i) % target.denominator;

        if (r > target.denominator / 2) {
            q++;
            r = target.denominator - r;
        }

        Fraction diff(r, i * target.denominator);
        diff.simplify();

        if (diff < bestDiff) {
            bestDiff = diff;
            bestFraction.numerator = q;
            bestFraction.denominator = i;
        }
    }

