using namespace std;

long long gcd(long long a, long long b) {
    while (b) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

long long lcm(long long a, long long b) {
    return a / gcd(a, b) * b;
}

int main() {
    long long x, y, n;
    cin >> x >> y >> n;

    long long best_num = 1, best_den = 1;
    double min_error = 1e18;

    if (y <= n) {
        long long g = gcd(x, y);
        x /= g;
        y /= g;
        cout << x << "/" << y;
        return 0;
    }

    for (long long d = 1; d <= n; ++d) {
        long long L = lcm(d, y);
        long long numerator = x * (L / y);
        long long step = L / d;

        // floor candidate
        long long q1 = numerator / step;
        long long approx1 = q1 * step;
        double err1 = fabs((double)numerator - approx1) / L;
        if (err1 < min_error) {
            min_error = err1;
            best_num = q1;
            best_den = d;
        }

        // ceil candidate
        long long q2 = (numerator + step - 1) / step;
        long long approx2 = q2 * step;
        double err2 = fabs((double)numerator - approx2) / L;
        if (err2 < min_error) {
            min_error = err2;
            best_num = q2;
            best_den = d;
        }
    }

    long long g = gcd(best_num, best_den);
    best_num /= g;
    best_den /= g;

    cout << best_num << "/" << best_den;
    return 0;
}

