        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();

        java.math.BigDecimal target = new java.math.BigDecimal(x).divide(new java.math.BigDecimal(y), 30, java.math.RoundingMode.HALF_UP);

        long bestA = 1;
        long bestB = 1;
        java.math.BigDecimal bestError = error(x, y, 1, 1);

        for (long b = 1; b <= n; ++b) {
            java.math.BigDecimal targetTimesB = target.multiply(new java.math.BigDecimal(b));
            long aFloor = targetTimesB.longValue();
            long aCeil = (targetTimesB.compareTo(new java.math.BigDecimal(aFloor)) > 0) ? aFloor + 1 : aFloor;

            // Try floor candidate
            java.math.BigDecimal errFloor = error(x, y, aFloor, b);
            if (errFloor.compareTo(bestError) < 0) {
                bestError = errFloor;
                bestA = aFloor;
                bestB = b;
            }

            // Try ceil candidate if different from floor
            if (aFloor != aCeil) {
                java.math.BigDecimal errCeil = error(x, y, aCeil, b);
                if (errCeil.compareTo(bestError) < 0) {
                    bestError = errCeil;
                    bestA = aCeil;
                    bestB = b;
                }
            }
        }

        System.out.println(bestA + "/" + bestB);
    }

    private static java.math.BigDecimal error(long x, long y, long a, long b) {
        if (b == 0) {
            return new java.math.BigDecimal("1e30");
        }
        java.math.BigDecimal target = new java.math.BigDecimal(x).divide(new java.math.BigDecimal(y), 30, java.math.RoundingMode.HALF_UP);
        java.math.BigDecimal fraction = new java.math.BigDecimal(a).divide(new java.math.BigDecimal(b), 30, java.math.RoundingMode.HALF_UP);
        return target.subtract(fraction).abs();
    }
}

