    double x,y,n,a,b;
    double min;
    int mina, minb;
    min = 1000000;

    cin>>x>>y>>n;

    if (n > y){
        int gc = gcd (x, y);
        if (gc != 1){       
            x = x/gc;
            y = y/gc;
        }
        cout<<x<<"/"<<y<<endl;
        return 0;
    }

    for (b = n; b >= 1; b--)
    {
        a = (x*b)/y;
