import java.util.*;
import java.io.*;

public class Main {
    static int findGCD(int a, int b) {
        int candidate = (a > b) ? a : b;
        while (true) {
            if (a % candidate == 0 && b % candidate == 0) break;
            --candidate;
        }
        return candidate;
    }

    static double computeAbsDiff(double x, double y, double p, double q, double[] result) {
        result[0] = Math.abs(x * q - y * p);
        result[1] = y * q;
        return result[0] / result[1];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        double x = Double.parseDouble(input[0]);
        double y = Double.parseDouble(input[1]);
        double n = Double.parseDouble(input[2]);

        double minError = Double.MAX_VALUE;
        int bestA = 0;
        int bestB = 1;

        if (n > y) {
            int g = findGCD((int)x, (int)y);
            if (g != 1) {
                x /= g;
                y /= g;
            }
            System.out.println((int)x + "/" + (int)y);
            return;
        }

        for (int b = (int)n; b >= 1; --b) {
            double a_candidate = (x * b) / y;
            if (a_candidate == Math.floor(a_candidate)) {
                bestA = (int)a_candidate;
                bestB = b;
                break;
            } else {
                double[] result1 = new double[2];
                double err1 = computeAbsDiff(x, y, Math.floor(a_candidate), b, result1);
                if (err1 < minError || (Math.abs(err1 - minError) < 1e-12 && (int)Math.floor(a_candidate) < bestA)) {
                    bestA = (int)Math.floor(a_candidate);
                    bestB = b;
                    minError = err1;
                }

                double[] result2 = new double[2];
                double err2 = computeAbsDiff(x, y, Math.ceil(a_candidate), b, result2);
                if (err2 < minError || (Math.abs(err2 - minError) < 1e-12 && (int)Math.ceil(a_candidate) < bestA)) {
                    bestA = (int)Math.ceil(a_candidate);
                    bestB = b;
                    minError = err2;
                }
            }
        }

        int g = findGCD(bestA, bestB);
        if (g != 1) {
            bestA /= g;
            bestB /= g;
        }

        System.out.println(bestA + "/" + bestB);
    }
}

