#include <iostream>
#include <cmath>
#include <vector>

using namespace std;

int greatestCommonDivisor(int p, int q) {
    int g = max(p, q);
    while (true) {
        if (p % g == 0 && q % g == 0) break;
        g--;
    }
    return g;
}

double absoluteDifference(double x, double y, double m, double d, double& num, double& den) {
    num = fabs(x * d - y * m);
    den = y * d;
    return num / den;
}

int main() {
    double x, y, n;
    double smallestError = 1e10;
    int numerator = 0, denominator = 1;

    cin >> x >> y >> n;

    if (n > y) {
        int g = greatestCommonDivisor((int)x, (int)y);
        if (g != 1) {
            x /= g;
            y /= g;
        }
        cout << (int)x << "/" << (int)y << endl;
        return 0;
    }

    for (int b = (int)n; b >= 1; --b) {
        double a_val = (x * b) / y;
        if (a_val == floor(a_val)) {
            numerator = (int)a_val;
            denominator = b;
            break;
        } else {
            double num1, den1;
            double error1 = absoluteDifference(x, y, floor(a_val), b, num1, den1);
            if (error1 < smallestError || (fabs(error1 - smallestError) < 1e-12 && (int)floor(a_val) < numerator)) {
                numerator = (int)floor(a_val);
                denominator = b;
                smallestError = error1;
            }

            double num2, den2;
            double error2 = absoluteDifference(x, y, ceil(a_val), b, num2, den2);
            if (error2 < smallestError || (fabs(error2 - smallestError) < 1e-12 && (int)ceil(a_val) < numerator)) {
                numerator = (int)ceil(a_val);
                denominator = b;
                smallestError = error2;
            }
        }
    }

    int g = greatestCommonDivisor(numerator, denominator);
    if (g != 1) {
        numerator /= g;
        denominator /= g;
    }

    cout << numerator << "/" << denominator << endl;

    return 0;
}

