import java.util.*;
import java.io.*;

public class Main {
    static final int mod1 = 998244353;
    static final int mod2 = 1000000007;
    static final int N = 2000000;
    static final int MX = 1000000;

    static long n, c;
    static int tot, ans, lim;
    static int[] pw = new int[9];
    static int[] sum = new int[7];
    static ArrayList<Integer>[] ve = new ArrayList[7];

    static int dec(int x, int y, int mod) {
        return (x - y < 0) ? x - y + mod : x - y;
    }

    static int add(int x, int y, int mod) {
        return (x + y >= mod) ? x + y - mod : x + y;
    }

    static void dfs(int pos, int now) {
        if (now <= n) {
            ++tot;
            int x = dec(tot, now, mod1);
            ve[pos - 1].add(x);
            sum[pos - 1] = add(sum[pos - 1], x, mod2);
        }
        if (pos > 6) return;
        for (int i = 0; i <= 9; ++i) {
            dfs(pos + 1, now * 10 + i);
        }
    }

    static void solve(int pos, long now) {
        if (now > n) return;
        if (pos > 1) {
            if (10L * now * MX > n && 1L * (now + 1) * MX - 1 <= n) {
                for (int i = 0; i < 7; ++i) {
                    long x = ((c - 1L * now * pw[i]) % mod1 + mod1) % mod1;
                    int xi = (int)x;
                    int p = lowerBound(ve[i], mod1 - xi);
                    int temp1 = (int)((1L * x * ve[i].size()) % mod2);
                    int temp2 = add(temp1, sum[i], mod2);
                    ans = add(ans, temp2, mod2);
                    ans = dec(ans, (int)((1L * mod1 * (ve[i].size() - p)) % mod2), mod2);
                }
                c += tot;
                return;
            }
            ++c;
            int val = (int)(((c - now) % mod1 + mod1) % mod1);
            ans = add(ans, val, mod2);
        }
        for (int i = (pos == 1 ? 1 : 0); i <= 9; ++i) {
            solve(pos + 1, now * 10 + i);
        }
    }

    static int lowerBound(ArrayList<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < target) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Long.parseLong(br.readLine());

        for (int i = 0; i < 7; i++) {
            ve[i] = new ArrayList<>();
        }

        pw[0] = 1;
        for (int i = 1; i < 9; ++i) {
            pw[i] = 10 * pw[i - 1];
        }

        dfs(1, 0);

        for (int i = 0; i < 7; ++i) {
            Collections.sort(ve[i]);
        }

        solve(1, 0);

        System.out.println(ans);
    }
}

