    static long counter_c;
    static int node_counter;
    static int final_output;
    static int boundary_condition;
    static long[] base10 = new long[2000000];
    static int[] running_sum = new int[2000000];
    static List<Integer>[] bucket = new List[2000000];

    static int safe_subtract(int first, int second, long modulo) {
        if (first - second < 0) return first - second + (int)modulo;
        return first - second;
    }

    static int safe_add(int first, int second, long modulo) {
        if (first + second >= (int)modulo) return first + second - (int)modulo;
        return first + second;
    }

    static void recursive_build(int depth, int current_number) {
        if (current_number <= input_n) {
            node_counter++;
            int temp = safe_subtract(node_counter, current_number, MOD1);
            bucket[depth - 1].add(temp);
            running_sum[depth - 1] = safe_add(running_sum[depth - 1], temp, MOD2);
        }
        if (depth > 6) return;
        for (int digit = 0; digit <= 9; digit++) {
            recursive_build(depth + 1, current_number * 10 + digit);
        }
    }

    static void recursive_compute(int depth, long current_value) {
        if (current_value > input_n) return;
        if (depth > 1) {
            if (10L * current_value * LIMIT_MAX > input_n &&
                1L * (current_value + 1) * LIMIT_MAX - 1 <= input_n) {
                for (int index = 0; index < 7; index++) {
                    long temp = counter_c - current_value * base10[index];
                    temp %= MOD1;
                    if (temp < 0) temp += MOD1;
                    int value = (int)temp;
                    List<Integer> list = bucket[index];
                    int pos = lowerBound(list, (int)(MOD1) - value);
                    int add_part1 = (int)(1L * value * list.size() % MOD2);
                    int add_part2 = running_sum[index];
                    int combined = safe_add(add_part1, add_part2, MOD2);
                    final_output = safe_add(final_output, combined, MOD2);
                    int subtract_part = (int)(1L * MOD1 * (list.size() - pos) % MOD2);
                    final_output = safe_subtract(final_output, subtract_part, MOD2);
                }
                counter_c += node_counter;
                return;
            }
            counter_c++;
            int diff = (int)(((counter_c - current_value) % MOD1 + MOD1) % MOD1);
            final_output = safe_add(final_output, diff, MOD2);
        }
        int start_digit = (depth == 1) ? 1 : 0;
        for (int digit = start_digit; digit <= 9; digit++) {
            recursive_compute(depth + 1, current_value * 10 + digit);
        }
    }

    static int lowerBound(List<Integer> list, int target) {
        int left = 0, right = list.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (list.get(mid) >= target) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
