const llong MOD1 = 998244353LL;
const llong MOD2 = 1000000007LL;
const llong P10[7] = {1LL, 10LL, 100LL, 1000LL, 10000LL, 100000LL, 1000000LL};

llong acc[7] = {};
llong result = 0;
llong N;
llong idx1 = 0, idx2 = -1;
vector<llong> groups[7];

void precompute(int depth, llong cur) {
    if (depth == 7) return;
    llong diff = (idx1 - cur + MOD1) % MOD1;
    groups[depth].push_back(diff);
    acc[depth] = (acc[depth] + diff) % MOD1;
    idx1++;
    for (int dig = 0; dig <= 9; ++dig) {
        precompute(depth + 1, cur * 10 + dig);
    }
}

bool inRange(llong prefix) {
    return prefix * P10[6] + 999999 <= N && prefix * P10[6] * 10 > N;
}

void explore(int depth, llong cur) {
    if (cur > N) return;
    if (inRange(cur)) {
        for (int i = 0; i <= 6; ++i) {
            llong needed = (idx2 + 1 - cur * P10[i]) % MOD1;
            if (needed < 0) needed += MOD1;
            llong pos = lower_bound(groups[i].begin(), groups[i].end(), MOD1 - needed) - groups[i].begin();
            llong part = (acc[i] + needed * (llong)groups[i].size() - MOD1 * ((llong)groups[i].size() - pos)) % MOD2;
            result = (result + part) % MOD2;
        }
        idx2 += idx1;
        return;
    }
    idx2++;
    llong term = ((idx2 - cur) % MOD1 + MOD1) % MOD1;
    result = (result + term) % MOD2;
    for (int dig = (depth == 0 ? 1 : 0); dig <= 9; ++dig) {
        explore(depth + 1, cur * 10 + dig);
    }
