const int MOD = 998244353;
const int MOD2 = 1000000007;

namespace IO {
    static const int BUF_SIZE = 1 << 21;
    static char buf[BUF_SIZE];
    static int pos = BUF_SIZE;

    inline char get_char() {
        if (pos == BUF_SIZE) {
            pos = 0;
            fread(buf, 1, BUF_SIZE, stdin);
        }
        return buf[pos++];
    }

    template<typename T>
    inline T read_int() {
        char c;
        while ((c = get_char()) < '0' || c > '9') {
            if (c == '-') {
                T res = 0;
                while ((c = get_char()) >= '0' && c <= '9') res = res * 10 + (c - '0');
                return -res;
            }
        }
        T res = c - '0';
        while ((c = get_char()) >= '0' && c <= '9') res = res * 10 + (c - '0');
        return res;
    }

    static char out_buf[BUF_SIZE];
    static int out_pos = 0;

    inline void flush_out() {
        fwrite(out_buf, 1, out_pos, stdout);
        out_pos = 0;
    }

    inline void put_char(char c) {
        out_buf[out_pos++] = c;
        if (out_pos >= BUF_SIZE) flush_out();
    }

    template<typename T>
    inline void write_int(T x, char sep = '\n') {
        if (x < 0) { put_char('-'); x = -x; }
        if (x == 0) { put_char('0'); if (sep != -1) put_char(sep); return; }
        char tmp[20];
        int len = 0;
        while (x) { tmp[len++] = '0' + x % 10; x /= 10; }
        while (len--) put_char(tmp[len]);
