namespace IO {
    static const int BSIZE = 1 << 21;
    static char inbuf[BSIZE], *inptr = inbuf, *inend = inbuf;
    static char outbuf[BSIZE], *outptr = outbuf;

    inline int getc() {
        if (inptr == inend) {
            inend = inbuf + fread(inbuf, 1, BSIZE, stdin);
            inptr = inbuf;
        }
        return (inptr == inend) ? EOF : *inptr++;
    }

    template<typename T>
    inline T read() {
        char c;
        while ((c = getc()) < '0' || c > '9') {
            if (c == EOF) return -1;
            if (c == '-') {
                T res = 0;
                while ((c = getc()) >= '0' && c <= '9') res = res * 10 + (c - '0');
                return -res;
            }
        }
        T res = c - '0';
        while ((c = getc()) >= '0' && c <= '9') res = res * 10 + (c - '0');
        return res;
    }

    inline void putc(char c) {
        *outptr++ = c;
        if (outptr - outbuf >= BSIZE) flush();
    }

    inline void flush() {
        fwrite(outbuf, 1, outptr - outbuf, stdout);
        outptr = outbuf;
    }

    template<typename T>
    inline void print(T x, char sep = '\n') {
        if (x < 0) { putc('-'); x = -x; }
        if (x == 0) { putc('0'); if (sep != -1) putc(sep); return; }
        char tmp[20];
        int len = 0;
        while (x) { tmp[len++] = '0' + x % 10; x /= 10; }
        while (len--) putc(tmp[len]);
        if (sep != -1) putc(sep);
    }

    inline void print(const char* s) {
        while (*s) putc(*s++);
    }
}

