#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int M1 = 1000000007;

struct Mint {
    int val;
    Mint(int v = 0) : val(v % M1) { if (val < 0) val += M1; }
    int get() const { return val; }
};

Mint operator+(Mint a, Mint b) { return a.val + b.val >= M1 ? a.val + b.val - M1 : a.val + b.val; }
Mint operator-(Mint a, Mint b) { return a.val >= b.val ? a.val - b.val : a.val - b.val + M1; }
Mint operator*(Mint a, Mint b) { return static_cast<ll>(a.val) * b.val % M1; }

Mint fast_pow(Mint b, int e) {
    Mint r = 1;
    for (; e; e /= 2, b = b * b) if (e & 1) r = r * b;
    return r;
}

const int M2 = 998244353;
const int P = 1000000;
const int LIMIT = 6;

ll n;
ll idx;
int suf_cnt;
Mint prefix_sum[LIMIT + 2];
vector<int> suffixes[LIMIT + 2];

void build_dfs(int level, ll num) {
    int val = ((idx++ - num) % M2 + M2) % M2;
    prefix_sum[level] = prefix_sum[level] + val;
    suffixes[level].push_back(val);
    if (level == LIMIT) return;
    for (int d = 0; d < 10; ++d) {
        build_dfs(level + 1, num * 10 + d);
    }
}

void solve_dfs(ll num) {
    if (num >= n) return;
    if ((num + 1) * P <= n && num * P * 10 >= n) {
        ll factor = 1;
        for (int lv = 0; lv <= LIMIT; ++lv) {
            int sz = suffixes[lv].size();
            int offset = ((idx - factor * num) % M2 + M2) % M2;
            int threshold = (M2 - offset) % M2;
            int matches = lower_bound(suffixes[lv].begin(), suffixes[lv].end(), threshold) - suffixes[lv].begin();
            prefix_sum[LIMIT + 1] = prefix_sum[LIMIT + 1] + Mint(sz) * offset + prefix_sum[lv] - (sz - matches) * M2;
            factor *= 10;
        }
        idx += suf_cnt;
        return;
    }
    prefix_sum[LIMIT + 1] = prefix_sum[LIMIT + 1] + Mint(((idx++ - num) % M2 + M2) % M2);
    for (int d = 0; d < 10; ++d) {
        solve_dfs(num * 10 + d);
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> n;
    ++n;
    build_dfs(0, 0);
