        if (cur >= limit) return;
        if ((cur + 1) * STEP <= limit && cur * STEP * 10 >= limit) {
            long multiplier = 1;
            for (int lvl = 0; lvl <= LEVELS; ++lvl) {
                long sz = tail_vals[lvl].size();
                long shift = ((cursor - multiplier * cur) % P2 + P2) % P2;
                long limit_val = (P2 - shift) % P2;
                long matches = lower_bound(tail_vals[lvl], limit_val);
                ModNum term1 = mul(new ModNum(sz), new ModNum(shift));
                ModNum term2 = row_sum[lvl];
                ModNum term3 = new ModNum((sz - matches) * P2);
                row_sum[LEVELS + 1] = add(add(row_sum[LEVELS + 1], term1), sub(term2, term3));
                multiplier *= 10;
            }
            cursor += total_count;
            return;
        }
        long term = ((cursor++ - cur) % P2 + P2) % P2;
        row_sum[LEVELS + 1] = add(row_sum[LEVELS + 1], new ModNum(term));
        for (int d = 0; d < 10; ++d)
            solve_subtree(cur * 10 + d);
    }

    static long lower_bound(List<Long> list, long value) {
        int low = 0;
        int high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) < value) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        limit = Long.parseLong(br.readLine());
        ++limit;

        for (int i = 0; i <= LEVELS + 1; ++i) {
            row_sum[i] = new ModNum(0);
            tail_vals[i] = new ArrayList<>();
        }

        build_layer(0, 0);
        for (int i = 0; i <= LEVELS; ++i) {
            total_count += tail_vals[i].size();
            Collections.sort(tail_vals[i]);
        }
        cursor = 1;
        for (int d = 1; d < 10; ++d)
            solve_subtree(d);
        System.out.println(row_sum[LEVELS + 1].value());
    }
}

