LL answer = 0;

void generate_second(LL depth, LL current) {
    if (current > N) return;

    if (current * 1000000 + 999999 <= N && current * 10000000 > N) {
        for (LL d = 0; d <= 6; ++d) {
            LL needed = ((counter2 + 1 - current * mod_pow(10, d, MOD1) % MOD1) % MOD1 + MOD1) % MOD1;
            auto it = lower_bound(first_digits[d].begin(), first_digits[d].end(), needed);
            LL idx = it - first_digits[d].begin();
            LL contribution = (first_sum[d] + needed * (LL)first_digits[d].size() % MOD1 - MOD1 * (first_digits[d].size() - idx)) % MOD1;
            answer = (answer + contribution) % MOD2;
        }
        counter2 = (counter2 + counter1) % MOD1;
        return;
    }

    counter2 = (counter2 + 1) % MOD1;
    answer = (answer + ((counter2 - current) % MOD1 + MOD1) % MOD1) % MOD2;

    for (LL digit = 0; digit <= 9; ++digit) {
        if (!depth && !digit) continue;
