        while (c >= '0' && c <= '9') {
            x = x * 10 + (c - '0');
            c = System.in.read();
        }
        return x;
    }

    private static long mod2(long x) {
        x %= MOD2;
        return x < 0 ? x + MOD2 : x;
    }

    private static void buildPhase(long cur, int depth) {
        ++globalCounter;
        long value = mod2(globalCounter - cur);
        level[depth].add(value);
        levelTotal[depth] = (levelTotal[depth] + value) % MOD1;
        if (depth == 6) return;
        for (long digit = 0; digit < 10; ++digit) {
            buildPhase(cur * 10 + digit, depth + 1);
        }
    }

