import java.util.*;
import java.io.*;

public class Main {
    static final int P = 998244353;
    static final int mod = 1000000007;
    static final long B = 1000000;

    static long n;
    static long cnt;
    static long[] s = new long[7];
    static int ans;
    static ArrayList<Integer>[] p = new ArrayList[7];

    static int m(long d) {
        return (int)((d % P + P) % P);
    }

    static void dfs0(int d, long v) {
        cnt++;
        p[d].add(m(cnt - v));
        if (d < 6) {
            for (int i = 0; i <= 9; i++) {
                dfs0(d + 1, v * 10 + i);
            }
        }
    }

    static int calc(int id, int f) {
        ArrayList<Integer> list = p[id];
        int ps = Collections.binarySearch(list, P - f);
        if (ps < 0) ps = -ps - 1;
        long result = (long)f * list.size() + s[id] - (long)P * (list.size() - ps);
        return (int)((result % mod + mod) % mod);
    }

    static void dfs1(int d, long v) {
        if (v > n) return;
        if (d >= 1) {
            if (v * B > n / 10 && v * B + B - 1 <= n) {
                int t = 1;
                for (int i = 0; i <= 6; i++) {
                    ans = (ans + calc(i, m(cnt - v * t))) % mod;
                    t *= 10;
                }
                for (int i = 0; i <= 6; i++) {
                    cnt += p[i].size();
                }
                return;
            }
            ans = (ans + m(++cnt - v)) % mod;
        }
        int start = (d == 0) ? 0 : 0;
        for (int i = start; i <= 9; i++) {
            dfs1(d + 1, v * 10 + i);
        }
    }

