#include <bits/stdc++.h>
#define ll long long
using namespace std;
const int MOD1 = 998244353, MOD2 = 1000000007, BLOCK_SIZE = 1000000;
int mod1(ll x) { return (x % MOD1 + MOD1) % MOD1; }
ll n, total_count, prefix_sum[7];
int result;
vector<int> residues[7];

void precompute(int depth, ll value) {
    total_count++;
    residues[depth].push_back(mod1(total_count - value));
    if (depth < 6) {
        for (int digit = 0; digit <= 9; ++digit) {
            precompute(depth + 1, value * 10 + digit);
        }
    }
}

int compute_contribution(int idx, int offset) {
    int pos = lower_bound(residues[idx].begin(), residues[idx].end(), MOD1 - offset) - residues[idx].begin();
    ll part1 = (ll)offset * residues[idx].size();
    ll part2 = prefix_sum[idx];
    ll part3 = (ll)MOD1 * (residues[idx].size() - pos);
    return (int)((part1 + part2 - part3) % MOD2);
}

void enumerate(int depth, ll value) {
    if (value > n) return;
    if (depth >= 1) {
        if (value * BLOCK_SIZE > n / 10 && value * BLOCK_SIZE + BLOCK_SIZE - 1 <= n) {
            int multiplier = 1;
            for (int i = 0; i <= 6; ++i) {
                result = (result + compute_contribution(i, mod1(total_count - value * multiplier))) % MOD2;
                multiplier *= 10;
            }
            for (int i = 0; i <= 6; ++i) {
                total_count += residues[i].size();
            }
            return;
        }
        result = (result + mod1(++total_count - value)) % MOD2;
    }
    for (int digit = (depth == 0 ? 1 : 0); digit <= 9; ++digit) {
        enumerate(depth + 1, value * 10 + digit);
    }
}

int main() {
    scanf("%lld", &n);
    precompute(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(residues[i].begin(), residues[i].end());
        for (size_t j = 0; j < residues[i].size(); ++j) {
            prefix_sum[i] += residues[i][j];
        }
    }
    total_count = 0;
    enumerate(0, 0);
    printf("%d\n", result);
    return 0;
}

