    static final int BASE_VALUE = 1000000;

    static long answer;
    static List<Long>[] digitBuckets = new List[7];
    static long[] digitSums = new long[7];
    static long phase1Counter = 0;
    static long phase2Counter = 0;

    static int mod1reduce(long x) {
        return (int)((x % MOD1 + MOD1) % MOD1);
    }

    static void collectPhase1(int depth, int currentNumber) {
        digitBuckets[depth].add((long)mod1reduce((int)(phase1Counter - currentNumber)));
        phase1Counter++;
        if (depth == 6) return;
        for (int digit = 0; digit < 10; ++digit) {
            collectPhase1(depth + 1, currentNumber * 10 + digit);
        }
    }

    static void computePhase2(int depth, long currentNumber) {
        if (currentNumber > answer) return;
        if (currentNumber * BASE_VALUE + 999999 <= answer && currentNumber * BASE_VALUE * 10 > answer) {
            for (int idx = 0, power = 1, boundary; idx < 7; ++idx, power *= 10) {
                long diff = mod1reduce((int)(phase2Counter - currentNumber * power + 1));
                List<Long> bucket = digitBuckets[idx];
                int boundaryIdx = Collections.binarySearch(bucket, MOD1 - diff);
                if (boundaryIdx < 0) boundaryIdx = -(boundaryIdx + 1);
                boundary = boundaryIdx;
                answer = (answer + diff * bucket.size() + digitSums[idx] - MOD1 * (bucket.size() - boundary)) % MOD2;
            }
            phase2Counter += phase1Counter;
        } else {
            phase2Counter++;
            answer = (answer + mod1reduce((int)(phase2Counter - currentNumber))) % MOD2;
            for (int digit = (depth == 0 ? 1 : 0); digit < 10; ++digit) {
                computePhase2(depth + 1, currentNumber * 10 + digit);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        // Initialize digitBuckets
        for (int i = 0; i < 7; i++) {
            digitBuckets[i] = new ArrayList<>();
        }

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        answer = Long.parseLong(br.readLine());

        collectPhase1(0, 0);
        for (int i = 0; i < 7; ++i) {
            Collections.sort(digitBuckets[i]);
            for (long v : digitBuckets[i]) {
                digitSums[i] += v;
            }
        }
        phase2Counter = -1;
        computePhase2(0, 0);
        System.out.println(answer);
    }
}

