public class Main {
    static final long MOD1 = 998244353L;
    static final long MOD2 = 1000000007L;
    static final long INF = 2000000007L;

    static class IStream {
        private InputStream input;
        private byte[] buffer;
        private int curChar;
        private int numChars;

        public IStream() {
            input = System.in;
            buffer = new byte[1024];
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = input.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    static class OStream {
        private PrintStream output;

        public OStream() {
            output = System.out;
        }

        public void print(char c) {
            output.print(c);
        }

        public void print(long val) {
            if (val < 0) {
                output.print('-');
                val = -val;
            }
            if (val > 9) {
                print(val / 10);
            }
            output.print((int)(val % 10 + '0'));
        }

        public void println(long val) {
            print(val);
            output.println();
        }
    }

    static IStream input = new IStream();
    static OStream output = new OStream();

    static int adjust(long x) {
        return (int)(((x % MOD1) + MOD1) % MOD1);
    }

    static long N_val;
    static List<Long>[] partition = new List[7];
    static long[] partitionSum = new long[7];
    static long step1 = 0, step2 = 0;

    @SuppressWarnings("unchecked")
    public static void setup(int depth, int current) {
        partition[depth].add((long)adjust((int)(step1 - current)));
        ++step1;
        if (depth == 6) return;
        for (int digit = 0; digit < 10; ++digit) {
            setup(depth + 1, current * 10 + digit);
        }
    }

    static final int WIDTH = 1000000;

    static void solve(int depth, long current) {
        if (current > N_val) return;
        if (current * WIDTH + 999999 <= N_val && current * WIDTH * 10 > N_val) {
            for (int i = 0, mul = 1; i < 7; ++i, mul *= 10) {
                long delta = adjust((int)(step2 - current * mul + 1));
                int idx = lowerBound(partition[i], MOD1 - delta);
                N_val = (N_val + delta * partition[i].size() + partitionSum[i] - MOD1 * (partition[i].size() - idx)) % MOD2;
            }
            step2 += step1;
        } else {
            ++step2;
            N_val = (N_val + adjust((int)(step2 - current))) % MOD2;
            for (int digit = (depth == 0 ? 1 : 0); digit < 10; ++digit) {
                solve(depth + 1, current * 10 + digit);
            }
        }
    }

    static int lowerBound(List<Long> list, long key) {
        int low = 0;
        int high = list.size();
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (list.get(mid) < key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) {
        for (int i = 0; i < 7; ++i) {
            partition[i] = new ArrayList<>();
        }
        N_val = input.nextLong();
        setup(0, 0);
        for (int i = 0; i < 7; ++i) {
            Collections.sort(partition[i]);
            for (long v : partition[i]) {
                partitionSum[i] += v;
            }
        }
        step2 = -1;
        solve(0, 0);
        output.print(N_val);
    }
}

