i64 normalize(i64 x) {
    return ((x % MOD1) + MOD1) % MOD1;
}

void build_buckets(int depth, i64 prefix) {
    count_val++;
    digit_buckets[depth].push_back(normalize(count_val - prefix));
    if (depth == 6) return;
    for (int d = 0; d <= 9; d++) {
        build_buckets(depth + 1, prefix * 10 + d);
    }
}

void search(int depth, i64 current) {
    if (current > N) return;

    if (depth >= 1) {
