    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();

        long N = sc.nextLong();

        final long BLOCK_SIZE = 1000000;
        final long MOD1 = 998244353L;
        final long MOD2 = 1000000007L;

        List<List<Long>> digit_buckets = new ArrayList<>();
        for (int i = 0; i <= 6; i++) {
            digit_buckets.add(new ArrayList<>());
        }

        long[] bucket_totals = new long[7];
        long[] answer = {0};
        long[] count_val = {0};
        long[] total_count = {0};

        // Build buckets
        build_buckets(0, 0, digit_buckets, count_val, MOD1);

        // Sort and compute bucket totals
        for (int i = 0; i <= 6; i++) {
            Collections.sort(digit_buckets.get(i));
            long sum = 0;
            for (long val : digit_buckets.get(i)) {
                sum = (sum + val) % MOD2;
            }
            bucket_totals[i] = sum;
        }

        total_count[0] = count_val[0];
        count_val[0] = 0;

        // Search
        search(0, 0, N, digit_buckets, bucket_totals, count_val, total_count, answer, BLOCK_SIZE, MOD1, MOD2);

        long result = (answer[0] % MOD2 + MOD2) % MOD2;
        System.out.println(result);
    }

    static long normalize(long x, long MOD1) {
        return ((x % MOD1) + MOD1) % MOD1;
    }

    static void build_buckets(int depth, long prefix, List<List<Long>> digit_buckets, long[] count_val, long MOD1) {
        count_val[0]++;
        digit_buckets.get(depth).add(normalize(count_val[0] - prefix, MOD1));
        if (depth == 6) return;
        for (int d = 0; d <= 9; d++) {
            build_buckets(depth + 1, prefix * 10 + d, digit_buckets, count_val, MOD1);
        }
    }

    static void search(int depth, long current, long N, List<List<Long>> digit_buckets, long[] bucket_totals, 
                       long[] count_val, long[] total_count, long[] answer, long BLOCK_SIZE, long MOD1, long MOD2) {
        if (current > N) return;

        if (depth >= 1) {
            if (current * BLOCK_SIZE > N / 10 && (current + 1) * BLOCK_SIZE - 1 <= N) {
                long factor = 1;
                for (int i = 0; i <= 6; i++, factor *= 10) {
                    long complement = normalize(total_count[0] - factor * current, MOD1);
                    List<Long> bucket = digit_buckets.get(i);
                    int pos = lowerBound(bucket, MOD1 - complement);
                    long part1 = factor * bucket.size() % MOD2 * complement % MOD2;
                    long part2 = (bucket_totals[i] - MOD1 * (bucket.size() - pos)) % MOD2;
                    answer[0] = (answer[0] + part1 + part2) % MOD2;
                }
                count_val[0] += total_count[0];
                return;
            }
            count_val[0]++;
            answer[0] = (answer[0] + normalize(count_val[0] - current, MOD2)) % MOD2;
        }

        for (int d = (depth == 0 ? 1 : 0); d <= 9; d++) {
            search(depth + 1, current * 10 + d, N, digit_buckets, bucket_totals, count_val, total_count, answer, BLOCK_SIZE, MOD1, MOD2);
        }
    }

    static int lowerBound(List<Long> list, long value) {
        int left = 0;
        int right = list.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (list.get(mid) >= value) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }
}

