import java.util.*;

public class Main {
    static final long MOD1 = 998244353;
    static final long MOD2 = 1000000007;
    static final long[] POW = {1, 10, 100, 1000, 10000, 100000, 1000000};

    static List<Long>[] val = new List[10];
    static long n;
    static long cnt1 = 0;
    static long cnt2 = 0;
    static long ans = 0;
    static long[] sum = new long[10];

    static boolean check(long x) {
        long now = 1000000;
        return x * now + 999999 <= n && x * now * 10 > n;
    }

    static void dfs1(int x1, long x2) {
        if (x1 == 7) return;
        val[x1].add((cnt1 - x2 + MOD1) % MOD1);
        sum[x1] = (sum[x1] + (cnt1 - x2 + MOD1) % MOD1) % MOD1;
        cnt1++;
        for (int i = 0; i <= 9; i++) {
            dfs1(x1 + 1, x2 * 10 + i);
        }
    }

    static void dfs2(int x1, long x2) {
        if (x2 > n) return;
        if (check(x2)) {
            for (int i = 0; i <= 6; i++) {
                long now = ((cnt2 + 1 - (x2 * POW[i])) % MOD1 + MOD1) % MOD1;
                int pos = lowerBound(val[i], now);
                long part1 = sum[i];
                long part2 = (now * (val[i].size() - pos)) % MOD1;
                long total = (part1 + part2 - (MOD1 * (val[i].size() - pos)) % MOD1 + MOD1) % MOD1;
                ans = (ans + total) % MOD2;
            }
            cnt2 += cnt1;
        } else {
            cnt2++;
            long val = ((cnt2 - x2) % MOD1 + MOD1) % MOD1;
            ans = (ans + val) % MOD2;
            for (int i = (x1 == 0 ? 0 : 1); i <= 9; i++) {
                dfs2(x1 + 1, x2 * 10 + i);
            }
        }
    }

    static int lowerBound(List<Long> list, long key) {
        int left = 0;
        int right = list.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (list.get(mid) >= key) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

