        long num = 0;
        int c;
        boolean neg = false;
        while ((c = System.in.read()) >= 0 && (c < '0' || c > '9')) {
            if (c == '-') neg = true;
        }
        while ((c = System.in.read()) >= 0 && c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');
        }
        return neg ? -num : num;
    }

    static void write(long x) throws IOException {
        if (x < 0) {
            System.out.print('-');
            write(-x);
            return;
