using namespace std;
using i64 = long long;
const i64 THRESHOLD = 1000000LL;
const i64 MOD_A = 998244353LL;
const i64 MOD_B = 1000000007LL;

i64 N, global_counter1 = 0, global_counter2 = 0;
int prefix_sums[10] = {0};
int final_result = 0;
vector<int> digit_sequences[10];

void recursive_build(int depth, i64 current_value) {
    if (depth > 6) return;
    int computed_value = ((++global_counter1) - current_value + MOD_A) % MOD_A;
    digit_sequences[depth].push_back(computed_value);
    prefix_sums[depth] = (prefix_sums[depth] + computed_value) % MOD_B;
    for (int digit = 0; digit <= 9; ++digit) {
        recursive_build(depth + 1, current_value * 10 + digit);
    }
}

void recursive_count(i64 current_value) {
    if (current_value > N) return;
    if (current_value < N / THRESHOLD && 10 * current_value > N / THRESHOLD) {
        for (int idx = 0, power = 1; idx <= 6; power *= 10, ++idx) {
            int complement = (global_counter2 + (i64)(MOD_A - power) * current_value + MOD_A) % MOD_A;
            int count = digit_sequences[idx].end() - lower_bound(digit_sequences[idx].begin(), digit_sequences[idx].end(), MOD_A - complement);
            final_result = (final_result + (i64)digit_sequences[idx].size() * complement + prefix_sums[idx] + (i64)(MOD_B - MOD_A) * count) % MOD_B;
        }
        global_counter2 += global_counter1;
        return;
    }
    ++global_counter2;
    final_result = (final_result + (global_counter2 - current_value % MOD_A + MOD_A) % MOD_A) % MOD_B;
    for (int digit = 0; digit <= 9; ++digit) {
        recursive_count(current_value * 10 + digit);
    }
