        if (depth > 6) return;
        int computed_value = (int)(((++global_counter1) - current_value + MOD_A) % MOD_A);
        digit_sequences[depth].add(computed_value);
        prefix_sums[depth] = (prefix_sums[depth] + computed_value) % (int)MOD_B;
        for (int digit = 0; digit <= 9; ++digit) {
