                long term3 = (MOD_B - MOD_A) * count;
                final_result = (int)(((long)final_result + term1 + term2 + term3) % MOD_B);
            }
            global_counter2 += global_counter1;
            return;
        }
        ++global_counter2;
        int val = (int)(((global_counter2 - current_value % MOD_A + MOD_A) % MOD_A) % MOD_B);
        final_result = (final_result + val) % (int)MOD_B;
