public class Main {
    private static List<Long> digits = new ArrayList<>();

    private static void show(String s, long v) {
        System.err.println(s + "=" + v);
    }

    private static long compute(long num, long depth) {
        long quotient = num / digits.get((int)depth);
        num %= digits.get((int)depth);
        if (num == 0) {
            return quotient * depth;
        }
        long option1 = depth + compute(digits.get((int)depth) - num, depth - 1);
        long option2 = compute(num, depth - 1);
        return quotient * depth + Math.min(option1, option2);
    }

