        long b = p[d];
        long q = x / b;
        long r = x % b;
        long res = q * d;
        if (r == 0) return res;
        long a1 = solve(r, d - 1);
        long a2 = d + solve(b - r, d - 1);
        return res + Math.min(a1, a2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        p[0] = 0;
        for (int i = 1; i < 17; i++) {
            p[i] = p[i-1] * 10 + 1;
        }

        n = scanner.nextLong();
        System.out.println(solve(n, 16));
    }
}

