import java.util.*;

public class Main {
    static long INF = 1000000000000000L;
    static int MAX_COST = 1000010;
    static ArrayList<Long> rep_units = new ArrayList<>();
    static int best = MAX_COST;

    static void dfs(long val, int depth) {
        if (depth >= best) return;

        if (val == 0) {
            best = depth;
            return;
        }

        int lo = 0, hi = 0;
        int left = 0, right = rep_units.size();

        // Binary search for lower_bound
        while (left < right) {
            int mid = (left + right) / 2;
            if (rep_units.get(mid) < val) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        lo = left - 1;

        // Binary search for upper_bound
        left = 0;
        right = rep_units.size();
        while (left < right) {
            int mid = (left + right) / 2;
            if (rep_units.get(mid) <= val) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        hi = left;

        if (lo < 0) lo = 0;
        if (hi >= rep_units.size()) hi = rep_units.size() - 1;

        if (lo == hi) {
            lo = Math.max(0, lo - 1);
        }

        long unit = rep_units.get(lo);
        int pos = lo;
        long diff1 = val - unit;
        long diff2 = (hi < rep_units.size()) ? rep_units.get(hi) - val : Long.MAX_VALUE;

        dfs(val % unit, depth + pos * (int)(val / unit));
        if (diff2 > 0 && diff2 < Long.MAX_VALUE) {
            dfs(diff2, depth + pos + 1);
        }
    }

    public static void main(String[] args) {
