#include <bits/stdc++.h>
using namespace std;

long long compute_repunit(int k) {
    long long res = 0;
    for (int i = 0; i < k; ++i) res = res * 10 + 1;
    return res;
}

long long solve(long long n) {
    vector<long long> A(17);
    for (int i = 1; i <= 16; ++i) A[i] = compute_repunit(i);

    vector<vector<long long>> dp(17, vector<long long>(2000000, LLONG_MAX));
    dp[0][0] = 0;

    for (int i = 1; i <= 16; ++i) {
        for (long long j = 0; j < 2000000; ++j) {
            if (dp[i-1][j] == LLONG_MAX) continue;
            long long diff = abs(j - n);
            long long m = diff / A[i];
            for (long long k = m; k <= m + 1; ++k) {
                long long new_val = j + (k * A[i]);
                if (new_val >= 2000000) continue;
                long long cost = dp[i-1][j] + k * i;
                dp[i][new_val] = min(dp[i][new_val], cost);
            }
