import java.util.*;

public class Main {
    static class Step {
        long val;
        int cost;

        Step(long val, int cost) {
            this.val = val;
            this.cost = cost;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Step step = (Step) o;
            return val == step.val && cost == step.cost;
        }

        @Override
        public int hashCode() {
            return Objects.hash(val, cost);
        }
    }

    static class StepComparator implements Comparator<Step> {
        @Override
        public int compare(Step a, Step b) {
            return Integer.compare(b.cost, a.cost);
        }
    }

    static Set<Long> visited = new HashSet<>();

    static boolean wasVisited(long c) {
        return visited.contains(c);
    }

    static Step uupper(long n) {
        long res = 0;
        int i = 0;
        while (res < n) {
            res = res * 10 + 1;
            i++;
        }
        return new Step(res, i);
    }

    static Step upper(long n) {
        long res = 0;
        int i = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            i++;
        }
        long resmul = res;
        int imul = i;
        while (res < n) {
            res += resmul;
            i += imul;
        }
        return new Step(res, i);
    }

    static Step lower(long n) {
        long res = 0;
        int i = 0;
        while (res * 10 + 1 <= n) {
            res = res * 10 + 1;
            i++;
        }
        long resmul = res;
        int imul = i;
        while (res + resmul <= n) {
            res += resmul;
            i += imul;
        }
        return new Step(res, i);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();

        PriorityQueue<Step> pq = new PriorityQueue<>(new StepComparator());
        pq.offer(new Step(n, 0));

        while (pq.peek().val != 0) {
            long val = pq.peek().val;
            int cost = pq.peek().cost;
            pq.poll();

            if (wasVisited(val)) {
                continue;
            }
            visited.add(val);

