#include<cstdio>
using namespace std;

#define ll long long

ll n,m,tmp[20];

ll Min(ll a,ll b) {if(a<b) return a;  return b;}

ll DFS(ll n,int x)
{
     if(n<0) n=-n;
     ll r=n/tmp[x]*x;
     n=n-n/tmp[x]*tmp[x];
     if(n==0) return r;
     return r+Min(DFS(n,x-1),x+DFS(tmp[x]-n,x-1));
}

int main()
{
    int i;
    tmp[1]=1;
    for(i=2;i<=18;i++) tmp[i]=tmp[i-1]*10+1;
    cin>>n;
    //for(i=1;i<=16;i++) cout<<tmp[i]<<endl;
    m=DFS(n,17);
    cout<<m;
    return 0;
}

