import java.util.Scanner;

public class Main {
    static long[] tmp = new long[20];

    static long Min(long a, long b) {
        return (a < b) ? a : b;
    }

    static long DFS(long n, int x) {
        if (n < 0) n = -n;
        long r = (n / tmp[x]) * tmp[x];
        n = n - (n / tmp[x]) * tmp[x];
        if (n == 0) return r;
        return r + Min(DFS(n, x - 1), tmp[x] + DFS(tmp[x] - n, x - 1));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int i;
        tmp[1] = 1;
        for (i = 2; i <= 18; i++) {
            tmp[i] = tmp[i - 1] * 10 + 1;
        }
        long n = scanner.nextLong();
        long m = DFS(n, 17);
        System.out.println(m);
    }
}

