import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        scanner.close();

        // Initialize memoization table with -1
        int[][] memo = new int[1000000][17];
        for (int i = 0; i < 1000000; i++) {
            Arrays.fill(memo[i], -1);
        }

        System.out.println(minOps(n, 16, memo));
    }

    private static long repunit(int k) {
        long res = 0;
        for (int i = 0; i < k; i++) {
            res = res * 10 + 1;
        }
        return res;
    }

    private static int minOps(long x, int k, int[][] memo) {
        if (k == 0) {
            return 0;
        }
        if (x == 0) {
            return 0;
        }
        if (memo[(int)x][k] != -1) {
            return memo[(int)x][k];
        }

        long block = repunit(k);
        long cnt = x / block;
        int base = (int)(cnt * k);
        x %= block;

        if (x == 0) {
            memo[(int)x][k] = base;
            return base;
        }

        int opt1 = minOps(block - x, k - 1, memo) + k;
        int opt2 = minOps(x, k - 1, memo);
        int result = base + Math.min(opt1, opt2);

        memo[(int)x][k] = result;
        return result;
    }
}

