import java.util.*;

public class Main {
    private static List<List<Integer>> memo = new ArrayList<>();

    private static int solve(long n, int k) {
        // Initialize memoization table if not already done
        while (memo.size() <= n) {
            memo.add(new ArrayList<>(Collections.nCopies(17, -1)));
        }

        if (k == 0 || n == 0) return 0;
        if (memo.get((int)n).get(k) != -1) return memo.get((int)n).get(k);

        long block = 0;
        for (int i = 0; i < k; ++i) block = block * 10 + 1;

        long cnt = n / block;
        int base = (int)(cnt * k);
        n %= block;

        if (n == 0) {
            memo.get((int)n).set(k, base);
            return base;
        }

        int res = base + Math.min(solve(block - n, k - 1) + k,
                                 solve(n, k - 1));
        memo.get((int)n).set(k, res);
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(solve(n, 16));
        scanner.close();
    }
}

