import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long v = scanner.nextLong();

        long[] cand = new long[17];
        cand[0] = 1;
        for (int i = 1; i < 17; ++i) {
            cand[i] = cand[i-1] * 10 + 1;
        }

        // Memoization cache
        Map<Long, Long>[] memo = new HashMap[17];
        for (int i = 0; i < 17; ++i) {
            memo[i] = new HashMap<>();
        }

        long result = rec(16, v, cand, memo);
        System.out.println(result);
    }

    private static long rec(int idx, long val, long[] cand, Map<Long, Long>[] memo) {
        val = val < 0 ? -val : val;

        if (idx == 0) {
            return val;
        }

        // Check memoization cache
        if (memo[idx].containsKey(val)) {
            return memo[idx].get(val);
        }

        long q1 = val / cand[idx];
        long q2 = q1 + 1;
        long res1 = q1 * (idx + 1) + rec(idx - 1, val - q1 * cand[idx], cand, memo);
        long res2 = q2 * (idx + 1) + rec(idx - 1, val - q2 * cand[idx], cand, memo);
        long result = Math.min(res1, res2);

        memo[idx].put(val, result);
        return result;
    }
}

