        cand[0] = 1;
        for (int i = 1; i < 17; ++i) {
            cand[i] = cand[i-1] * 10 + 1;
        }

        long[][] memo = new long[17][(int)v + 1];
        for (int i = 0; i < 17; ++i) {
            Arrays.fill(memo[i], -1);
