    private static long rec(int idx, long val, long[] cand, long[][] memo) {
        val = val < 0 ? -val : val;
        if (idx == 0) {
            return val;
        }
        if (val <= memo[0].length - 1 && memo[idx][(int)val] != -1) {
            return memo[idx][(int)val];
