        long q2 = q1 + 1;
        long res1 = q1 * (idx + 1) + rec(idx - 1, val - q1 * cand[idx], cand, memo);
        long res2 = q2 * (idx + 1) + rec(idx - 1, val - q2 * cand[idx], cand, memo);
        long ans = Math.min(res1, res2);

        if (val <= memo[0].length - 1) {
            memo[idx][(int)val] = ans;
        }
        return ans;
    }
}

