import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long v = scanner.nextLong();

        long[] cand = new long[17];
        cand[0] = 1;
        for (int i = 1; i < 17; ++i) {
            cand[i] = cand[i - 1] * 10 + 1;
        }

        // Memoization table
        Map<Long, Long>[] memo = new HashMap[17];
        for (int i = 0; i < 17; ++i) {
            memo[i] = new HashMap<>();
        }

        // DP function with memoization
        class DP {
            long solve(int idx, long x) {
                x = Math.abs(x);
                if (idx == 0) return x;

                // Check memoization
                if (memo[idx].containsKey(x)) {
                    return memo[idx].get(x);
                }

                long q = x / cand[idx];
                long r = q + 1;

                long cost1 = q * (idx + 1) + solve(idx - 1, x - q * cand[idx]);
                long cost2 = r * (idx + 1) + solve(idx - 1, x - r * cand[idx]);

                long result = cost1 <= cost2 ? cost1 : cost2;
                memo[idx].put(x, result);
                return result;
            }
        }

        DP dp = new DP();
        System.out.println(dp.solve(16, v));
    }
}

