#include <cmath>
using namespace std;
using i64 = long long;

i64 numof(i64 x) {
    if (x == 0) return 1;
    i64 cnt = 0;
    if (x < 0) x = -x;
    while (x > 0) {
        cnt++;
        x /= 10;
    }
    return cnt;
}

i64 nxt(i64 x) {
    vector<int> digits;
    bool neg = x < 0;
    if (neg) x = -x;
    while (x > 0) {
        int d = x % 10;
        digits.push_back(d - (neg ? -1 : 1));
        x /= 10;
    }
    i64 res = 0;
    for (int i = digits.size() - 1; i >= 0; --i) {
        res = res * 10 + digits[i];
    }
    return neg ? -res : res;
}

i64 prv(i64 x) {
    bool neg = x < 0;
    if (neg) x = -x;
    i64 c = 0;
    i64 cx = x;
    while (x > 0) {
        c = c * 10 + (neg ? -1 : 1);
        x /= 10;
    }
    c = c * 10 + 1;
    return neg ? cx + c : cx - c;
}

i64 lst(i64 x) {
    if (x < 0) x = -x;
    while (x >= 10) {
        x /= 10;
    }
    return x;
}

i64 del(i64 x) {
    if (x < 0) x = -x;
    vector<int> digits;
    while (x >= 10) {
        digits.push_back(x % 10);
        x /= 10;
    }
    i64 res = 0;
    for (int i = digits.size() - 1; i >= 0; --i) {
        res = res * 10 + digits[i];
    }
    return res;
}

unordered_map<i64, i64> memo;

i64 f(i64 x) {
    if (x <= 11) return min(13 - x, x);
    if (memo.count(x)) return memo[x];
    i64 n = 0, t = 1;
    while (t < x) {
        t *= 10;
        t++;
        n++;
    }
    if (x * 2 >= t) {
        return memo[x] = min(f(t - x) + n + 1, (x / (t / 10)) * n + f(x % (t / 10)));
    }
    return memo[x] = (x / (t / 10)) * n + f(x % (t / 10));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    i64 a;
    cin >> a;
    cout << f(a) << '\n';
    return 0;
