        }
        return res;
    }

    public static long solve(long x, int depth, long[] repunits) {
        long count = x / repunits[depth];
        x %= repunits[depth];
        if (x == 0) {
            return count * depth;
        }
        long option1 = solve(x, depth - 1, repunits);
        long option2 = depth + solve(repunits[depth] - x, depth - 1, repunits);
        return count * depth + Math.min(option1, option2);
    }

