import java.util.*;

public class Main {
    // tim so chu so cua n
    static int num(long n) {
        int num = 0;
        while (n != 0) {
            n /= 10;
            num++;
        }
        return num;
    }

    // tinh so co dang 11...1 lon nhat nhung khong vuot qua n
    static long find(long n) {
        int ex = num(n);
        long cur = 0, ad = 1;
        for (int i = 0; i <= ex - 1; i++) {
            cur += ad;
            ad *= 10;
        }
        if (cur <= n) return cur;
        return ((cur - 1) / 10);
    }

    static long process(long n) {
        if (n <= 6) return n;
        if (n <= 11) return (13 - n);
        long less = find(n);
        long more = less * 10 + 1;
        if (n % less == 0) {
            if (n <= more / 2 + less) return num(less) * n / less;
            return num(more) + process(more - n);
        } else {
            long _m = (n / less) * less;
            long res = process(_m) + process(n - _m);
            if (n > more / 2) res = Math.min(process(_m) + process(n - _m), num(more) + process(more - n));
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(process(n));
        scanner.close();
    }
}

