import java.util.Scanner;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();

        // Process "at" replacements
        String temp = input;

        // First replace "at" with "@" when it's not preceded by '.' or '@' and not followed by '.'
        // Using regex to match "at" that is either at end of string or not followed by '.'
        Pattern atPattern = Pattern.compile("at(?=[^.]|$)");
        Matcher atMatcher = atPattern.matcher(temp);
        temp = atMatcher.replaceAll("@");

        // Process remaining "at" occurrences
        while (temp.contains("at")) {
            int pos = temp.indexOf("at");
            if (pos > 0 && temp.charAt(pos-1) != '.' && temp.charAt(pos-1) != '@' && pos + 2 < temp.length()) {
                temp = temp.substring(0, pos-1) + "@" + temp.substring(pos+2);
            } else {
                break;
            }
        }

        // Replace "dot" with "."
        temp = temp.replace("dot", ".");

        System.out.println(temp);
    }
}

