            output += '.';
            i += 3;
            continue;
        }

        if (!atReplaced && i > 0 && i + 1 < input.length() - 1 && 
            input[i] == 'a' && isAtSequence(input, i)) {
            output += '@';
            i += 2;
            atReplaced = true;
            continue;
        }

        output += input[i];
        i++;
    }

    cout << output;
    return 0;
