                break;
            }
        }

        // Second replacement: "dot" -> "." (skip first character)
        for (int i = 1; i + 3 <= input.length(); ++i) {
            while (i + 3 <= input.length() && 
                   input.charAt(i) == 'd' && 
                   input.charAt(i+1) == 'o' && 
                   input.charAt(i+2) == 't') {
                if (i + 3 < input.length()) {
                    input = input.substring(0, i) + "." + input.substring(i + 3);
                } else {
                    break;
                }
                i += 1; // adjust position after replacement
            }
        }

        System.out.print(input);
    }
}

