import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    public static boolean isPrime(long n) {
        if (n <= 1) return true;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;

        for (long i = 5; i * i <= n; i = i + 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    public static long pow(long a, long b, long m) {
        long res = 1;
        while (b > 0) {
            if ((b & 1) == 1) res = (res * a) % m;
            a = (a * a) % m;
            b >>= 1;
        }
        return res;
    }

    public static long ncr(int n, int k) {
        if (k > n) return 0;
        long res = 1;
        if (k > n - k) {
            k = n - k;
        }
        for (int i = 0; i < k; ++i) {
            res *= (n - i);
            res /= (i + 1);
        }
        return res;
    }

    public static void solve() {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        boolean at = false;
        int n = s.length();
        System.out.print(s.charAt(0));
        int[] done = new int[n + 1];
        done[0] = 1;

        for (int i = 1; i <= n - 3; i++) {
            done[i] = 1;
            if (s.charAt(i) == 'a' && s.charAt(i + 1) == 't' && !at) {
                System.out.print('@');
                at = true;
                done[i + 1] = 1;
                i++;
            } else if (s.charAt(i) == 'd' && s.charAt(i + 1) == 'o' && s.charAt(i + 2) == 't' && (i != n - 3)) {
                System.out.print('.');
                done[i + 1] = 1;
                done[i + 2] = 1;
                i += 2;
            } else {
                System.out.print(s.charAt(i));
            }
        }

        for (int i = 0; i < n; i++) {
            if (done[i] == 0) {
                System.out.print(s.charAt(i));
            }
        }
    }

    public static void main(String[] args) {
        solve();
    }
}

