public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.next();
        scanner.close();

        int l = s.length();
        int i = 0;

        System.out.print(s.charAt(0));

        boolean f = false;

        for (i = 1; i < l;) {
            if (s.charAt(i) == 'a' && !f && at(s, i, l)) {
                System.out.print('@');
                f = true;
                i += 2;
                continue;
