        return (i + 2) < (l - 1) && s.charAt(i + 1) == 'o' && s.charAt(i + 2) == 't';
    }

    private static boolean at(String s, int i, int l) {
        return (i + 1) < l && s.charAt(i + 1) == 't';
    }
}

