            // Check for "@@@" pattern (actually 'a' followed by 't')
            if (i > 0 && i + 1 < n && !replaced_at && s.charAt(i) == 'a' && s.charAt(i+1) == 't') {
                result.append('@');
                replaced_at = true;
                i += 2; // consume both 'a' and 't'
            }
            // Check for ".dot" pattern (actually 'd', 'o', 't')
            else if (i > 0 && i + 2 < n && s.charAt(i) == 'd' && s.charAt(i+1) == 'o' && s.charAt(i+2) == 't') {
                result.append('.');
                i += 3; // consume 'd', 'o', 't'
            }
            else {
                result.append(s.charAt(i));
                i += 1;
            }
        }

        System.out.println(result.toString());
    }
}

