        for (int i = 1; i < len - 3; i++) {
            if (buf[i] == 'd' && buf[i+1] == 'o' && buf[i+2] == 't') {
                buf[i] = '.';
                buf[i+1] = '\0';
                buf[i+2] = '\0';
                // Shift the remaining characters left by 2 positions
                for (int j = i + 3; j < len; j++) {
                    buf[j - 2] = buf[j];
