                    }
                    if (Integer.bitCount(xd) > Integer.bitCount(ms)) {
                        bad = true;
                        break;
                    }
                }

                if (!bad) mas[mask] |= (1 << ind);
                ++ind;
            }
        }

        for (int i = 0; i < (1 << 18); ++i) {
            p0[mas[i]] = (p0[mas[i]] + sub0[i]) % MOD;
        }

        for (int i = 0; i < (1 << 18); ++i) {
            int cm_val = 0;
            for (int j = 0; j < 20; ++j) {
                if ((mas[i] & (1 << j)) != 0) {
                    cm_val |= (1 << comp[j]);
                }
            }
            p1[cm_val] = (p1[cm_val] + sub1[i]) % MOD;
        }

        for (int i = 0; i < 20; ++i) {
            for (int mask = 0; mask < (1 << 20); ++mask) {
                if ((mask & (1 << i)) != 0) {
                    p1[mask] = (p1[mask] + p1[mask ^ (1 << i)]) % MOD;
                }
            }
        }

        long ans = 0;
        for (int i = 0; i < (1 << 20); ++i) {
            ans = (ans + p0[i] * p1[i ^ ((1 << 20) - 1)]) % MOD;
        }

        ans = (1 - ans + MOD) % MOD;
        System.out.println(ans);
    }
}

