        return r *= o;
    }

    inline Field<N> operator/(const Field<N>& o) const {
        Field<N> r(*this);
        return r /= o;
    }

    inline Field<N> operator-() {
        if (v) return { (int)(N - v) };
        else return { 0 };
    }

    inline Field<N>& operator++() {
        ++v;
        if (v == N) v = 0;
        return *this;
    }

    inline Field<N> operator++(int) {
        Field<N> r(*this);
        ++*this;
        return r;
    }

    inline Field<N>& operator--() {
        --v;
        if (v == (unsigned int)(-1)) v = N - 1;
        return *this;
    }

