        }
        return result;
    }

    static int inv_mod(int a) {
        return pow_mod(a, MOD - 2);
    }

    static int div_mod(int a, int b) {
        return mul_mod(a, inv_mod(b));
    }

    static class State {
        List<Byte> masks;
        int value;

        State(List<Byte> masks, int value) {
            this.masks = masks;
            this.value = value;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());

        int[][] a = new int[n][n];
        for (int i = 0; i < n; ++i) {
            String[] line = br.readLine().split(" ");
            for (int j = 0; j < n; ++j) {
                a[i][j] = Integer.parseInt(line[j]);
                a[i][j] = div_mod(a[i][j], 100);
            }
        }

        List<State> current = new ArrayList<>();
        List<Byte> initialMasks = new ArrayList<>();
        initialMasks.add((byte)0);
        current.add(new State(initialMasks, 1));

        for (int g = 0; g < n; ++g) {
            List<State> next = new ArrayList<>();

            for (int mask = 0; mask < (1 << n); ++mask) {
                int prob = 1;
                for (int j = 0; j < n; ++j) {
                    if ((mask & (1 << j)) != 0) {
                        prob = mul_mod(prob, a[j][g]);
                    } else {
                        prob = mul_mod(prob, sub_mod(1, a[j][g]));
                    }
                }

                for (State state : current) {
                    List<Byte> new_masks = new ArrayList<>();
                    for (byte mask2 : state.masks) {
                        int remaining = ~mask2 & mask;
                        while (remaining != 0) {
                            int pos = remaining & -remaining;
                            new_masks.add((byte)(mask2 | pos));
                            remaining ^= pos;
                        }
                    }

                    if (new_masks.isEmpty()) continue;
                    Collections.sort(new_masks);
                    new_masks = new ArrayList<>(new LinkedHashSet<>(new_masks));

                    next.add(new State(new_masks, mul_mod(state.value, prob)));
                }
            }

            Collections.sort(next, (s1, s2) -> {
                int minSize = Math.min(s1.masks.size(), s2.masks.size());
                for (int i = 0; i < minSize; i++) {
                    int cmp = Byte.compare(s1.masks.get(i), s2.masks.get(i));
                    if (cmp != 0) return cmp;
                }
                return Integer.compare(s1.masks.size(), s2.masks.size());
            });

            current.clear();
            for (int i = 0; i < next.size(); ) {
                int j = i;
                int total = 0;
                while (j < next.size() && compareMasks(next.get(j).masks, next.get(i).masks) == 0) {
                    total = add_mod(total, next.get(j).value);
                    ++j;
                }
                current.add(new State(next.get(i).masks, total));
                i = j;
            }
        }

        int result = 0;
        for (State state : current) {
            result = add_mod(result, state.value);
        }

        System.out.println(result);
    }

    static int compareMasks(List<Byte> masks1, List<Byte> masks2) {
        if (masks1.size() != masks2.size()) {
            return Integer.compare(masks1.size(), masks2.size());
        }
        for (int i = 0; i < masks1.size(); i++) {
            int cmp = Byte.compare(masks1.get(i), masks2.get(i));
            if (cmp != 0) return cmp;
        }
        return 0;
    }
}

