                            int bit = rem & -rem;
                            curMasks.add((byte) ((base & 0xFF) | bit));
                            rem ^= bit;
                        }
                    }

                    if (curMasks.isEmpty()) continue;

                    Collections.sort(curMasks);
                    List<Byte> uniqueMasks = new ArrayList<>();
                    Byte last = null;
                    for (Byte b : curMasks) {
                        if (last == null || last != b) {
                            uniqueMasks.add(b);
                            last = b;
                        }
                    }

                    byte[] uniqueArray = new byte[uniqueMasks.size()];
                    for (int i = 0; i < uniqueMasks.size(); i++) {
                        uniqueArray[i] = uniqueMasks.get(i);
                    }

                    nxt.add(new State(uniqueArray, mul(coef, prob)));
                }
            }

            Collections.sort(nxt, (a, b) -> {
                if (a.masks.length != b.masks.length) {
                    return Integer.compare(a.masks.length, b.masks.length);
                }
                for (int i = 0; i < Math.min(a.masks.length, b.masks.length); i++) {
                    int cmp = Byte.compare(a.masks[i] & 0xFF, b.masks[i] & 0xFF);
                    if (cmp != 0) return cmp;
                }
                return 0;
            });

            cur.clear();
            for (int i = 0; i < nxt.size(); ) {
                int j = i;
                int cum = 0;
                byte[] key = nxt.get(i). masks;
                while (j < nxt.size() && Arrays.equals(nxt.get(j).masks, key)) {
                    cum = add(cum, nxt.get(j).coef);
                    j++;
                }
                cur.add(new State(key, cum));
                i = j;
            }
        }

        int ans = 0;
        for (State state : cur) {
            ans = add(ans, state.coef);
        }
        System.out.println(ans);
    }

    static class State {
        byte[] masks;
        int coef;

        State(byte[] masks, int coef) {
            this.masks = masks;
            this.coef = coef;
        }
    }
}

