struct Mod {
    int v;
    Mod() : v(0) {}
    Mod(int _v) : v(norm(_v)) {}
    explicit operator int() const { return v; }

    static int norm(int x) {
        if (x < 0) x += MOD;
        if (x >= MOD) x -= MOD;
        return x;
    }

    Mod& operator+=(const Mod& o) { v = norm(v + o.v); return *this; }
    Mod& operator-=(const Mod& o) { v = norm(v - o.v); return *this; }
    Mod& operator*=(const Mod& o) { v = (int)(1LL * v * o.v % MOD); return *this; }
    Mod& operator/=(const Mod& o) { return *this *= o.inv(); }

    Mod operator-() const { return Mod(-v); }

    Mod inv() const {
        int a = v, b = MOD, x = 0, y = 1;
        while (a > 1) {
            int q = a / b;
            int t = b; b = a % b; a = q;
            t = x; x = y - q * x; y = t;
        }
        if (y < 0) y += MOD;
        return Mod(y);
    }

    friend Mod pow(Mod a, i64 e) {
        Mod res = 1;
        while (e > 0) {
            if (e & 1) res *= a;
