            for (int j = 0; j < (1 << n); ++j) {
                if ((j & (1 << i)) == 0) {
                    no[i] |= (1L << j);
                }
            }
        }

        Map<Long, Mod> dp = new HashMap<>();
        dp.put(1L, new Mod(1));

        for (int round = 0; round < n; ++round) {
            Map<Long, Mod> ndp = new HashMap<>();
            for (Map.Entry<Long, Mod> entry : dp.entrySet()) {
                long mask = entry.getKey();
                Mod prob = entry.getValue();

                for (int outcome = 0; outcome < (1 << n); ++outcome) {
                    long nextMask = 0;
                    Mod curProb = new Mod(1);

                    for (int k = 0; k < n; ++k) {
                        if ((outcome & (1 << k)) != 0) {
                            curProb.multiply(p[round][k]);
                            nextMask |= (mask & no[k]) << (1L << k);
                        } else {
                            Mod complement = new Mod(1).subtract(p[round][k]);
                            curProb.multiply(complement);
                        }
                    }

                    ndp.put(nextMask, ndp.getOrDefault(nextMask, new Mod(0)).add(prob.multiply(curProb)));
                }
            }
            dp = ndp;
        }

        System.out.println(dp.get(1L << ((1 << n) - 1)).intValue());
    }
}

