    map<int, int> permMap;
    int id = 0;
    do {
        int mask = 0;
        for (int k = 0; k < 6; ++k) {
            if (v[k]) mask |= (1 << k);
        }
        permMap[mask] = id++;
    } while (next_permutation(v.begin(), v.end()));

    // Solve function
    auto solve = [&](int offset) -> vector<Mod> {
        vector<Mod> res(1 << 20, Mod(0));
        for (int m = 0; m < (1 << 18); ++m) {
            vector<vector<int>> h(3, vector<int>(6, 0));
            Mod p(1);
            for (int i = 0; i < 3; ++i) {
                for (int j = 0; j < 6; ++j) {
                    int idx = i * 6 + j;
                    if (m & (1 << idx)) {
                        h[i][j] = 1;
                        p *= pers[offset + i][j];
                    } else {
                        p *= (Mod(1) - pers[offset + i][j]);
                    }
                }
            }
            int f = 0;
            for (int i = 0; i < 6; ++i) {
                if (!h[0][i]) continue;
                for (int j = 0; j < 6; ++j) {
                    if (!h[1][j]) continue;
                    if (i == j) continue;
                    for (int k = 0; k < 6; ++k) {
                        if (!h[2][k]) continue;
                        if (i == k || j == k) continue;
                        int anum = (1 << i) ^ (1 << j) ^ (1 << k);
                        f |= (1 << permMap[anum]);
                    }
                }
            }
            res[f] += p;
        }
        return res;
    };

    auto up = solve(0);
    auto dn = solve(3);

    // FWT-style summation
    for (int b = 1; b < (1 << 20); b <<= 1) {
        for (int i = 0; i < (1 << 20); ++i) {
            if (!(i & b)) dn[i ^ b] += dn[i];
