                            elo[j][s[1] + (f ? 3 : 0)] == 1 &&
                            elo[k][s[2] + (f ? 3 : 0)] == 1) {
                            int base = f ? 126 : 0;
                            mask |= maska[base ^ ((1 << i) + (1 << j) + (1 << k))];
                        }
                    }
                }
            }
        }
