    static class ModInt {
        private static final long MD = 1000000007L; // 10^9 + 7
        private long v;

        public ModInt(long val) {
            val = val % MD + MD;
            v = (val < MD) ? val : val - MD;
        }

        public ModInt() {
            v = 0;
        }

        public ModInt setV(long val) {
