        ModInt[][] mat = new ModInt[n][n];

        for (int i = 0; i < n; i++) {
            String[] line = br.readLine().split(" ");
            for (int j = 0; j < n; j++) {
                int x = Integer.parseInt(line[j]);
                mat[i][j] = new ModInt(x).div(new ModInt(100));
            }
        }

        class State {
            List<Integer> maskList;
            ModInt prob;

            State(List<Integer> maskList, ModInt prob) {
                this.maskList = maskList;
                this.prob = prob;
            }
        }

        List<State> sts = new ArrayList<>();
        List<Integer> initMask = new ArrayList<>();
        initMask.add(0);
