                for (int i = 0; i < Math.min(a.maskList.size(), b.maskList.size()); i++) {
                    if (a.maskList.get(i) != b.maskList.get(i)) {
                        return a.maskList.get(i) - b.maskList.get(i);
                    }
                }
                return a.maskList.size() - b.maskList.size();
            });

            sts.clear();
            for (State st : nsts) {
                if (!sts.isEmpty() && sts.get(sts.size() - 1).maskList.equals(st.maskList)) {
                    sts.get(sts.size() - 1).prob = sts.get(sts.size() - 1).prob.add(st.prob);
                } else {
                    sts.add(st);
                }
            }
        }

        ModInt ans = new ModInt(0);
        if (!sts.isEmpty()) {
            ans = sts.get(0).prob;
        }

        pw.println(ans);
        pw.close();
    }
}

