                sts.back().second += st.second;
            } else {
                sts.emplace_back(st);
            }
        }
        dbg(ph, nsts.size());
    }

    Mint ans = Mint(0);
    if (!sts.empty()) {
        ans = sts[0].second;
    }

    cout << ans << '\n';

    return 0;
}

