import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static int[][] P = new int[6][6];
    static List<Integer> masks = new ArrayList<>();
    static List<Integer> masks2 = new ArrayList<>();
    static int[] prob = new int[1 << 20];
    static int[] prob2 = new int[1 << 20];

    static int modPow(int base, int exp) {
        int result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (int) (((long) result * base) % MOD);
            }
            exp >>= 1;
            base = (int) (((long) base * base) % MOD);
        }
        return result;
    }

    static int modInverse(int n) {
        return modPow(n, MOD - 2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        for (int i = 0; i < n; i++) {
            String[] line = br.readLine().split("\\s+");
            for (int j = 0; j < n; j++) {
                P[i][j] = Integer.parseInt(line[j]);
            }
        }

        int h = (n + 1) / 2;
        int h2 = n - h;
        int inv100 = modInverse(100);

        for (int mask = 0; mask < (1 << n); mask++) {
            int count = Integer.bitCount(mask);
            if (count == h) masks.add(mask);
            if (count == h2) masks2.add(mask);
        }

        for (int mask = 0; mask < (1 << (n * h)); mask++) {
            long p = 1;
            for (int bit = 0; bit < n * h; bit++) {
                int row = bit / n;
                int col = bit % n;
                if ((mask & (1 << bit)) != 0) {
                    p = (p * P[row][col] % MOD) * inv100 % MOD;
                } else {
                    p = (p * (100 - P[row][col]) % MOD) * inv100 % MOD;
                }
            }
            int successMask = 0;
            for (int m = 0; m < masks.size(); m++) {
                List<Integer> selected = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    if ((masks.get(m) & (1 << k)) != 0) {
                        selected.add(k);
                    }
                }
                Collections.sort(selected);
                do {
                    boolean valid = true;
                    for (int idx = 0; idx < selected.size(); idx++) {
                        int bitPos = idx * n + selected.get(idx);
                        if ((mask & (1 << bitPos)) == 0) {
                            valid = false;
                            break;
                        }
                    }
                    if (valid) {
                        successMask |= (1 << m);
                        break;
                    }
                } while (nextPermutation(selected));
                prob[successMask] = (int) ((prob[successMask] + p) % MOD);
            }
        }

        for (int mask = 0; mask < (1 << (n * h2)); mask++) {
            long p = 1;
            for (int bit = 0; bit < n * h2; bit++) {
                int row = bit / n + h;
                int col = bit % n;
                if ((mask & (1 << bit)) != 0) {
                    p = (p * P[row][col] % MOD) * inv100 % MOD;
                } else {
                    p = (p * (100 - P[row][col]) % MOD) * inv100 % MOD;
                }
            }
            int successMask = 0;
            for (int m = 0; m < masks.size(); m++) {
                List<Integer> selected = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    if ((masks.get(m) & (1 << k)) == 0) {
                        selected.add(k);
                    }
                }
                Collections.sort(selected);
                do {
                    boolean valid = true;
                    for (int idx = 0; idx < selected.size(); idx++) {
                        int bitPos = idx * n + selected.get(idx);
                        if ((mask & (1 << bitPos)) == 0) {
                            valid = false;
                            break;
                        }
                    }
                    if (valid) {
                        successMask |= (1 << m);
                        break;
                    }
                } while (nextPermutation(selected));
                prob2[successMask] = (int) ((prob2[successMask] + p) % MOD);
            }
        }

        int numMasks = masks.size();
        for (int i = 0; i < (1 << numMasks); i++) {
            for (int j = 0; j < numMasks; j++) {
                if ((i & (1 << j)) != 0) {
                    prob2[i] = (int) ((prob2[i] + prob2[i ^ (1 << j)]) % MOD);
                }
            }
        }

        long answer = 0;
        for (int i = 0; i < (1 << numMasks); i++) {
            answer = (answer + (long) prob[i] * prob2[((1 << numMasks) - 1) ^ i]) % MOD;
        }

        System.out.println((MOD + 1 - answer) % MOD);
    }

    static boolean nextPermutation(List<Integer> list) {
        int i = list.size() - 2;
        while (i >= 0 && list.get(i) >= list.get(i + 1)) {
            i--;
        }
        if (i < 0) {
            return false;
        }
        int j = list.size() - 1;
        while (list.get(j) <= list.get(i)) {
            j--;
        }
        Collections.swap(list, i, j);
        Collections.reverse(list.subList(i + 1, list.size()));
        return true;
    }
}

