            while (r != 0) {
                int q = g / r;
                g %= r;
                int temp = g;
                g = r;
                r = temp;
                x -= q * y;
                temp = x;
                x = y;
                y = temp;
            }
            return x < 0 ? x + m : x;
        }

        ModInt(int v) {
            val = v;
        }

        ModInt() {
            val = 0;
        }

        ModInt add(ModInt other) {
            val += other.val;
            if (val >= MOD) val -= MOD;
            return this;
        }

        ModInt subtract(ModInt other) {
            val -= other.val;
            if (val < 0) val += MOD;
            return this;
        }

        ModInt multiply(ModInt other) {
            val = (int) ((long) val * other.val % MOD);
            return this;
        }

        ModInt divide(ModInt other) {
            return multiply(other.inverse());
        }

