        v %= MOD;
        if (v < 0) v += MOD;
        val = static_cast<int>(v);
    }

    static int mod_inverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return val; }

    Mod& operator+=(const Mod& other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    Mod& operator-=(const Mod& other) {
