import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 1000000007;
    static int n;
    static int[][] a;
    static int[][] f;
    static Map<Long, Integer>[] st;
    static long mx;
    static long stt;

    static long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static class BitMask {
        long a;
        long b;

        void set(int x) {
            if (x < 64) {
                a |= (1L << x);
            } else {
                b |= (1L << (x - 64));
            }
        }

        void reset() {
            a = 0;
            b = 0;
        }

        void orWith(BitMask ano) {
            this.a |= ano.a;
            this.b |= ano.b;
        }

        boolean equals(BitMask ano) {
            return b == ano.b && a == ano.a;
        }

        boolean get(int x) {
            return (x < 64) ? ((a & (1L << x)) != 0) : ((b & (1L << (x - 64))) != 0);
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            BitMask bitMask = (BitMask) obj;
            return b == bitMask.b && a == bitMask.a;
        }

        @Override
        public int hashCode() {
            return Objects.hash(a, b);
        }
    }

    static int dfs(int x, BitMask w) {
        if (x == n) {
            return w.equals(mx) ? 1 : 0;
        }

        if (st[x].containsKey(w.a * (1L << 64) + w.b)) {
            return st[x].get(w.a * (1L << 64) + w.b);
        }

