        long t = 1L * a * b;
        if (t >= mod) t %= mod;
        return (int) t;
    }

    static int dec(int a, int b) {
        if ((a -= b) < 0) a += mod;
        return a;
    }

    static int power(int a, int b) {
        int out = 1;
        while (b > 0) {
            if ((b & 1) == 1) out = mult(out, a);
            a = mult(a, a);
            b >>= 1;
        }
        return out;
    }

