import java.util.*;

public class Main {
    static final int MOD = 1000000007;

    static int mod_inc(int x, int y) {
        x += y;
        return x >= MOD ? x - MOD : x;
    }

    static int mod_dec(int x, int y) {
        x -= y;
        return x < 0 ? x + MOD : x;
    }

    static int mod_mul(int x, int y) {
        return (int) (((long) x * y) % MOD);
    }

    static int mod_exp(int base, int exp) {
        int res = 1;
        while (exp != 0) {
            if ((exp & 1) == 1) res = mod_mul(res, base);
            base = mod_mul(base, base);
            exp >>= 1;
        }
        return res;
    }

    static int get_lb(int x) {
        return x & -x;
    }

    static int N;
    static int[][] adj = new int[10][10];
    static int[][] trie = new int[70010][128];
    static int node_cnt = 0;
    static int[][] prob_table = new int[10][128];
    static int[][] dp = new int[10][70010];
    static HashMap<BitSet, Integer> state_to_node = new HashMap<>();

    static int traverse(BitSet st) {
        Integer node = state_to_node.get(st);
        if (node != null) return node;
        node = ++node_cnt;
        state_to_node.put(st, node);
        for (int a = 0; a < (1 << N); ++a) {
            BitSet nxt_st = (BitSet) st.clone();
            for (int idx = 0; idx < (1 << N); ++idx) {
                if (!nxt_st.get(idx)) {
                    int ol = a & idx;
                    boolean ok = false;
                    while (ol != 0) {
                        int b = get_lb(ol);
                        if (st.get(idx ^ b)) {
                            nxt_st.set(idx);
                            ok = true;
                            break;
                        }
                        ol -= b;
                    }
                    if (!ok) nxt_st.clear(idx);
                }
            }
            trie[node][a] = traverse(nxt_st);
        }
        return node;
    }

    public static void main(String[] args) {
        Scanner cin = new Scanner(System.in);
        N = cin.nextInt();
        traverse(new BitSet());

        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                adj[i][j] = cin.nextInt();
                adj[i][j] = mod_mul(adj[i][j], mod_exp(100, MOD - 2));
            }
        }

        for (int i = 0; i < N; ++i) {
            for (int mask = 0; mask < (1 << N); ++mask) {
                prob_table[i][mask] = 1;
                for (int k = 0; k < N; ++k) {
                    if (((mask >> k) & 1) == 1)
                        prob_table[i][mask] = mod_mul(prob_table[i][mask], adj[i][k]);
                    else
                        prob_table[i][mask] = mod_mul(prob_table[i][mask], mod_dec(1, adj[i][k]));
                }
            }
        }

        dp[0][1] = 1;
        for (int step = 1; step <= N; ++step) {
            for (int node = 1; node <= node_cnt; ++node) {
                for (int act = 0; act < (1 << N); ++act) {
                    int next_node = trie[node][act];
                    dp[step][next_node] = mod_inc(dp[step][next_node], mod_mul(dp[step - 1][node], prob_table[step - 1][act]));
                }
            }
        }

        BitSet full = new BitSet(128);
        for (int i = 0; i < 128; ++i) full.set(i);
