                    nmsk |= nxt[s][S.get(i).get(j)];
                }
            }
            ret = (ret + p * solve(i + 1, nmsk)) % MOD;
        }
        int result = (int) (ret % MOD);
        dp[i].put(msk, result);
        return result;
    }

