	for (int i=1;i<=n;i++)
		for (int j=1;j<=n;j++)
			scanf("%d",&p[i][j]),p[i][j]=(LL)p[i][j]*inv%MOD;
	while (n<6) n++,p[n][n]=1;
}

bool get_match(int x)
