typedef long long ll;
const int MOD = 1000000007;

int mod_exp(int base, int exp, int mod) {
    int res = 1;
    base %= mod;
    while (exp) {
        if (exp & 1) res = (ll)res * base % mod;
        base = (ll)base * base % mod;
        exp >>= 1;
    }
    return res;
}

void add_mod(int& a, int b) {
    a = (a + b) % MOD;
    if (a < 0) a += MOD;
}

int n;
vector<vector<int>> p;
vector<vector<int>> prod;
vector<vector<int>> groups;
vector<int> idx;
vector<vector<ll>> q;
map<pair<int, ll>, int> dp;

int dfs(int cur, ll state) {
    if (state == 0) return 0;
    if (cur == n) return 1;

    auto key = make_pair(cur, state);
    if (dp.count(key)) return dp[key];

    int result = 0;
    for (int mask = 1; mask < (1 << n); ++mask) {
        ll next_state = 0;
        for (int k = 0; k < groups.size(); ++k) {
            if (!(state & (1LL << k))) continue;
            int cur_elem = groups[k];
            int rem = mask & ~cur_elem;
            next_state |= q[cur_elem][rem];
        }
        add_mod(result, (ll)prod[cur][mask] * dfs(cur + 1, next_state) % MOD);
    }

    return dp[key] = result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> n;
    int inv100 = mod_exp(100, MOD - 2, MOD);

