    for (int i = 0; i < n; ++i) {
        for (int mask = 0; mask < (1 << n); ++mask) {
            for (int j = 0; j < n; ++j) {
                if (mask & (1 << j)) {
                    prod[i][mask] = (ll)prod[i][mask] * p[i][j] % MOD;
                } else {
                    prod[i][mask] = (ll)prod[i][mask] * ((MOD + 1 - p[i][j]) % MOD) % MOD;
                }
            }
        }
    }

    groups.clear();
    for (int i = 0; i < n; ++i) groups.push_back(1 << i);

    idx.resize(1 << n);
    vector<vector<int>> cnt_groups(n + 1);
    for (int mask = 0; mask < (1 << n); ++mask) {
        int cnt = __builtin_popcount(mask);
        cnt_groups[cnt].push_back(mask);
        idx[mask] = cnt_groups[cnt].size() - 1;
    }

    q.assign(1 << n, vector<ll>(1 << n, 0));
    for (int mask = 0; mask < (1 << n); ++mask) {
        for (int j = 0; j < n; ++j) {
            if (!(mask & (1 << j))) {
                int next_mask = mask | (1 << j);
                int group_id = __builtin_popcount(mask);
                int pos = idx[next_mask];
                q[mask][1 << j] = 1LL << pos;
            }
        }
        for (int j = 1; j < (1 << n); ++j) {
            int lb = j & -j;
