public class Main {
    static final int MOD = 1000000007;

    static class ModInt {
        int val;

        ModInt(long v) {
            if (v < 0) v = (v % MOD + MOD) % MOD;
            if (v >= MOD) v %= MOD;
            val = (int) v;
        }

        static int modInv(int a, int m) {
            int g = m, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                g %= r;
                int temp = g;
                g = r;
                r = temp;
                x -= q * y;
                temp = x;
                x = y;
                y = temp;
            }
            return (x < 0 ? x + m : x);
        }

        ModInt(int v) {
            val = v;
        }

        ModInt() {
            val = 0;
        }

        ModInt add(ModInt other) {
            val = (val + other.val) % MOD;
            if (val < 0) val += MOD;
            return this;
        }

        ModInt subtract(ModInt other) {
            val = (val - other.val + MOD) % MOD;
            return this;
        }

        ModInt multiply(ModInt other) {
            val = (int) ((long) val * other.val % MOD);
            return this;
        }

        ModInt divide(ModInt other) {
            return multiply(other.inverse());
        }

        ModInt increment() {
            val = (val == MOD - 1) ? 0 : val + 1;
            return this;
        }

        ModInt decrement() {
            val = (val == 0) ? MOD - 1 : val - 1;
            return this;
        }

        ModInt negate() {
            return val == 0 ? new ModInt(0) : new ModInt(MOD - val);
        }

        ModInt inverse() {
            return new ModInt(modInv(val, MOD));
        }

        ModInt pow(long p) {
            assert p >= 0;
