            ModInt result = new ModInt(1);
            while (p > 0) {
                if ((p & 1) == 1) result.multiply(a);
                a.multiply(a);
                p >>= 1;
            }
            return result;
        }

        boolean equals(ModInt other) {
            return val == other.val;
        }

        @Override
        public String toString() {
            return String.valueOf(val);
        }
    }

    static final int N_MAX = 10;
