                }
            }
            int complement = ((1 << 20) - 1) ^ m[mask];
            long term = ((1 - F[complement] + MOD) % MOD);
            ans = (ans + v * term) % MOD;
        }

        pw.println(ans);
        pw.close();
    }

    static boolean nextPermutation(List<Integer> arr) {
        int i = arr.size() - 2;
        while (i >= 0 && arr.get(i) >= arr.get(i + 1)) {
            i--;
        }
        if (i < 0) {
            return false;
        }

        int j = arr.size() - 1;
        while (arr.get(j) <= arr.get(i)) {
            j--;
        }

        int temp = arr.get(i);
        arr.set(i, arr.get(j));
        arr.set(j, temp);

        Collections.reverse(arr.subList(i + 1, arr.size()));
        return true;
    }
}

