        for (int i = 0; i < lim; ++i) {
            a[i] += a[i + lim];
            if (a[i] >= mod) a[i] -= mod;
        }
        fwt(a, lim);
        fwt(a, lim + lim);
    }

    static void fwt2(int[] a, int lim) {
        if ((lim /= 2) == 0) return;
        for (int i = 0; i < lim; ++i) {
            a[i] -= a[i + lim];
            if (a[i] < 0) a[i] += mod;
        }
        fwt2(a, lim);
        fwt2(a, lim + lim);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        int n_input = Integer.parseInt(br.readLine().trim());
        int n = n_input;

        int[][] a = new int[maxn][maxn];
        int[] b = new int[400];

        for (int i = 0; i < n; i++) {
            String[] line = br.readLine().split("\\s+");
            for (int j = 0; j < n; j++) {
                a[i][j] = Integer.parseInt(line[j]);
                a[i][j] = (int) ((long) a[i][j] * mod_inv(100) % mod);
                b[i * n + j] = a[i][j];
            }
        }

        List<List<Integer>> v = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            v.add(new ArrayList<>());
        }

        int[] cnt_popcount = new int[maxn];
        int[] mp = new int[1 << n];

        for (int i = 0; i < (1 << n); i++) {
            v.get(popcount(i)).add(i);
            mp[i] = cnt_popcount[popcount(i)]++;
        }

        int m = n / 2;
        int[] f = new int[1 << cnt_popcount[m]];

        for (int i = 0; i < (1 << (m * n)); i++) {
            long p = 1;
            int[] S = new int[3];

            for (int j = 0; j < m * n; j++) {
                if ((i >> j & 1) == 1) {
                    p = p * b[j] % mod;
                } else {
                    p = p * (mod + 1 - b[j]) % mod;
                }
            }

            for (int j = 0; j < m; j++) {
                S[j] = (i >> j * n) & ((1 << n) - 1);
            }

            int st = 0;
            for (int j : v.get(m)) {
                int[] s = new int[maxn];
                int cnt = 0;
                for (int k = j; k > 0; k &= k - 1) {
                    s[cnt++] = Integer.numberOfTrailingZeros(k);
                }

                Arrays.sort(s, 0, cnt);

                do {
                    boolean valid = true;
                    for (int idx = 0; idx < cnt; idx++) {
                        if ((S[idx] >> s[idx] & 1) == 0) {
                            valid = false;
                            break;
                        }
                    }
                    if (valid) {
                        st |= 1 << mp[j];
                    }
                } while (nextPermutation(s, cnt));
            }

            f[st] = (f[st] + (int) p) % mod;
            if (f[st] >= mod) f[st] -= mod;
        }

        int M = n - m;
        int[] g = new int[1 << cnt_popcount[M]];

        for (int i = 0; i < (1 << (M * n)); i++) {
            long p = 1;
            int[] S = new int[3];

            for (int j = 0; j < M * n; j++) {
                if ((i >> j & 1) == 1) {
                    p = p * b[j + n * m] % mod;
                } else {
                    p = p * (mod + 1 - b[j + n * m]) % mod;
                }
            }

            for (int j = 0; j < M; j++) {
                S[j] = (i >> j * n) & ((1 << n) - 1);
            }

            int st = 0;
            for (int j : v.get(n - m)) {
                int[] s = new int[maxn];
                int cnt = 0;
                for (int k = j; k > 0; k &= k - 1) {
                    s[cnt++] = Integer.numberOfTrailingZeros(k);
                }

                Arrays.sort(s, 0, cnt);

                do {
                    boolean valid = true;
                    for (int idx = 0; idx < cnt; idx++) {
                        if ((S[idx] >> s[idx] & 1) == 0) {
                            valid = false;
                            break;
                        }
                    }
                    if (valid) {
                        st |= 1 << mp[~j & ((1 << n) - 1)];
                    }
                } while (nextPermutation(s, cnt));
            }

            g[st] = (g[st] + (int) p) % mod;
            if (g[st] >= mod) g[st] -= mod;
        }

        fwt(f, 1 << cnt_popcount[m]);
        fwt(g, 1 << cnt_popcount[m]);

        for (int i = 0; i < (1 << cnt_popcount[m]); i++) {
            f[i] = (int) ((long) f[i] * g[i] % mod);
        }

        fwt2(f, 1 << cnt_popcount[m]);

        int result = 0;
        for (int i = 1; i < (1 << cnt_popcount[m]); i++) {
            result += f[i];
            if (result >= mod) result -= mod;
        }

        pw.println(result);
        pw.close();
    }

    static boolean nextPermutation(int[] arr, int len) {
        int i = len - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) {
            i--;
        }
        if (i < 0) return false;

        int j = len - 1;
        while (arr[j] <= arr[i]) {
            j--;
        }

        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;

        reverse(arr, i + 1, len - 1);
        return true;
    }

    static void reverse(int[] arr, int start, int end) {
        while (start < end) {
            int temp = arr[start];
            arr[start] = arr[end];
            arr[end] = temp;
            start++;
            end--;
        }
    }
}

