using namespace __gnu_pbds;

template<typename T>
using ordered_set = tree<
T,
null_type,
less<T>,
rb_tree_tag,
tree_order_statistics_node_update>;

typedef long long LL;
typedef pair<int,int> PII;
typedef vector<PII> VPII;

const LL mod = 1000000007LL;

LL modPow(LL base, LL exp) {
    LL result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<vector<int>> tab(7, vector<int>(7, 0));
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            cin >> tab[i][j];
        }
    }

    for (int i = n + 1; i <= 6; i++) {
        tab[i][i] = 100;
    }

    vector<PII> edges;
    for (int i = 1; i <= 6; i++) {
        for (int j = 1; j <= 6; j++) {
            edges.emplace_back(i, j);
        }
    }

    unordered_map<int, int> maskMap;
    int idx = 0;
    for (int i = 1; i <= 6; i++) {
        for (int j = i + 1; j <= 6; j++) {
            for (int k = j + 1; k <= 6; k++) {
                maskMap[(1 << i) ^ (1 << j) ^ (1 << k)] = idx++;
            }
        }
    }

    const int edgeCount = 36;
    const int half = 18;
    const LL inv100 = modPow(100, mod - 2);

    vector<vector<LL>> dp(1 << 20, vector<LL>(2, 0));

    for (int block = 0; block < 2; block++) {
        for (int mask = 0; mask < (1 << half); mask++) {
            LL prob = 1;
            vector<PII> selected;

            for (int bit = 0; bit < half; bit++) {
                if (mask & (1 << bit)) {
                    int idx = bit + block * half;
                    prob = (prob * tab[edges[idx].first][edges[idx].second] % mod) * inv100 % mod;
                    selected.emplace_back(edges[idx]);
                } else {
                    int idx = bit + block * half;
                    prob = (prob * (100 - tab[edges[idx].first][edges[idx].second]) % mod) * inv100 % mod;
                }
            }

            int finalMask = 0;
            for (int i = 0; i < (int)selected.size(); i++) {
                for (int j = i + 1; j < (int)selected.size(); j++) {
                    if (selected[i].first != selected[j].first && selected[i].second != selected[j].second) {
                        for (int k = j + 1; k < (int)selected.size(); k++) {
                            if (selected[i].first != selected[k].first && 
                                selected[j].first != selected[k].first && 
                                selected[i].second != selected[k].second && 
                                selected[j].second != selected[k].second) {
                                int curMask = (block ? 126 : 0) ^ 
                                    ((1 << selected[i].second) | 
                                     (1 << selected[j].second) | 
                                     (1 << selected[k].second));
                                if (maskMap.count(curMask)) {
                                    finalMask |= (1 << maskMap[curMask]);
                                }
                            }
                        }
                    }
                }
            }

            dp[finalMask][block] = (dp[finalMask][block] + prob) % mod;
        }
    }

    for (int bit = 0; bit < 20; bit++) {
        for (int mask = 0; mask < (1 << 20); mask++) {
            if (mask & (1 << bit)) {
                dp[mask][0] = (dp[mask][0] + dp[mask ^ (1 << bit)][0]) % mod;
            }
        }
    }

    LL result = 1;
    int fullMask = (1 << 20) - 1;
    for (int mask = 0; mask < (1 << 20); mask++) {
        LL complement = dp[fullMask ^ mask][1];
        result = (result - dp[mask][0] * complement % mod + mod) % mod;
    }

    cout << result << '\n';
    return 0;
}

