#include <bits/stdc++.h>
using namespace std;

using ll = long long;
#define pb push_back

constexpr int MAXN = 32;
constexpr int MAXB = 60;
constexpr int MOD = 1000000007;
constexpr ll INF = 2000000000000000000LL;

inline void normalize(int &x) {
    if (x >= MOD) x -= MOD;
    else if (x < 0) x += MOD;
}

struct Matrix {
    int data[MAXN][MAXN];
    int size;

    Matrix(int sz = 0, int diag = 0) : size(sz) {
        for (int i = 0; i < size; ++i)
            for (int j = 0; j < size; ++j)
                data[i][j] = (i == j ? diag : 0);
    }

    int* operator[](int idx) { return data[idx]; }

    Matrix operator*(const Matrix& other) const {
        Matrix res(size, 0);
        for (int i = 0; i < size; ++i)
            for (int k = 0; k < size; ++k) {
                if (!data[i][k]) continue;
                for (int j = 0; j < size; ++j) {
                    res[i][j] = (res[i][j] + 1LL * data[i][k] * other.data[k][j]) % MOD;
                }
            }
        return res;
    }

    Matrix operator+(const Matrix& other) const {
        Matrix res(size, 0);
        for (int i = 0; i < size; ++i)
            for (int j = 0; j < size; ++j)
                res[i][j] = (data[i][j] + other.data[i][j]) % MOD;
        return res;
    }

    bool operator==(const Matrix& other) const {
        if (size != other.size) return false;
        for (int i = 0; i < size; ++i)
            for (int j = 0; j < size; ++j)
                if (data[i][j] != other.data[i][j]) return false;
        return true;
    }
};

