    vector<int>& operator[](int i) { return data[i]; }
    const vector<int>& operator[](int i) const { return data[i]; }

    Matrix operator*(const Matrix& b) const {
        Matrix res(n, 0);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                for (int k = 0; k < n; ++k)
                    res[i][k] = norm(res[i][k] + 1LL * data[i][j] * b.data[j][k] % MOD);
        return res;
    }

    Matrix operator+(const Matrix& b) const {
        Matrix res(n, 0);
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                res[i][j] = norm(data[i][j] + b.data[i][j]);
        return res;
    }

    bool operator==(const Matrix& b) const {
        if (n != b.n) return false;
