    Matrix() { memset(mat, 0, sizeof(mat)); }

    void normalize() {
        for (int i = 0; i < dim; ++i)
            for (int j = 0; j < dim; ++j)
                mat[i][j] = ((mat[i][j] % MOD) + MOD) % MOD;
    }
