            n = size;
            s = new long[size][size];
        }

        Matrix(int size, boolean identity) {
            n = size;
            s = new long[size][size];
            if (identity) {
                for (int i = 0; i < size; i++) {
                    s[i][i] = 1;
                }
            }
        }

        static Matrix multiply(Matrix a, Matrix b) {
            Matrix c = new Matrix(a.n);
            c.n = a.n;
            for (int i = 0; i < a.n; i++) {
                for (int j = 0; j < a.n; j++) {
                    c.s[i][j] = 0;
                    for (int k = 0; k < a.n; k++) {
                        c.s[i][j] += a.s[i][k] * b.s[k][j];
                        c.s[i][j] %= MOD;
                    }
                }
            }
            return c;
        }

        void swapRows(int row1, int row2) {
            for (int col = 0; col < n; col++) {
                long temp = s[row1][col];
                s[row1][col] = s[row2][col];
                s[row2][col] = temp;
            }
        }

        void swapCols(int col1, int col2) {
            for (int row = 0; row < n; row++) {
                long temp = s[row][col1];
                s[row][col1] = s[row][col2];
                s[row][col2] = temp;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long m = sc.nextLong();

        Matrix[][] bi = new Matrix[65][65];
        for (int i = 0; i < 65; i++) {
