            bi[0][0].s[i][i] = 1;
            bi[0][0].s[0][i] = 1;
        }

        while (y * m <= n) {
            y *= m;
            x++;
        }

        for (int t = 0; t <= x; t++) {
            if (t != 0) {
                bi[t][0] = new Matrix(bi[t-1][0].n);
                bi[t][0].s = deepCopy(bi[t-1][0].s, bi[t-1][0].n);
                for (i = 1; i < m; i++) {
                    bi[t][0] = Matrix.multiply(bi[t][0], bi[t-1][i]);
                }
            }
            for (i = 1; i < m; i++) {
                bi[t][i] = new Matrix(bi[t][i-1].n);
                bi[t][i].s = deepCopy(bi[t][i-1].s, bi[t][i-1].n);

                for (j = (int)m - 2; j >= 0; j--) {
                    for (k = 0; k <= m; k++) {
                        long temp = bi[t][i].s[j][k];
                        bi[t][i].s[j][k] = bi[t][i].s[j+1][k];
                        bi[t][i].s[j+1][k] = temp;
                    }
                }

                for (j = (int)m - 2; j >= 0; j--) {
                    for (k = 0; k <= m; k++) {
                        long temp = bi[t][i].s[k][j];
                        bi[t][i].s[k][j] = bi[t][i].s[k][j+1];
                        bi[t][i].s[k][j+1] = temp;
                    }
                }
            }
        }

        I = new Matrix((int)(m + 1), true);

