    long long entries[31][31];

    Matrix() {
        for (int i = 0; i < 31; ++i)
            fill(entries[i], entries[i] + 31, 0LL);
    }

    Matrix operator*(const Matrix& other) const {
        Matrix product;
        for (int i = 0; i <= dimension; ++i)
            for (int j = 0; j <= dimension; ++j)
                for (int k = 0; k <= dimension; ++k)
                    product.entries[i][j] = (product.entries[i][j] + entries[i][k] * other.entries[k][j]) % MOD;
        return product;
    }
};

Matrix precomputed[100];

Matrix cyclic_permutation(int shift) {
    shift = ((shift % dimension) + dimension) % dimension;
    Matrix result;
    for (int i = 0; i < dimension; ++i)
        result.entries[i][(i + shift) % dimension] = 1;
    result.entries[dimension][dimension] = 1;
    return result;
}

void construct_initial_matrix() {
    for (int i = 1; i < dimension; ++i)
        precomputed[0].entries[i][i] = 1;
    precomputed[0].entries[dimension][0] = 1;
    precomputed[0].entries[dimension][dimension] = 2;
    precomputed[0].entries[0][dimension] = MOD - 1;
}

