    for (int i = (int)base_digits.size() - 1; i >= 0; --i) {
        for (int j = 0; j < base_digits[i]; ++j)
            final_matrix = final_matrix * precomputed[i] * cyclic_permutation(1);
    }

    long long answer = final_matrix.entries[dimension][dimension] % MOD;
    if (answer < 0) answer += MOD;
    cout << answer;
}

