#define  LL  long long
#define  ULL unsigned long long

inline void add(LL &x, LL y) {
	x = (x + y) % mod;
}

int r;

struct Matrix {
	LL a[N][N];
	void toZero() {
		memset(a, 0, sizeof a);
	}
	void toE() {
		toZero();
		REP(i, r)
			a[i][i] = 1;
	}
	friend Matrix operator * (const Matrix &a, const Matrix &b) {
		Matrix ret; ret.toZero();
		REP(i, r) REP(j, r) REP(k, r)
				add(ret.a[i][j], a.a[i][k] * b.a[k][j]);
		return ret;
	}
};

LL n, K;
Matrix one[70];
Matrix two[70];
Matrix rotr[70], rotc[70];

int Main() {
    ios_base::sync_with_stdio(0);

    cin >> n >> K;
    r = K + 1;

    // 0 - > single 1
    // i - > i - 1
    REP(i, K+1) {
    	one[i].toE();
    	if (i)
    		REP(j, K+1)
    			one[i].a[i][j] = 1;
    }

    REP(i, K+1) {
    	rotr[i].toE();
    	if (i == 1) {
    		rotr[i].toZero();
    		rotr[i].a[0][0] = 1;
    		rotr[i].a[1][K] = 1;
    		for (int j = 2; j <= K; j++)
    			rotr[i].a[j][j-1] = 1;
    	} else if (i > 1)
    		rotr[i] = rotr[1] * rotr[i-1];
    }

    REP(i, K+1) {
    	rotc[i].toE();
    	if (i == 1) {
    		rotc[i].toZero();
    		rotc[i].a[0][0] = 1;
    		rotc[i].a[K][1] = 1;
    		for (int j = 2; j <= K; j++)
    			rotc[i].a[j-1][j] = 1;
    	} else if (i > 1)
    		rotc[i] = rotc[i-1] * rotc[1];
    }


    two[1].toE();
    FOR(i, K)
    	two[1] = one[i] * two[1];

    int bit = 0;
    int num[70];
    while (n) {
    	num[bit++] = n % K;
    	n /= K;
    }

    for (int i = 2; i <= bit; i++) {
    	two[i].toE();
