    for (int idx = 2; idx <= (int)digits.size(); ++idx) {
        binary_ops[idx].identity();
        for (int j = 0; j < K_val; ++j)
            binary_ops[idx] = row_transform[j] * binary_ops[idx-1] * col_transform[j] * binary_ops[idx];
    }

    Matrix ans_matrix;
    ans_matrix.identity();

    int cur_pos = 0;
    for (int i = 0; i < (int)digits.size(); ++i) {
        if (i == (int)digits.size() - 1) {
            for (int j = 0; j < digits[i]; ++j) {
                ans_matrix = unary_ops[cur_pos % K_val + 1] * ans_matrix;
                ++cur_pos;
