                    }
                    res.data[i][j] = (int) sum;
                }
            }
            return res;
        }

        Matrix shift(int shiftVal) {
            int k = this.rows - 1;
            shiftVal = (k - shiftVal) % k;
            if (shiftVal < 0) shiftVal += k;
            int[][] resData = new int[this.rows][this.cols];
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < k; j++) {
                    resData[i][j] = this.data[(i + shiftVal) % k][(j + shiftVal) % k];
                }
            }
            for (int j = 0; j < k; j++) {
                resData[k][j] = this.data[k][(j + shiftVal) % k];
            }
            for (int j = k; j < this.cols; j++) {
                resData[k][j] = this.data[k][j];
            }
            return new Matrix(resData);
        }
    }

