            Matrix e = Matrix.identity(k + 1);

            for (int depth = 1; depth < maxDepth; depth++) {
                dp.add(e);
                Matrix bs = dp.get(depth - 1);
                int curx = k;
                for (int i = 0; (1 << i) <= curx; i++) {
                    if ((curx & (1 << i)) != 0) {
                        Matrix shifted = dp.get(depth).shift(1 << i);
                        dp.set(depth, Matrix.multiply(bs, shifted));
