                base = Matrix.multiply(base, shifted);
                sl = (sl + 1) % k;
            }
        }

        int res = 0;
        for (int i = 0; i <= k; i++) {
            res = (res + base.data[0][i]) % MOD;
        }
        System.out.println(res);
    }
}

