        if (scanner.hasNextLong()) {
            n = scanner.nextLong();
            k = scanner.nextInt();
            return true;
        }
        return false;
    }

    static void process() {
        List<Integer> digits = new ArrayList<>();
        long temp = n;
        while (temp > 0) {
            digits.add((int)(temp % k));
            temp /= k;
        }

        // Initialize base_matrices[0][d]
