  for (int j = 0; j < K; j++)
    retpk[0].many[0][j] = 1;

  for (int pk = 1; pk < nd; pk++) {
    retpk[pk] = retpk[pk-1];
    for (int v = 1; v < K; v++)
      retpk[pk] = res_t(retpk[pk], res_t(retpk[pk-1], v));
