      shifts[k][i][(i + k) % d] = 1;
    }
    shifts[k][d][d] = 1;
  }

  auto units = Make3DVector<FiniteField>(d, d + 1, d + 1, 0);
  for (int k = 0; k < d; k++) {
    for (int i = 0; i < d + 1; i++) {
      units[k][i][i] = 1;
