            this.size = size;
            this.data = new int[size][size];
        }

        void identity() {
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    data[i][j] = (i == j) ? 1 : 0;
                }
            }
        }

        void copyFrom(Matrix other) {
            for (int i = 0; i < size; i++) {
                System.arraycopy(other.data[i], 0, data[i], 0, size);
            }
        }

        static void multiply(Matrix A, Matrix B, Matrix C) {
            for (int i = 0; i < A.size; i++) {
                for (int j = 0; j < A.size; j++) {
                    long cur = 0;
                    for (int k = 0; k < A.size; k++) {
                        if (cur > LIM) cur %= MOD;
                        cur += (long) A.data[i][k] * B.data[k][j];
                    }
                    C.data[i][j] = (int) (cur % MOD);
                }
            }
        }

        void print() {
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    System.out.printf("%2d ", data[i][j]);
                }
