        for (int i = 0; i <= maxExp; i++) {
            for (int j = 0; j < base; j++) {
                mat[i][j] = new Matrix(base + 1);
            }
        }

        // Initialize mat[0][i]
        for (int i = 0; i < base; i++) {
            for (int j = 0; j <= base; j++) {
                for (int k = 0; k <= base; k++) {
                    mat[0][i].data[j][k] = (j == k || i == j) ? 1 : 0;
                }
