public class Main {
    static final long M = 1000000007;
    static long N;
    static int K;
    static List<int[][]> R = new ArrayList<>();
    static int[][][] D = new int[100][40][][];

    static void resize_matrix(int[][] A, int a, int b) {
        for (int i = 0; i < a; i++) {
            Arrays.fill(A[i], 0);
        }
    }

    static int[][] multiply_matrices(int[][] A, int[][] B) {
        int n = A.length;
        int m = B.length;
        int p = B[0].length;
        int[][] C = new int[n][p];
        for (int i = 0; i < n; ++i) {
            for (int k = 0; k < m; ++k) {
                if (A[i][k] == 0) continue;
                for (int j = 0; j < p; ++j) {
                    C[i][j] = (int)((C[i][j] + (long)A[i][k] * B[k][j]) % M);
                }
            }
        }
        return C;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Long.parseLong(st.nextToken());
        K = Integer.parseInt(st.nextToken());

        // Count digits in base K
        long power = 1;
        int digits = 0;
        while (power <= N / K) {
            power *= K;
            ++digits;
        }
        power *= K; // now power > N
        power /= K;

        int[] baseK = new int[digits];
        long tempN = N;
        for (int i = 0; i < digits; ++i) {
            baseK[i] = (int)(tempN / power);
            tempN %= power;
            power /= K;
        }

        // Initialize R
        for (int j = 0; j <= K; ++j) {
            int[][] mat = new int[K + 1][K + 1];
            resize_matrix(mat, K + 1, K + 1);
            R.add(mat);
        }

        // Initialize D
        for (int i = 0; i <= digits; ++i) {
            for (int j = 0; j < K; ++j) {
                D[i][j] = new int[K + 1][K + 1];
                resize_matrix(D[i][j], K + 1, K + 1);
            }
        }

        // Initialize R[0] and R[1]
        R.get(0)[K][K] = 1;
        R.get(1)[K][K] = 1;
        for (int j = 0; j < K; ++j) {
