    void identity() {
        memset(m, 0, sizeof(m));
        for (int i = 1; i <= dim; ++i) m[i][i] = 1;
    }

    Matrix operator*(const Matrix& other) const {
        Matrix res;
        res.dim = dim;
        static ll buf[MAX_DIM][MAX_DIM];
        const ll MOD2 = (ll)MOD * MOD;

        for (int i = 1; i <= dim; ++i)
            for (int j = 1; j <= dim; ++j)
                buf[i][j] = 0;

        for (int i = 1; i <= dim; ++i)
            for (int p = 1; p <= dim; ++p)
                for (int j = 1; j <= dim; ++j)
                    buf[i][j] += (ll)m[i][p] * other.m[p][j];

        for (int i = 1; i <= dim; ++i)
            for (int j = 1; j <= dim; ++j)
                res.m[i][j] = buf[i][j] % MOD;

        return res;
    }
};

Matrix F[80][MAX_DIM], P[80][MAX_DIM], S[80][MAX_DIM];

void compute() {
    vector<int> digits;
    ll x = n;
    while (x) {
        digits.push_back(x % k);
        x /= k;
