    S[0][k - 1] = F[0][k - 1];

    for (int d = 1; d < k; ++d)
        P[0][d] = F[0][d] * P[0][d - 1];

    for (int d = k - 2; d >= 0; --d)
        S[0][d] = S[0][d + 1] * F[0][d];

