                for (int j = 0; j < size; j++) {
                    v[i][j] = 0;
                }
            }
        }

        Matrix multiply(Matrix a) {
            Matrix res = new Matrix(size);
            for (int k = 0; k <= size - 1; k++) {
                for (int i = 0; i <= size - 1; i++) {
                    if (v[i][k] != 0) {
                        for (int j = 0; j <= size - 1; j++) {
