import java.util.*;

public class Main {
    static final long mod = 1000000007;
    static final int N = 33;
    static int[] bin = new int[N * 2];
    static int n, m;

    static class Matrix {
        long[][] mat = new long[N][N];

        Matrix() {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    mat[i][j] = 0;
                }
            }
        }

        Matrix multiply(Matrix a) {
            Matrix res = new Matrix();
            for (int i = 0; i <= m; i++) {
                for (int j = 0; j <= m; j++) {
                    for (int k = 0; k <= m; k++) {
                        res.mat[i][j] = (res.mat[i][j] + mat[i][k] * a.mat[k][j]) % mod;
                    }
                }
            }
            return res;
        }
    }

    static Matrix[][] ansMatrix = new Matrix[N * 2][N];
    static Matrix[][] P = new Matrix[N * 2][N];
    static Matrix[][] S = new Matrix[N * 2][N];
    static Matrix[][] A = new Matrix[N * 2][N];
    static Matrix ans = new Matrix();

    static int read(Scanner scanner) {
        int x = 0, f = 1;
        String token = scanner.next();
        char[] chars = token.toCharArray();
        int idx = 0;

        if (chars[idx] == '-') {
            f = -1;
            idx++;
        }

        while (idx < chars.length && Character.isDigit(chars[idx])) {
            x = x * 10 + (chars[idx] - '0');
            idx++;
        }

        return x * f;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = read(scanner);
        m = read(scanner);

        int n2 = n;
        int len = -1;

        while (n2 > 0) {
            len++;
            bin[len] = n2 % m;
            n2 = n2 / m;
        }
        len++;

        for (int i = 0; i <= m; i++) {
            ans.mat[0][i] = 1;
        }

        for (int i = 0; i < len; i++) {
            for (int j = 0; j <= m; j++) {
                A[i][j] = new Matrix();
                A[i][j].mat[j][j] = 1;
            }

            if (i == 0) {
                for (int j = 0; j < m; j++) {
                    A[i][j] = new Matrix();
                    A[i][j].mat[m][m] = 1;
                    for (int k = 0; k < m; k++) {
                        if (k != j) {
                            A[i][j].mat[k][k] = 1;
                            continue;
                        }
                        for (int l = 0; l <= m; l++) {
                            A[i][j].mat[k][l] = 1;
                        }
                    }
                }
            } else {
                for (int j = 0; j < m; j++) {
                    if (j == 0) {
                        A[i][j] = S[i - 1][0];
                    } else {
                        A[i][j] = S[i - 1][j].multiply(P[i - 1][j - 1]);
                    }
                }
            }

            P[i][0] = A[i][0];
            for (int j = 1; j < m; j++) {
                P[i][j] = P[i][j - 1].multiply(A[i][j]);
            }

            S[i][m - 1] = A[i][m - 1];
            for (int j = m - 2; j >= 0; j--) {
                S[i][j] = A[i][j].multiply(S[i][j + 1]);
            }
        }

        int j = 0;
        for (int i = len - 1; i >= 0; i--) {
            while (bin[i] > 0) {
                ans = ans.multiply(A[i][j]);
                j++;
                if (j == m) j = 0;
                bin[i]--;
            }
        }

        System.out.println(ans.mat[0][m]);
    }
}

