int fpow(int a,int b)
{
	int ans=1,t=a;
	while(b)
	{
		if(b&1)ans=1ll*ans*t%p;
		t=1ll*t*t%p;b>>=1;
	}
	return ans;
}
int lowbit(int x)
{
	return x&(-x);
}
