import java.util.*;
import java.io.*;

public class Main {
    static int n, k, p;
    static int[][] f;
    static int[] fac;
    static int[] inv;

    static int fpow(int a, int b) {
        int ans = 1, t = a;
        while (b > 0) {
            if ((b & 1) == 1) {
                ans = (int) ((long) ans * t % p);
            }
            t = (int) ((long) t * t % p);
            b >>= 1;
        }
        return ans;
    }

    static int lowbit(int x) {
        return x & (-x);
    }

    static void init() {
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (int) ((long) fac[i - 1] * i % p);
        }
        inv[n] = fpow(fac[n], p - 2);
        for (int i = n; i >= 1; i--) {
            inv[i - 1] = (int) ((long) inv[i] * i % p);
        }
    }

    static int solve(int cur, int S) {
        if (f[cur][S] != -1) {
            return f[cur][S];
        }
        if (S == 0) {
            f[cur][S] = fac[n];
            for (int i = 1; i <= cur; i++) {
                f[cur][S] = (int) ((long) f[cur][S] * (k - i + 1) % p);
            }
            return f[cur][S];
        }
        f[cur][S] = 0;
        int U = S - lowbit(S);
        for (int T = U; T > 0; T = (T - 1) & U) {
            f[cur][S] = (int) ((f[cur][S] + (long) inv[S - T] * solve(cur + 1, T)) % p);
        }
        f[cur][S] = (int) ((f[cur][S] + (long) inv[S] * solve(cur + 1, 0)) % p);
        return f[cur][S];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        p = Integer.parseInt(st.nextToken());

        int ans = 1;
        for (int i = 1; i <= n; i++) {
            ans = (int) ((long) ans * k % p);
        }

        if (n % 2 == 0) {
            fac = new int[250010];
            inv = new int[250010];
            f = new int[26][250010];
            for (int i = 0; i < 26; i++) {
                Arrays.fill(f[i], -1);
            }
            init();
            ans = (ans - solve(0, n) + p) % p;
        }

        System.out.println(ans);
    }
}

