import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line = br.readLine().split(" ");
        int n = Integer.parseInt(line[0]);
        int k = Integer.parseInt(line[1]);
        int mod = Integer.parseInt(line[2]);

        // Fast exponentiation function
        class PowerFunction {
            Map<String, Integer> memo = new HashMap<>();

            int power(int a, int n) {
                if (n == 0) return 1;
                String key = a + "," + n;
                if (memo.containsKey(key)) return memo.get(key);

                int ret = power(a, n / 2);
                ret = (int) ((1L * ret * ret) % mod);
                if (n % 2 == 1) {
                    ret = (int) ((1L * ret * a) % mod);
                }
                memo.put(key, ret);
                return ret;
            }
        }

        PowerFunction pf = new PowerFunction();

        if (n % 2 == 1) {
            System.out.println(pf.power(k, n));
            return;
        }

        int[] fac = new int[n + 1];
        int[] inv = new int[n + 1];
        int[] len = new int[n + 1];
        boolean[] vis = new boolean[1 << n];

        // dp[i][j] = number of ways to partition j elements into i non-empty subsets
        int[][] dp = new int[k + 1][1 << n];

        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (int) ((1L * fac[i - 1] * i) % mod);
        }

        inv[n] = pf.power(fac[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = (int) ((1L * inv[i + 1] * (i + 1)) % mod);
        }

        List<Integer> listVec = new ArrayList<>();
        for (int i = 0; (1 << i) <= n; i++) {
            if ((n & (1 << i)) != 0) {
                listVec.add(i);
            }
        }

        dp[0][0] = 1;

        // Precompute len[i] = number of 1-bits in i
        for (int i = 0; i <= n; i++) {
            int cnt = 0;
            int x = i;
            while (x != 0) {
                cnt++;
                x = (x - 1) & x;
            }
            len[i] = cnt;
        }

        // Mark all subsets of n
        for (int mask = n; ; mask = (mask - 1) & n) {
            vis[mask] = true;
            if (mask == 0) break;
        }

        // DP transitions
        for (int mask = 1; mask <= n; mask++) {
            if (!vis[mask]) continue;
            for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                int l = Math.min(k, len[mask - sub] + 1);
                for (int s = 1; s <= l; s++) {
                    if (dp[s - 1][mask - sub] != 0) {
                        dp[s][mask] = (int) ((dp[s][mask] + 1L * dp[s - 1][mask - sub] * inv[sub]) % mod);
                    }
                }
            }
        }

        int ans = 0;
        int maxI = Math.min(k, len[n]);
        for (int i = 0; i <= maxI; i++) {
            if (dp[i][n] != 0) {
                long tmp = 1L * dp[i][n] * fac[k] % mod;
                tmp = tmp * inv[k - i] % mod;
                tmp = tmp * inv[i] % mod;
                tmp = tmp * fac[n] % mod;
                ans = (int) ((ans + tmp) % mod);
            }
        }

        int result = (pf.power(k, n) - ans + mod) % mod;
        System.out.println(result);
    }
}

