            for (int j = 1; j < i; j++) {
                long term = (long) b[j] * a[i - j] % Mo * j % Mo;
                b[i] = (int) ((b[i] + Mo - term) % Mo);
            }
            b[i] = (int) ((long) b[i] * pwr(i, Mo - 2) % Mo);
        }
    }

