        b[0] = 1;
        for (int i = 1; i <= nn; i++) {
            b[i] = 0;
            for (int j = 1; j <= i; j++) {
                long term = (long) a[j] * b[i - j] % Mo * j % Mo;
                b[i] = (int) ((b[i] + term) % Mo);
            }
            b[i] = (int) ((long) b[i] * pwr(i, Mo - 2) % Mo);
        }
