import java.util.*;
import java.io.*;

public class Main {
    static long[] f = new long[30][300010];
    static long[] fac = new long[300010];
    static long[] inv = new long[300010];
    static int[] a = new int[55];
    static int[] S = new int[1000010];
    static int[] p = new int[1000010];
    static int N, n, k, MO, s;
    static long ans;

    static long pw(long x, int y) {
        long t = 1;
        while (y > 0) {
            if ((y & 1) == 1) t = t * x % MO;
            x = x * x % MO;
            y >>= 1;
        }
        return t;
    }

    static long P(int x, int y) {
        return fac[x] * inv[x - y] % MO;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        MO = Integer.parseInt(st.nextToken());

        if ((n & 1) == 1) {
            System.out.println(pw(k, n));
            return;
        }

        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = fac[i - 1] * i % MO;
        }

        inv[n] = pw(fac[n], MO - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = inv[i + 1] * (i + 1) % MO;
        }

        int t = n;
        s = 0;
        for (int i = 0; i <= 20; i++) {
            if ((t & 1) == 1) {
                a[s++] = 1 << i;
            }
            t >>= 1;
        }

        N = 1 << s;

        for (int i = 0; i < N; i++) {
            S[i] = 0;
            for (int j = 0; j < s; j++) {
                if (((i >> j) & 1) == 1) {
                    S[i] += a[j];
                }
            }
        }

        for (int i = 0; i < N; i++) {
            int t_val = -1;
            for (int j = 0; j <= 20; j++) {
                if (((i >> j) & 1) == 1) {
                    t_val = j;
                }
            }
            p[i] = (1 << (t_val + 1)) + i;
        }

        f[0][0] = 1;
        for (int i = 0; i < k; i++) {
            for (int j = 0; j < N; j++) {
                if (f[i][j] != 0) {
                    for (int k_val = p[j]; k_val < N; k_val = (k_val + 1) | j) {
                        f[i + 1][k_val] = (f[i + 1][k_val] + f[i][j] * inv[S[k_val ^ j]]) % MO;
                    }
                }
            }
        }

        ans = 0;
        for (int i = 0; i <= k; i++) {
            ans = (ans + f[i][N - 1] * P(k, i)) % MO;
        }

        ans = ans * fac[n] % MO;
        ans = (pw(k, n) - ans + MO) % MO;
        System.out.println(ans);
    }
}

