import java.util.*;

public class Main {
    static final int N = 262144;
    static int L, n, k, Mo, len;
    static int[] bit = new int[20];
    static int[] fac = new int[N];
    static int[] inv = new int[N];
    static int[] cnt = new int[N];
    static int[][] g = new int[20][N];
    static int[][] f = new int[20][N];
    static long[] h = new long[20];
    static long[] p = new long[20];

    static int pwr(int x, int y) {
        int z = 1;
        for (; y > 0; y >>= 1, x = (int) ((long) x * x % Mo)) {
            if ((y & 1) == 1) {
                z = (int) ((long) z * x % Mo);
            }
        }
        return z;
    }

    static void inc(int[] a, int i, int y) {
        a[i] = a[i] + y >= Mo ? a[i] + y - Mo : a[i] + y;
    }

    static void dec(int[] a, int i, int y) {
        a[i] = a[i] - y < 0 ? a[i] - y + Mo : a[i] - y;
    }

    static void FWT(int[] a, int len) {
        for (int i = 1; i < len; i <<= 1) {
            for (int j = 0; j < len; j += i << 1) {
                for (int k = 0; k < i; k++) {
                    inc(a, j + k + i, a[j + k]);
                }
            }
        }
    }

    static void IFWT(int[] a, int len) {
        for (int i = 1; i < len; i <<= 1) {
            for (int j = 0; j < len; j += i << 1) {
                for (int k = 0; k < i; k++) {
                    dec(a, j + k + i, a[j + k]);
                }
            }
        }
    }

    static void get_ln() {
        p[0] = 0;
        for (int i = 1; i <= n; i++) {
            p[i] = h[i] * i;
            for (int j = 1; j < i; j++) {
                p[i] -= p[j] * h[i - j] % Mo * j;
            }
            p[i] = p[i] % Mo * inv[i] % Mo;
        }
        for (int i = 0; i <= n; i++) {
            h[i] = (p[i] + Mo) % Mo;
        }
    }

    static void get_exp() {
        p[0] = 1;
        for (int i = 1; i <= n; i++) {
            p[i] = 0;
            for (int j = 1; j <= i; j++) {
                p[i] += h[j] * p[i - j] % Mo * j;
            }
            p[i] = p[i] % Mo * inv[i] % Mo;
        }
        for (int i = 0; i <= n; i++) {
            h[i] = p[i];
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        L = scanner.nextInt();
        k = scanner.nextInt();
        Mo = scanner.nextInt();
        int all = pwr(k, L);
        if ((L & 1) == 1) {
            System.out.println(all);
            return;
        }
        fac[0] = 1;
        for (int i = 1; i <= L; i++) {
            fac[i] = (int) ((long) fac[i - 1] * i % Mo);
        }
        inv[L] = pwr(fac[L], Mo - 2);
        for (int i = L - 1; i >= 0; i--) {
            inv[i] = (int) ((long) inv[i + 1] * (i + 1) % Mo);
        }
        for (int s = 1; s <= L; s++) {
            cnt[s] = cnt[s & (s - 1)] + 1;
        }
        n = 0;
        for (int i = 0; i < 19; i++) {
            if ((L >> i & 1) == 1) {
                bit[++n] = 1 << i;
            }
        }
        len = 1 << n;
        for (int i = 0; i < len; i++) {
            int s = 0;
            for (int j = 1; j <= n; j++) {
                if ((i >> (j - 1) & 1) == 1) {
                    s += bit[j];
                }
            }
            g[cnt[i]][i] = inv[s];
        }
        for (int i = 2; i <= n; i++) {
            inv[i] = (int) ((long) (Mo - Mo / i) * inv[Mo % i] % Mo);
        }
        for (int i = 0; i <= n; i++) {
            FWT(g[i], len);
        }
        for (int s = 0; s < len; s++) {
            for (int i = 0; i <= n; i++) {
                h[i] = g[i][s];
            }
            get_ln();
            for (int i = 0; i <= n; i++) {
                h[i] = h[i] * k;
            }
            get_exp();
            for (int i = 0; i <= n; i++) {
                f[i][s] = (int) (h[i] % Mo);
            }
        }
        IFWT(f[n], len);
        int ans = (int) ((long) f[n][len - 1] * fac[L] % Mo);
        ans = (all - ans + Mo) % Mo;
        System.out.println(ans);
    }
}

