        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static final int MAX_VAL = 250015;
    static long[] inv_tbl = new long[MAX_VAL];
    static long[] fact_tbl = new long[MAX_VAL];
    static long[][] dp_tab = new long[20][250005];
    static ArrayList<Integer> sub_list = new ArrayList<>();

    static void comb_init(int limit, long mod) {
        inv_tbl[0] = inv_tbl[1] = 1;
        fact_tbl[0] = fact_tbl[1] = 1;
        for (int i = 2; i <= limit; ++i) {
            inv_tbl[i] = (mod - mod / i) * inv_tbl[(int)(mod % i)] % mod;
            fact_tbl[i] = fact_tbl[i-1] * i % mod;
        }
        for (int i = 2; i <= limit; ++i) {
            inv_tbl[i] = inv_tbl[i-1] * inv_tbl[i] % mod;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line = br.readLine().split(" ");
        long n_val = Long.parseLong(line[0]);
        long k_val = Long.parseLong(line[1]);
        long mod_val = Long.parseLong(line[2]);

        comb_init((int)(n_val + 5), (int)mod_val);

        if ((n_val & 1) == 1) {
            System.out.println(mod_pow(k_val, n_val, mod_val));
            return;
        }

        sub_list.clear();
        for (int i = 2; i <= n_val; i += 2) {
            if ((i & n_val) == i) {
                sub_list.add(i);
            }
        }

        for (int i = 0; i < 20; i++) {
            Arrays.fill(dp_tab[i], 0);
        }
        dp_tab[0][(int)n_val] = 1;
        long tot_ans = 0;
        int max_depth = (int)Math.min(17L, k_val);

        for (int depth = 1; depth <= max_depth; ++depth) {
            long sub_sum = 0;
            for (int idx = 0; idx < sub_list.size(); ++idx) {
                int curr = sub_list.get(idx);
                if (dp_tab[depth-1][curr] == 0) continue;

                int next_node = curr & (curr - 1);
                int diff = next_node ^ curr;

                for (int step = diff; step <= next_node; step += diff) {
                    if ((step & next_node) == step) {
                        dp_tab[depth][step] = (dp_tab[depth][step] +
                            dp_tab[depth-1][curr] * fact_tbl[curr] % mod_val *
                            inv_tbl[step] % mod_val * inv_tbl[curr - step] % mod_val) % mod_val;
                    }
                }
                sub_sum = (sub_sum + dp_tab[depth-1][curr]) % mod_val;
            }
            tot_ans = (tot_ans + sub_sum * inv_tbl[(int)(k_val - depth)] % mod_val) % mod_val;
        }

        tot_ans = tot_ans * fact_tbl[(int)k_val] % mod_val;
        long final_val = (mod_pow(k_val, n_val, mod_val) - tot_ans % mod_val + mod_val) % mod_val;
        System.out.println(final_val);
    }
}

