            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long choose(int n, int r) {
        if (r < 0 || r > n) return 0;
        long res = factorial[n];
        res = (res * inv_factorial[r]) % MOD;
        res = (res * inv_factorial[n - r]) % MOD;
        return res;
    }

    static long solve() {
        long max_val = Math.max(N, K);
        factorial = new long[(int)max_val + 1];
        inv_factorial = new long[(int)max_val + 1];
        factorial[0] = 1;
        for (int i = 1; i <= max_val; ++i) {
