        inv_factorial[(int)max_val] = mod_exp(factorial[(int)max_val], MOD - 2, MOD);
        for (int i = (int)max_val - 1; i >= 0; --i) {
            inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % MOD;
        }

        int max_stage = (int)Math.min(18, K);
        dp = new long[max_stage + 1][300005];

