            }
            long term = dp[stage][(int)N] * choose((int)K, stage) % MOD;
            term = (term * factorial[stage]) % MOD;
            result = (result + term >= MOD) ? result + term - MOD : result + term;
        }
        result = (result * factorial[(int)N]) % MOD;
        return result;
    }

    public static void main(String[] args) throws IOException {
