import java.io.*;
import java.util.*;

public class Main {
    private static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    private static PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
    private static int P;
    private static int[][] f = new int[19][300010];
    private static int[] ifac = new int[300010];
    private static int[] fac = new int[300010];
    private static int[] inv = new int[300010];

    private static int geti() throws IOException {
        int xi = 0;
        int ch = br.read();
        boolean f = false;
        while (ch != -1 && !Character.isDigit(ch)) {
            if (ch == '-') f = true;
            ch = br.read();
        }
        while (ch != -1 && Character.isDigit(ch)) {
            xi = xi * 10 + (ch - '0');
            ch = br.read();
        }
        return f ? -xi : xi;
    }

    private static void pi(int k) {
        if (k < 0) {
            pw.print('-');
            k = -k;
        }
        if (k >= 10) pi(k / 10);
        pw.print((char) ('0' + (k % 10)));
    }

    private static long fpow(long a, int b) {
        long c = 1;
        for (; b > 0; b >>= 1, a = a * a % P) {
            if ((b & 1) == 1) c = c * a % P;
        }
        return c;
    }

    private static void init(int n) {
        fac[0] = 1;
        for (int i = 1; i <= n; ++i) fac[i] = (int) (1L * fac[i - 1] * i % P);
        ifac[n] = (int) fpow(fac[n], P - 2);
        for (int i = n - 1; i >= 0; --i) ifac[i] = (int) (1L * ifac[i + 1] * (i + 1) % P);
        inv[1] = 1;
        for (int i = 2; i <= n; ++i) inv[i] = (int) (1L * (P - P / i) * inv[P % i] % P);
    }

    private static void add(int[] f, int idx, int y) {
        f[idx] += y;
        if (f[idx] >= P) f[idx] -= P;
    }

    private static void sub(int[] f, int idx, int y) {
        f[idx] -= y;
        f[idx] -= (f[idx] >> 31) * P;
    }

    private static void FMT(int[] f, int n) {
        for (int l = 1; l < n; l <<= 1) {
            for (int i = 0; i < n; i += l << 1) {
                for (int j = 0; j < l; ++j) {
                    add(f, i + j + l, f[i + j]);
                }
            }
        }
    }

    private static void IFMT(int[] f, int n) {
        for (int l = 1; l < n; l <<= 1) {
            for (int i = 0; i < n; i += l << 1) {
                for (int j = 0; j < l; ++j) {
                    sub(f, i + j + l, f[i + j]);
                }
            }
        }
    }

    private static int pop(int x) {
        return Integer.bitCount(x);
    }

    private static void ln(int[] f, int[] g, int n) {
        g[0] = 0;
        for (int i = 1; i < n; ++i) {
            g[i] = 0;
            for (int j = 1; j < i; ++j) {
                g[i] = (int) ((g[i] + 1L * f[i - j] * g[j] % P * j) % P);
            }
            g[i] = (int) ((f[i] + 1L * g[i] * (P - inv[i]) % P) % P);
        }
    }

    private static void exp(int[] f, int[] g, int n) {
        g[0] = 1;
        for (int i = 1; i < n; ++i) {
            g[i] = 0;
            for (int j = 1; j <= i; ++j) {
                g[i] = (int) ((g[i] + 1L * g[i - j] * f[j] % P * j) % P);
            }
            g[i] = (int) (1L * g[i] * inv[i] % P);
        }
    }

    public static void main(String[] args) throws IOException {
        int n = geti();
        int k = geti();
        P = geti();
        int ans = (int) fpow(k, n);
        if ((n & 1) == 0) {
            int m = 32 - Integer.numberOfLeadingZeros(n - 1);
            init(1 << m);
            for (int i = 0; i < (1 << m); ++i) {
                f[pop(i)][i] = ifac[i];
            }
            for (int i = 0; i <= m; ++i) {
                FMT(f[i], 1 << m);
            }
            int[] F = new int[20];
            int[] G = new int[20];
            for (int i = 0; i < (1 << m); ++i) {
                for (int j = 0; j <= m; ++j) F[j] = f[j][i];
                ln(F, G, m + 1);
                for (int j = 0; j <= m; ++j) G[j] = (int) (1L * G[j] * k % P);
                exp(G, F, m + 1);
                for (int j = 0; j <= m; ++j) f[j][i] = F[j];
            }
            IFMT(f[pop(n)], 1 << m);
            ans = (P + ans - (int) (1L * f[pop(n)][n] * fac[n] % P)) % P;
        }
        pi(ans);
        pw.flush();
        pw.close();
    }
}

