public class Main {
    private static int P;
    private static int[][] f;
    private static int[] ifac;
    private static int[] fac;
    private static int[] inv;

    private static int geti(Scanner sc) {
        int xi = 0;
        char ch = (char) sc.next().charAt(0);
        boolean f = false;
        while (!Character.isDigit(ch)) {
            if (ch == '-') f = true;
            ch = (char) sc.next().charAt(0);
        }
        while (Character.isDigit(ch)) {
            xi = xi * 10 + (ch - '0');
            if (sc.hasNext()) {
                ch = (char) sc.next().charAt(0);
            } else {
                break;
            }
        }
        return f ? -xi : xi;
    }

    private static long fpow(long a, int b) {
        long c = 1;
        for (; b > 0; b >>= 1, a = a * a % P) {
            if ((b & 1) == 1) {
                c = c * a % P;
            }
        }
        return c;
    }

    private static void init(int n) {
        fac[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fac[i] = (int) ((long) fac[i - 1] * i % P);
        }
        ifac[n] = (int) fpow(fac[n], P - 2);
        for (int i = n - 1; i >= 0; --i) {
            ifac[i] = (int) ((long) ifac[i + 1] * (i + 1) % P);
        }
        inv[1] = 1;
        for (int i = 2; i <= n; ++i) {
            inv[i] = (int) ((long) (P - P / i) * inv[P % i] % P);
        }
    }

    private static void add(int[] arr, int idx, int val) {
        arr[idx] += val;
        if (arr[idx] >= P) arr[idx] -= P;
    }

    private static void sub(int[] arr, int idx, int val) {
        arr[idx] -= val;
        if (arr[idx] < 0) arr[idx] += P;
    }

    private static void FMT(int[] f, int n) {
        for (int l = 1; l < n; l <<= 1) {
            for (int i = 0; i < n; i += l << 1) {
                for (int j = 0; j < l; ++j) {
                    add(f, i + j + l, f[i + j]);
                }
            }
        }
    }

    private static void IFMT(int[] f, int n) {
        for (int l = 1; l < n; l <<= 1) {
            for (int i = 0; i < n; i += l << 1) {
                for (int j = 0; j < l; ++j) {
                    sub(f, i + j + l, f[i + j]);
                }
            }
        }
    }

