        for (int i = 1; i < n; ++i) {
            g[i] = 0;
            for (int j = 1; j < i; ++j) {
                g[i] = (int) ((g[i] + (long) f[i - j] * g[j] % P * j) % P);
            }
            g[i] = (int) ((f[i] + (long) g[i] * (P - inv[i]) % P) % P);
        }
    }

