        int n = geti(sc);
        int k = geti(sc);
        P = geti(sc);

        int ans = (int) fpow(k, n);

        if ((n & 1) == 0) {
            int m = 32 - Integer.numberOfLeadingZeros(n - 1);
            int size = 1 << m;
            f = new int[m + 1][size];
            ifac = new int[size];
            fac = new int[size];
            inv = new int[size];
            init(size);

            for (int i = 0; i < size; ++i) {
                f[pop(i)][i] = ifac[i];
            }

            for (int i = 0; i <= m; ++i) {
                FMT(f[i], size);
            }

            int[] F = new int[m + 1];
            int[] G = new int[m + 1];

            for (int i = 0; i < size; ++i) {
                for (int j = 0; j <= m; ++j) {
                    F[j] = f[j][i];
                }
                ln(F, G, m + 1);
                for (int j = 0; j <= m; ++j) {
                    G[j] = (int) ((long) G[j] * k % P);
                }
                exp(G, F, m + 1);
                for (int j = 0; j <= m; ++j) {
                    f[j][i] = F[j];
                }
            }

            IFMT(f[pop(n)], size);
            ans = (P + ans - (int) ((long) f[pop(n)][n] * fac[n] % P)) % P;
        }

        System.out.println(ans);
    }
}

