import java.util.*;
import java.io.*;

public class Main {
    static final int N = 266666;
    static final int MOD = 1000000009;

    static long[] fac = new long[N];
    static long[] inv = new long[N];
    static long[][] dp = new long[30][22];
    static long[][] a = new long[18][N];
    static long[] b = new long[N];

    static long qpow(long base, long exp, int mod) {
        long s = base % mod;
        long ans = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                ans = (ans * s) % mod;
            }
            exp >>= 1;
            s = (s * s) % mod;
        }
        return ans;
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int M = sc.nextInt();

        if ((n & 1) == 1) {
            System.out.println(qpow(k, n, M));
            return;
        }

        fac[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fac[i] = (fac[i - 1] * i) % M;
        }

        inv[n] = qpow(fac[n], M - 2, M);
        for (int i = n - 1; i >= 0; --i) {
            inv[i] = (inv[i + 1] * (i + 1)) % M;
        }

        n >>= 1;

        for (int i = 0; i <= n; ++i) {
            int pp = Integer.bitCount(i);
            a[pp][i] = inv[i * 2];
        }

        for (int i = 0; i < 17; ++i) {
            for (int j = 0; j < 17; ++j) {
                for (int u = 0; u < (1 << 17); ++u) {
                    if (((u >> j) & 1) == 1) {
                        a[i][u] = (a[i][u] + a[i][u ^ (1 << j)]) % M;
                    }
                }
            }
        }

        for (int i = 0; i < 17; ++i) {
            for (int u = 0; u < (1 << 17); ++u) {
                a[i][u] %= M;
                if (a[i][u] < 0) a[i][u] += M;
            }
        }

        int pn = Integer.bitCount(n);

        for (int i = 0; i < (1 << 17); ++i) {
            for (int x = 0; x < 30; ++x) {
                for (int y = 0; y < 22; ++y) {
                    dp[x][y] = 0;
                }
            }
            dp[0][0] = 1;

            for (int j = 1; j <= k; ++j) {
                for (int u = 0; u <= 17; ++u) {
                    for (int v = 0; u + v <= 17; ++v) {
                        dp[j][u + v] = (dp[j][u + v] + a[u][i] * dp[j - 1][v]) % M;
                    }
                    if ((u & 7) == 0) {
                        for (int v = 0; v <= 17; ++v) {
                            dp[j][v] %= M;
                            if (dp[j][v] < 0) dp[j][v] += M;
                        }
                    }
                }
                for (int v = 0; v <= 17; ++v) {
                    dp[j][v] %= M;
                    if (dp[j][v] < 0) dp[j][v] += M;
                }
            }
            b[i] = dp[k][pn];
        }

