        for (; b > 0; b >>= 1, a = a * a % P) {
            if ((b & 1) == 1) c = c * a % P;
        }
        return c;
    }

    static long fpow(long a, int b) {
        return fpow(a, b, 1);
    }

    static void init(int n) {
        fac[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fac[i] = (int) (1L * fac[i - 1] * i % P);
        }
        ifac[n] = (int) fpow(fac[n], P - 2);
        for (int i = n - 1; i >= 0; --i) {
            ifac[i] = (int) (1L * ifac[i + 1] * (i + 1) % P);
        }
        inv[1] = 1;
        for (int i = 2; i <= n; ++i) {
            inv[i] = (int) (1L * (P - P / i) * inv[P % i] % P);
        }
    }

    static void add(int[] f, int idx, int y) {
        f[idx] += y;
        if (f[idx] >= P) f[idx] -= P;
    }

    static void sub(int[] f, int idx, int y) {
        f[idx] -= y;
        f[idx] -= (f[idx] >> 31) * P;
    }

    static int sub(int x) {
        return x - (x >> 31) * P;
