    static int P;
    static int[] fac, ifac, inv;
    static int[][] f;
    static int[] t, g;

    static int geti() throws IOException {
        int xi = 0;
        int ch = br.read();
        boolean f = false;
        while (ch != -1 && !Character.isDigit(ch)) {
            if (ch == '-') f = true;
            ch = br.read();
        }
        while (ch != -1 && Character.isDigit(ch)) {
            xi = xi * 10 + (ch - '0');
            ch = br.read();
        }
        return f ? -xi : xi;
    }

    static void pi(int k) {
        if (k < 0) {
            k = -k;
            pw.print('-');
        }
        if (k >= 10) pi(k / 10);
        pw.print((char) ('0' + (k % 10)));
    }

    static long fpow(long a, int b, long c) {
        for (; b > 0; b >>= 1, a = a * a % P) {
            if ((b & 1) == 1) c = c * a % P;
        }
        return c;
    }

    static long fpow(long a, int b) {
        return fpow(a, b, 1);
    }

    static void init(int n) {
        fac = new int[n + 1];
        ifac = new int[n + 1];
        inv = new int[n + 1];
        fac[0] = 1;
        for (int i = 1; i <= n; ++i) {
            fac[i] = (int) ((long) fac[i - 1] * i % P);
        }
        ifac[n] = (int) fpow(fac[n], P - 2);
        for (int i = n - 1; i >= 0; --i) {
            ifac[i] = (int) ((long) ifac[i + 1] * (i + 1) % P);
        }
        inv[1] = 1;
        for (int i = 2; i <= n; ++i) {
            inv[i] = (int) ((long) (P - P / i) * inv[P % i] % P);
        }
    }

    static void add(int[] f, int i, int y) {
        f[i] = (f[i] + y) % P;
        if (f[i] >= P) f[i] -= P;
    }

    static void sub(int[] f, int i, int y) {
        f[i] = (f[i] - y) % P;
        if (f[i] < 0) f[i] += P;
    }

    static int sub(int x) {
        x %= P;
        if (x < 0) x += P;
        return x;
    }

    static void fpow(int[] f, int n, int k) {
        System.arraycopy(f, 0, t, 0, n + 1);
        f[0] = (1 - f[0] + P) % P;
        g[0] = 0;
        for (int i = 1; i < n; ++i) {
            f[i] = 0;
            g[i] = 0;
            for (int j = 1; j < i; ++j) {
