        for (int l = 1; l < n; l <<= 1) {
            for (int i = 0; i < n; i += l << 1) {
                for (int j = 0; j < l; ++j) {
                    add(f, i + j + l, f[i + j]);
                }
            }
        }
    }

    static void IFMT(int[] f, int n) {
        for (int l = 1; l < n; l <<= 1) {
            for (int i = 0; i < n; i += l << 1) {
                for (int j = 0; j < l; ++j) {
                    sub(f, i + j + l, f[i + j]);
                }
            }
        }
    }

