        int res = 1;
        for (; y > 0; y >>= 1, x = mul(x, x)) {
            if ((y & 1) == 1) {
                res = mul(res, x);
            }
        }
        return res;
    }

    static int inv(int x) {
        return power(x, M - 2);
    }

