            if ((y & 1) == 1) {
                res = mul(res, x);
            }
        }
        return res;
    }

    static int inv(int x) {
        return power(x, M - 2);
    }

    static final int N = 250005;
    static final int K = 19;
    static int[][] f = new int[N][K];
    static int n, k;

    static int[] fac = new int[N];
    static int[] ifac = new int[N];

    static void prefac(int nn) {
        fac[0] = 1;
        for (int i = 1; i <= nn; ++i) {
            fac[i] = mul(fac[i - 1], i);
        }
        ifac[nn] = inv(fac[nn]);
        for (int i = nn - 1; i >= 0; --i) {
            ifac[i] = mul(ifac[i + 1], i + 1);
        }
    }

    static int dp(int s, int c) {
        if (s == 0) return 1;
        if (c == k) return 0;
        int res = f[s][c];
        if (res != -1) return res;
        res = 0;
        int hb = 1;
        while (hb <= s) hb <<= 1;
        hb >>= 1;
        for (int t = s; t != -1; --t) {
            t &= s;
            if ((t & hb) == 0) {
                f[s][c] = res;
                return res;
            }
            res = add(res, mul(ifac[t], k - c, dp(s ^ t, c + 1)));
        }
        f[s][c] = res;
        return res;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        M = Integer.parseInt(st.nextToken());

        for (int i = 0; i < N; i++) {
            Arrays.fill(f[i], -1);
        }

        prefac(n);

        if ((n & 1) == 1) {
            System.out.println(power(k, n));
            return;
        }

        int result = sub(power(k, n), mul(fac[n], dp(n, 0)));
        System.out.println(result);
    }
}

