    static int[] fac;
    static int[] inv;
    static int[][] dp;

    static int lowbit(int x) {
        return x & (-x);
    }

    static int fpow(int x, int y) {
        int res = 1;
        while (y > 0) {
            if ((y & 1) == 1) {
                res = (int) ((long) res * x % mod);
            }
            x = (int) ((long) x * x % mod);
            y >>= 1;
        }
        return res;
    }

    static void init() {
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (int) ((long) fac[i - 1] * i % mod);
        }
        inv[n] = fpow(fac[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = (int) ((long) inv[i + 1] * (i + 1) % mod);
        }
    }

    static int dfs(int x, int s) {
        if (dp[x][s] != -1) {
            return dp[x][s];
        }
        if (s == 0) {
            dp[x][s] = (int) ((long) fac[n] * fac[k] % mod * inv[k - x] % mod);
            return dp[x][s];
        }
        int now = s - lowbit(s);
        dp[x][s] = 0;
        for (int t = now; t > 0; t = (t - 1) & now) {
            dp[x][s] = (int) ((dp[x][s] + (long) dfs(x + 1, t) * inv[s - t] % mod) % mod);
        }
        dp[x][s] = (int) ((dp[x][s] + (long) dfs(x + 1, 0) * inv[s] % mod) % mod);
        return dp[x][s];
    }

