import java.util.*;

public class Main {
    static int n, k, MOD;
    static long[] factorial;
    static long[] inv_factorial;
    static int[][] cache;

    static int LSB(int x) {
        return x & -x;
    }

    static long mod_exp(long base, int exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    static void precompute() {
        factorial[0] = 1;
        for (int i = 1; i <= n; ++i) {
            factorial[i] = (factorial[i-1] * i) % MOD;
        }
        inv_factorial[n] = mod_exp(factorial[n], MOD - 2);
        for (int i = n - 1; i >= 0; --i) {
            inv_factorial[i] = (inv_factorial[i+1] * (i+1)) % MOD;
        }
    }

    static int compute(int depth, int bitmask) {
        if (cache[depth][bitmask] != -1) {
            return cache[depth][bitmask];
        }
        if (bitmask == 0) {
            cache[depth][bitmask] = (int) (((factorial[n] * factorial[k]) % MOD) * inv_factorial[k - depth] % MOD);
            return cache[depth][bitmask];
        }
        int remaining = bitmask - LSB(bitmask);
        cache[depth][bitmask] = 0;
        for (int submask = remaining; submask != 0; submask = (submask - 1) & remaining) {
