    static long[][] memo;

    static int getLowestSetBit(int x) {
        return x & -x;
    }

    static long modularExponentiation(long base, int power) {
        long res = 1;
        while (power > 0) {
            if ((power & 1) == 1) {
                res = (res * base) % MODULO;
            }
            base = (base * base) % MODULO;
            power >>= 1;
        }
        return res;
