        int res = 1;
        while (e != 0) {
            if ((e & 1) != 0) 
                res = (int)((1L * res * b) % MOD);
            b = (int)((1L * b * b) % MOD);
            e >>= 1;
        }
        return res;
    }

    static void prepare() {
        factorial[0] = 1;
        for (int i = 1; i <= N; ++i)
            factorial[i] = (int)((1L * factorial[i-1] * i) % MOD);
        inv_factorial[N] = fast_power(factorial[N], MOD - 2);
        for (int i = N - 1; i >= 0; --i)
            inv_factorial[i] = (int)((1L * inv_factorial[i+1] * (i+1)) % MOD);
    }

    static int solve(int depth, int bits) {
        if (dp_table[depth][bits] != -1) 
            return dp_table[depth][bits];
        if (bits == 0) {
            dp_table[depth][bits] = (int)((1L * factorial[N] * factorial[K] % MOD) * inv_factorial[K - depth] % MOD);
