#include <iostream>
#include <vector>
using namespace std;

using ll = long long;

const int MAX_N = 250010;

ll precomputeFactorial(int limit, ll mod) {
    vector<ll> f(limit + 1);
    f[0] = 1;
    for (int i = 1; i <= limit; ++i)
        f[i] = f[i - 1] * i % mod;
    return f[limit];
}

ll modInverse(ll a, ll mod) {
    ll b = a, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= mod;
    if (u < 0) u += mod;
    return u;
}

ll extendedModInverseArray(int limit, ll mod) {
    vector<ll> inv(limit + 1);
    inv[1] = 1;
    for (int i = 2; i <= limit; ++i)
        inv[i] = mod - (mod / i) * inv[mod % i] % mod;
    for (int i = 1; i <= limit; ++i)
        inv[i] = inv[i - 1] * inv[i] % mod;
    return inv[limit];
}

int popcount(int x) {
    int cnt = 0;
    while (x) {
        cnt += x & 1;
        x >>= 1;
    }
    return cnt;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n_in, m_in, mod_in;
    cin >> n_in >> m_in >> mod_in;

    int n = n_in, m = m_in;
    ll mod = mod_in;

    vector<ll> fac(n + 1), inv(n + 1);
    fac[0] = inv[0] = inv[1] = fac[1] = 1;

    for (int i = 2; i <= n; ++i) {
        ll r = mod / i;
        ll x = mod - i * r;
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = (mod - r * inv[x] % mod) % mod;
    }

    for (int i = 2; i <= n; ++i) {
        inv[i] = inv[i - 1] * inv[i] % mod;
    }

    ll totalWays = 1;
    for (int i = 1; i <= n; ++i)
        totalWays = totalWays * m % mod;

    vector<int> pc(n + 1);
    pc[0] = 0;
    for (int i = 1; i <= n; ++i)
        pc[i] = pc[i >> 1] + (i & 1);

    if (n & 1) {
        cout << totalWays << '\n';
        return 0;
    }

    vector<vector<ll>> dp(pc[n] + 2, vector<ll>(n + 1, 0));
    dp[0][0] = 1;

    int maxPop = pc[n];
    for (int i = 0; i < maxPop && i < m; ++i) {
        for (int j = 0; j <= n; ++j) {
            if (!dp[i][j]) continue;
            int mask = n ^ j;
            for (int k = mask; k > j; k = (k - 1) & mask) {
                int state = k | j;
                dp[i + 1][state] = (dp[i + 1][state] + dp[i][j] * inv[k] % mod) % mod;
            }
        }
    }

    for (int i = 1; i <= m; ++i) {
        ll subtract = dp[i][n];
        subtract = subtract * fac[m] % mod;
        subtract = subtract * inv[m - i] % mod;
        subtract = subtract * fac[n] % mod;
        totalWays = (totalWays - subtract % mod + mod) % mod;
    }

    cout << totalWays << '\n';
    return 0;
}

