		return f[use][S]=ret;
	}
	if(use>k)return 0;
	int lbit=S&(-S);
	int U=S-lbit;
	for(int T=U;;T=(T-1)&U){
//		cerr<<"? "<<S<<" "<<T<<" "<<lbit<<endl;
		ret=(1LL*dfac[S-T]*solve(use+1,T)+ret)%Mod;	
