import java.util.*;

public class Main {
    static int Mod;
    static int n, k;
    static int[][] f;
    static int[] fac, dfac, inv;

    static int ksm(int a, int x) {
        long ans = 1;
        long w = a;
        while (x > 0) {
            if ((x & 1) == 1) {
                ans = ans * w % Mod;
            }
            w = w * w % Mod;
            x >>= 1;
        }
        return (int) ans;
    }

    static int solve(int use, int S) {
        if (f[use][S] != -1) {
            return f[use][S];
        }
        int ret = 0;
        if (S == 0) {
            ret = fac[n];
            for (int i = 1; i <= use; ++i) {
                ret = (int) ((long) ret * (k - i + 1) % Mod);
            }
            return f[use][S] = ret;
        }
        if (use > k) {
            return 0;
        }
        int lbit = S & (-S);
        int U = S - lbit;
        for (int T = U; ; T = (T - 1) & U) {
            ret = (int) ((long) dfac[S - T] * solve(use + 1, T) % Mod + ret) % Mod;
            if (T == 0) {
                break;
            }
        }
        return f[use][S] = ret;
    }

