            fac[i] = (int) ((long) fac[i - 1] * i % Mod);
            inv[i] = (int) ((long) (Mod - Mod / i) * inv[Mod % i] % Mod);
            dfac[i] = (int) ((long) dfac[i - 1] * inv[i] % Mod);
        }

        f = new int[19][n + 1];
        for (int i = 0; i <= 18; ++i) {
            for (int j = 0; j <= n; ++j) {
                f[i][j] = -1;
            }
        }

        int result = (ksm(k, n) - solve(0, n) + Mod) % Mod;
        System.out.println(result);
    }
}

