import java.util.*;

public class Main {
    static int MOD;
    static int n, k;
    static int[] factorial;
    static int[] inv_factorial;
    static int[] inv;
    static int[][] dp;

    static int mod_pow(int base, int exp) {
        long result = 1, b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            exp >>= 1;
        }
        return (int) result;
    }

    static int solve_dp(int used, int mask) {
        if (dp[used][mask] != -1) {
            return dp[used][mask];
        }

        if (mask == 0) {
            long res = factorial[n];
            for (int i = 1; i <= used; ++i) {
                res = (res * (k - i + 1)) % MOD;
            }
            dp[used][mask] = (int) res;
            return dp[used][mask];
        }

        if (used > k) {
            return 0;
        }

        int lowbit = mask & -mask;
        int upper = mask - lowbit;
        int res = 0;

        for (int subset = upper; ; subset = (subset - 1) & upper) {
