using namespace std;
const int N = 300010;
int n, K, mod;
int dp[N][20];
int cnt[N], mx[N];
long long fact[N], invFact[N];

long long modPow(long long base, long long exp, long long modulus) {
    base %= modulus;
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % modulus;
        base = (base * base) % modulus;
        exp >>= 1;
    }
    return result;
}

long long binomial(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * invFact[k] % mod * invFact[n - k] % mod;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> n >> K >> mod;
    if (n & 1) {
        cout << modPow(K, n) << '\n';
        return 0;
    }

    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;

    invFact[n] = modPow(fact[n], mod - 2, mod);
    for (int i = n - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % mod;

    for (int i = 1; i <= n; i++) {
        cnt[i] = __builtin_popcount(i);
        mx[i] = i & -i;
    }

    dp[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        if ((n & i) != i) continue;
        int low = i ^ mx[i];
        for (int k = low; k >= 0; k = (k - 1) & low) {
            int cur1 = k + mx[i];
            int cur2 = i ^ cur1;
            int up = min(K - 1, cnt[cur2]);
            long long coef = binomial(i, cur1);
            for (int j = 0; j <= up; j++) {
                dp[i][j + 1] = (dp[i][j + 1] + dp[cur2][j] * coef) % mod;
            }
            if (k == 0) break;
        }
    }

    long long ans = 0;
    for (int j = 1; j <= min(cnt[n], K); j++) {
        ans = (ans + dp[n][j] * binomial(K, j) % mod * fact[j]) % mod;
    }
    ans = (modPow(K, n) - ans + mod) % mod;
    cout << ans << '\n';
    return 0;
}

