#include <cmath>

using namespace std;

long long mod_pow(long long b, int e, int m) {
    long long r = 1;
    while (e) {
        if (e & 1) r = (r * b) % m;
        b = (b * b) % m;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int n, K, mod; cin >> n >> K >> mod;

    if (n & 1) {
        cout << mod_pow(K, n, mod) << '\n';
        return 0;
    }

    vector<long long> fact(n + 1), invfact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % mod;

    invfact[n] = mod_pow(fact[n], mod - 2, mod);
    for (int i = n; i >= 1; i--) invfact[i - 1] = invfact[i] * i % mod;

    auto C = [&](int nn, int kk) -> long long {
        if (kk < 0 || kk > nn) return 0;
        return fact[nn] * invfact[kk] % mod * invfact[nn - kk] % mod;
    };

    vector<int> bitcnt(n + 1, 0), msb(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        int tmp = i;
        while (tmp) {
            bitcnt[i]++;
            tmp &= tmp - 1;
        }
