public class Main {
    static long mod_pow(long b, int e, int m) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * b) % m;
            b = (b * b) % m;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int mod = Integer.parseInt(st.nextToken());

        if ((n & 1) == 1) {
            System.out.println(mod_pow(K, n, mod));
            return;
        }

        long[] fact = new long[n + 1];
        long[] invfact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % mod;
        }

        invfact[n] = mod_pow(fact[n], mod - 2, mod);
        for (int i = n; i >= 1; i--) {
            invfact[i - 1] = invfact[i] * i % mod;
        }

        class Combinatorics {
            long C(int nn, int kk) {
                if (kk < 0 || kk > nn) return 0;
                return fact[nn] * invfact[kk] % mod * invfact[nn - kk] % mod;
            }
        }
        Combinatorics combinatorics = new Combinatorics();

        int[] bitcnt = new int[n + 1];
        int[] msb = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            int tmp = i;
            int cnt = 0;
            while (tmp != 0) {
                cnt++;
                tmp &= tmp - 1;
            }
            bitcnt[i] = cnt;
            if (i > 0) {
                msb[i] = 1 << (int)(Math.log(i) / Math.log(2));
            }
        }

        long[][] dp = new long[n + 1][20];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            if ((i & n) != i) continue;
            int pb = msb[i];
            int rem = i ^ pb;
            for (int k = rem; ; k = (k - 1) & rem) {
                int a = k + pb;
                int b = i ^ a;
                int lim = Math.min(K - 1, bitcnt[b]);
                long comb = combinatorics.C(i, a);
                for (int j = 0; j <= lim; j++) {
                    dp[i][j + 1] = (dp[i][j + 1] + dp[b][j] * comb) % mod;
                }
                if (k == 0) break;
            }
        }

        long ans = 0;
        int top = Math.min(bitcnt[n], K);
        for (int j = 1; j <= top; j++) {
            ans = (ans + dp[n][j] * combinatorics.C(K, j) % mod * fact[j]) % mod;
        }
        ans = (mod_pow(K, n, mod) - ans + mod) % mod;
        System.out.println(ans);
    }
