    static class ModInt {
        long n;

        ModInt() {
            n = 0;
        }

        ModInt(long m) {
            n = m % MOD;
            if (n < 0) n += MOD;
        }

        ModInt add(ModInt b) {
            n = (n + b.n) % MOD;
            if (n >= MOD) n -= MOD;
            return this;
        }

        ModInt sub(ModInt b) {
            n = (n - b.n) % MOD;
            if (n < 0) n += MOD;
            return this;
        }

        ModInt mul(ModInt b) {
            n = n * b.n % MOD;
            return this;
        }

        ModInt pow(long exp) {
            return new ModInt(modPow(n, exp, MOD));
        }

        ModInt inv() {
            return new ModInt(modPow(n, MOD - 2, MOD));
        }

        ModInt div(ModInt b) {
            return mul(b.inv());
        }

        @Override
        public String toString() {
            return String.valueOf(n);
        }
    }

