import java.util.*;
import java.io.*;

public class Main {
    static int mod;

    static int upd(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void add(int[] x, int idx, int y) {
        x[idx] = upd(x[idx] + y);
    }

    static int ksm(int x, int k) {
        int ans = 1;
        while (k > 0) {
            if ((k & 1) == 1) ans = (int)(1L * ans * x % mod);
            x = (int)(1L * x * x % mod);
            k >>= 1;
        }
        return ans;
    }

    static int[] jc, inv;

    static void init(int n) {
        jc = new int[n + 1];
        inv = new int[n + 1];
        jc[0] = 1;
        for (int i = 1; i <= n; i++) {
            jc[i] = (int)(1L * jc[i - 1] * i % mod);
        }
        inv[n] = ksm(jc[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv[i] = (int)(1L * inv[i + 1] * (i + 1) % mod);
        }
    }

    static int C(int n, int m) {
        if (n < 0 || m < 0 || n < m) return 0;
        return (int)(1L * jc[n] * inv[n - m] % mod * inv[m] % mod);
    }

    static int S(int n) {
        return n * (n + 1) / 2;
    }

    static int[] multiply(int[] A, int[] B) {
        int[] C = new int[A.length + B.length - 1];
        for (int i = 0; i < A.length; i++) {
            for (int j = 0; j < B.length; j++) {
                add(C, i + j, (int)(1L * A[i] * B[j] % mod));
            }
        }
        return C;
    }

    static int G(int n, int m) {
        return C(m + n - 1, n - 1);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        int n = sc.nextInt();
        mod = sc.nextInt();

        init(m << 1);

        int[] f = new int[n + 1];
        int[] g = new int[n + 1];
        f[0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                int term = (int)(1L * f[j] * f[i - 1 - j] % mod * C(i - 1, j) % mod);
                add(f, i, term);
            }
            f[i] = (int)(1L * f[i] * (i + 1) % mod);
        }

