            for (int j = 0; j < i; j++) {
                long term1 = 2L * f[j] * g[i - 1 - j] % mod * C(i - 1, j) % mod * (i + 1) % mod;
                long term2 = 1L * C(i - 1, j) * (S(j) + S(i - 1 - j)) % mod * f[j] % mod * f[i - 1 - j] % mod;
                int term = (int)((term1 + term2) % mod);
                add(g, i, term);
            }
        }

        f[0] = 0;
        for (int i = 0; i <= n; i++) {
            g[i] = (int)(1L * g[i] * inv[i] % mod);
            f[i] = (int)(1L * f[i] * inv[i] % mod);
        }

