public class Main {
    static final int maxn = 510;
    static int n, m, P;
    static int[][] C = new int[maxn][maxn];
    static int[] f1 = new int[maxn];
    static int[][] f2 = new int[maxn][maxn];
    static int[] g1 = new int[maxn];
    static int[][] g2 = new int[maxn][maxn];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        P = sc.nextInt();

        // Precompute binomial coefficients
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
            }
