                add_mod(term, mul_mod(mul_mod(cnt[i - j - 1], cnt[j]), tri));
                term = mul_mod(term, C[i - 1][j]);
                add_mod(dp1, i, term);

                int cnt_term = C[i - 1][j];
                cnt_term = mul_mod(cnt_term, cnt[j]);
                cnt_term = mul_mod(cnt_term, cnt[i - j - 1]);
                cnt_term = mul_mod(cnt_term, j + 1);
                add_mod(cnt, i, cnt_term);
            }
            add_mod(cnt, i, cnt[i]);
            add_mod(dp1, i, dp1[i]);
        }

        int[][] dp2 = new int[n + 2][m + 1];
        int[][] dp3 = new int[n + 2][m + 1];
        dp2[0][0] = 1;
        dp3[0][0] = 0;

        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= m; ++j) {
                for (int k = 0; k <= m; ++k) {
                    if (j + k > m || i + k + 1 > n + 1) continue;
                    int v2 = dp2[i][j];
                    v2 = mul_mod(v2, C[m - j][k]);
                    v2 = mul_mod(v2, cnt[k]);

                    int v3 = dp3[i][j];
                    v3 = mul_mod(v3, cnt[k]);
                    add_mod(v3, mul_mod(dp1[k], dp2[i][j]));
                    v3 = mul_mod(v3, C[m - j][k]);

                    add_mod(dp2, i + k + 1, j + k, v2);
                    add_mod(dp3, i + k + 1, j + k, v3);
                }
            }
        }

        System.out.println(dp3[n + 1][m]);
    }

    static void add_mod(int[][] arr, int i, int j, int val) {
        arr[i][j] += val;
        if (arr[i][j] >= P) arr[i][j] -= P;
    }

    static void add_mod(int[] arr, int idx, int val) {
        arr[idx] += val;
        if (arr[idx] >= P) arr[idx] -= P;
    }
