        private final BufferedWriter bw;

        public Printer(OutputStream stream) {
            bw = new BufferedWriter(new OutputStreamWriter(stream));
        }

        public void print(Object obj) {
            try {
                bw.write(obj.toString());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void println(Object obj) {
            try {
                bw.write(obj.toString());
                bw.newLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void flush() {
            try {
                bw.flush();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    static class ModInt {
        private static final long MOD = 1000000007;
        private long value;

        public ModInt(long value) {
            this.value = (value % MOD + MOD) % MOD;
        }

        public ModInt add(ModInt other) {
            return new ModInt(this.value + other.value);
        }

        public ModInt sub(ModInt other) {
            return new ModInt(this.value - other.value);
        }

        public ModInt mul(ModInt other) {
            return new ModInt(this.value * other.value);
        }

        public ModInt pow(long n) {
            ModInt base = new ModInt(this.value);
            ModInt result = new ModInt(1);
            while (n > 0) {
                if ((n & 1) == 1) {
                    result = result.mul(base);
                }
                base = base.mul(base);
                n >>= 1;
            }
            return result;
        }

        public ModInt inv() {
            return pow(MOD - 2);
        }

        public ModInt div(ModInt other) {
            return this.mul(other.inv());
        }

        public long val() {
            return value;
        }

        @Override
        public String toString() {
            return Long.toString(value);
        }
    }

    public static void main(String[] args) {
