        Printer pr = new Printer(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        ModInt[][] C = new ModInt[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                C[i][j] = new ModInt(0);
