public class Main {
    static class Scanner {
        BufferedReader br;
        StringTokenizer st;

        public Scanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    static class Printer {
        private final BufferedWriter bw;

        public Printer(OutputStream stream) {
            bw = new BufferedWriter(new OutputStreamWriter(stream));
        }

        public void print(Object obj) {
            try {
                bw.write(obj.toString());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void println(Object obj) {
            try {
                bw.write(obj.toString());
                bw.newLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void flush() {
            try {
                bw.flush();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    static class ModInt {
        private static final long MOD = 1000000007;
        private long value;

        public ModInt(long value) {
            this.value = (value % MOD + MOD) % MOD;
        }

        public ModInt add(ModInt other) {
            return new ModInt(this.value + other.value);
        }

        public ModInt sub(ModInt other) {
            return new ModInt(this.value - other.value);
        }

        public ModInt mul(ModInt other) {
            return new ModInt(this.value * other.value);
        }

        public ModInt pow(long n) {
            ModInt base = new ModInt(this.value);
            ModInt result = new ModInt(1);
            while (n > 0) {
                if ((n & 1) == 1) {
                    result = result.mul(base);
                }
                base = base.mul(base);
                n >>= 1;
            }
            return result;
        }

        public ModInt inv() {
            return pow(MOD - 2);
        }

        public ModInt div(ModInt other) {
            return this.mul(other.inv());
        }

        public long val() {
            return value;
        }

        @Override
        public String toString() {
            return Long.toString(value);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Printer pr = new Printer(System.out);

        int n = sc.nextInt();
        int m = sc.nextInt();
        int mod = sc.nextInt();

        ModInt[][] C = new ModInt[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                C[i][j] = new ModInt(0);
            }
        }
        C[0][0] = new ModInt(1);
        for (int i = 1; i <= n; i++) {
            C[i][0] = new ModInt(1);
            for (int j = 1; j <= n; j++) {
                C[i][j] = C[i - 1][j - 1].add(C[i - 1][j]);
            }
        }

        ModInt[] g = new ModInt[n + 1];
        for (int i = 0; i <= n; i++) {
            g[i] = new ModInt((long) i * (i + 1) / 2);
        }

        class Pair {
            ModInt first;
            ModInt second;

            Pair(ModInt first, ModInt second) {
                this.first = first;
                this.second = second;
            }
        }

        Pair[] f = new Pair[n + 1];
        for (int i = 0; i <= n; i++) {
            f[i] = new Pair(new ModInt(0), new ModInt(0));
        }
        f[0] = new Pair(new ModInt(1), new ModInt(0));

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < i; j++) {
                ModInt z = f[j].first.mul(f[i - 1 - j].first).mul(C[i - 1][j]);
                f[i].first = f[i].first.add(z.mul(new ModInt(i + 1)));
                f[i].second = f[i].second.add(z.mul(g[j].add(g[i - 1 - j])));
                f[i].second = f[i].second.add(
