import java.util.*;

public class Main {
    static final int MAX = 503;
    static int N, M, P;
    static long[] num = new long[MAX];
    static long[] V = new long[MAX];
    static long[][] C = new long[MAX][MAX];
    static long[][] dp = new long[MAX][MAX];
    static long[][] ans = new long[MAX][MAX];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        P = sc.nextInt();

        num[0] = 1;

        // Precompute binomial coefficients modulo P
        for (int i = 0; i <= M; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]) % P;
            }
        }

        // Compute num and V arrays
        for (int i = 1; i <= M; i++) {
            for (int j = 1; j <= i; j++) {
                long term = num[j - 1] * num[i - j] % P;
                term = term * (i + 1) % P;
                term = term * C[i - 1][j - 1] % P;
                num[i] = (num[i] + term) % P;

                int sum = 0;
                for (int k = 1; k <= i; k++) {
                    sum += Math.abs(j - k);
                }

                long term1 = V[j - 1] * num[i - j] % P;
                term1 = term1 * (i + 1) % P;
                term1 = term1 * C[i - 1][j - 1] % P;

                long term2 = V[i - j] * num[j - 1] % P;
                term2 = term2 * (i + 1) % P;
                term2 = term2 * C[i - 1][j - 1] % P;

                long term3 = num[i - j] * num[j - 1] % P;
                term3 = term3 * sum % P;
                term3 = term3 * C[i - 1][j - 1] % P;

                V[i] = (V[i] + term1 + term2 + term3) % P;
            }
        }

        dp[0][0] = 1;
        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= i; j++) {
                for (int k = 0; k + i + 1 <= N + 1 && k + j <= M; k++) {
