import java.util.*;

public class Main {
    static final int N = 505;
    static int n, m, mod;
    static int[][] C = new int[N][N];
    static int[] f = new int[N];
    static int[] g = new int[N];
    static int[][] ff = new int[N][N];
    static int[][] gg = new int[N][N];

    static void add(int[] arr, int idx, int val) {
        arr[idx] = (arr[idx] + val) % mod;
        if (arr[idx] >= mod) arr[idx] -= mod;
    }

    static void add(int[][] arr, int i, int j, int val) {
        arr[i][j] = (arr[i][j] + val) % mod;
        if (arr[i][j] >= mod) arr[i][j] -= mod;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        mod = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i-1][j] + C[i-1][j-1]) % mod;
            }
        }

        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                long term1 = (long) f[j-1] * f[i-j] % mod;
                term1 = term1 * C[i-1][j-1] % mod;
                term1 = term1 * (i + 1) % mod;
                add(f, i, (int) term1);

                long term2 = (long) g[j-1] * f[i-j] % mod;
                term2 = term2 * C[i-1][j-1] % mod;
                term2 = term2 * (i + 1) % mod;
                add(g, i, (int) term2);

                long term3 = (long) g[i-j] * f[j-1] % mod;
                term3 = term3 * C[i-1][j-1] % mod;
                term3 = term3 * (i + 1) % mod;
                add(g, i, (int) term3);

                int s = 0;
                for (int k = 1; k <= i; k++) {
                    s += Math.abs(k - j);
                    if (s >= mod) s -= mod;
                }
                long term4 = (long) f[j-1] * f[i-j] % mod;
                term4 = term4 * C[i-1][j-1] % mod;
                term4 = term4 * s % mod;
                add(g, i, (int) term4);
            }
        }

        ff[0][0] = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == i) {
                    ff[i][j] = f[i];
                    gg[i][j] = g[i];
                    break;
                }
                ff[i][j] = ff[i-1][j];
                gg[i][j] = gg[i-1][j];
                for (int k = 1; k <= j; k++) {
