            return res;
        }

        Modular inv() {
            return pow(mod - 2);
        }

        Modular add(long x) {
            return new Modular(x + v);
        }

        Modular sub(long x) {
            return new Modular(x - v);
        }

        Modular mul(long x) {
            return new Modular((x * v) % mod);
        }

        Modular div(long x) {
            return mul(new Modular(x).inv());
        }

        @Override
        public String toString() {
            return String.valueOf(v);
        }

        boolean lt(Modular r) {
            return v < r.v;
        }

        boolean eq(Modular r) {
            return v == r.v;
        }

        boolean neq(Modular r) {
            return v != r.v;
        }

        public boolean booleanValue() {
            return v != 0;
        }
    }

    static final int vmax = 10010;
    static Modular[] fact = new Modular[vmax];
    static Modular[] finv = new Modular[vmax];
    static Modular[] invs = new Modular[vmax];

    static void initfact() {
        fact[0] = new Modular(1);
        for (int i = 1; i < vmax; i++) {
            fact[i] = fact[i - 1].mul(new Modular(i));
        }
        finv[vmax - 1] = fact[vmax - 1].inv();
        for (int i = vmax - 2; i >= 0; i--) {
            finv[i] = finv[i + 1].mul(new Modular(i + 1));
        }
        for (int i = vmax - 1; i >= 1; i--) {
            invs[i] = finv[i].mul(fact[i - 1]);
        }
    }

    static Modular choose(int n, int k) {
        return fact[n].mul(finv[n - k]).mul(finv[k]);
    }

    static Modular binom(int a, int b) {
        return fact[a + b].mul(finv[a]).mul(finv[b]);
    }

    static Modular catalan(int n) {
        Modular res = binom(n, n);
        if (n - 1 >= 0) {
            res = res.sub(binom(n - 1, n + 1));
        }
        return res;
    }

    static void slv() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        long mod = sc.nextLong();
        Modular.ref = new ModInfo(mod, 0);
        Modular.mod = mod;
        Modular.root = 0;
        initfact();

        Modular ans = new Modular(0);
        for (int len = 1; len < m; len++) {
            Modular f = new Modular(len + 1).pow(len).mul(new Modular(len)).div(new Modular(n - len)).mul(finv[len]);
            for (int i = 0; i < m - len; i++) {
                int j = i + len;
                Modular g = new Modular(n - len).pow(i).mul(finv[i]);
                Modular h = new Modular(n - j).mul(new Modular(n + 1).pow(m - 1 - j)).mul(fact[j]);
                ans = ans.add(f.mul(g).mul(h));
            }
        }
        ans = ans.mul(new Modular(2).pow(m - 1)).mul(new Modular(n + 1 - m));
        System.out.println(ans);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        slv();
    }
}

