            this.root = root;
        }
    }

    static final int VMAX = 10010;
    static Mint[] FACT = new Mint[VMAX];
    static Mint[] FINV = new Mint[VMAX];
    static Mint[] INVS = new Mint[VMAX];
    static ModInfo base = new ModInfo(998244353, 3);

    static void INIT_FACT() {
        FACT[0] = new Mint(1, base.mod);
        for (int i = 1; i < VMAX; i++) {
            FACT[i] = FACT[i - 1].mul(new Mint(i, base.mod));
