                long part1 = (g[(int)j] * f[(int)(i - 1 - j)] % P + f[(int)j] * g[(int)(i - 1 - j)] % P) * (i + 1) % P;
                long part2 = f[(int)j] * f[(int)(i - 1 - j)] % P * (triangular.apply(j) + triangular.apply(i - 1 - j)) % P;
                long inner = (part1 + part2) % P * nCr.apply(i - 1, j) % P;
                g[(int)i] = (g[(int)i] + inner) % P;
            }
            f[(int)i] = f[(int)i] * (i + 1) % P;
        }

        long[][] F = new long[(int)m + 1][(int)n + 1];
        long[][] G = new long[(int)m + 1][(int)n + 1];

        F[0][0] = 1;
        for (int j = 0; j <= n; ++j) F[0][j] = 1;

        for (long i = 1; i <= m; ++i) {
            F[(int)i][(int)i] = f[(int)i];
            G[(int)i][(int)i] = g[(int)i];
            for (long j = i + 1; j <= n; ++j) {
                F[(int)i][(int)j] = F[(int)i][(int)(j-1)];
                G[(int)i][(int)j] = G[(int)i][(int)(j-1)];
                for (long l = 1; l <= i; ++l) {
                    if (j - 1 - l >= 0) {
                        long termF = F[(int)(i-l)][(int)(j-1-l)] * f[(int)l] % P * nCr.apply(i, l) % P;
                        F[(int)i][(int)j] = (F[(int)i][(int)j] + termF) % P;

                        long termG = (G[(int)(i-l)][(int)(j-1-l)] * f[(int)l] % P + F[(int)(i-l)][(int)(j-1-l)] * g[(int)l] % P) % P;
                        termG = termG * nCr.apply(i, l) % P;
                        G[(int)i][(int)j] = (G[(int)i][(int)j] + termG) % P;
                    }
                }
            }
        }

        System.out.println(G[(int)m][(int)n]);
    }

    private static long modExp(long base, long exp, long mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }
}

