using namespace std;
using ll = long long;

const int MAX_N = 500;
int MOD, C[MAX_N + 1][MAX_N + 1];
pair<int, int> dp1[MAX_N + 1], dp2[2][MAX_N + 1][MAX_N + 1];

inline void add(int &x, int y) {
    x = (x + y) % MOD;
    if (x < 0) x += MOD;
}

inline int sum_tri(int n) {
    return 1LL * n * (n + 1) / 2;
}

int main() {
    int n, m;
    scanf("%d%d%d", &n, &m, &MOD);

    for (int i = 0; i <= m; ++i) {
        C[i][0] = 1;
        for (int j = 1; j <= i; ++j) {
            C[i][j] = (C[i-1][j] + C[i-1][j-1]) % MOD;
        }
    }

    dp1[0] = {1, 0};
    for (int i = 1; i <= m; ++i) {
        for (int j = 1; j <= i; ++j) {
            int w = 1LL * dp1[j-1].first * dp1[i-j].first % MOD * C[i-1][j-1] % MOD;
            int term1 = 1LL * (sum_tri(j-1) + sum_tri(i-j)) * w % MOD;
