        for (int j = 0; j < i; ++j) {
            int temp = multiply(binomial(i - 1, j), multiply(f_arr[j], f_arr[i - 1 - j]));
            f_arr[i] = add(f_arr[i], multiply(temp, i + 1));
            g_arr[i] = add(g_arr[i], multiply(temp, add(prefix[j], prefix[i - 1 - j])));

            temp = multiply(add(multiply(g_arr[j], f_arr[i - 1 - j]), multiply(g_arr[i - 1 - j], f_arr[j])), i + 1);
            g_arr[i] = add(g_arr[i], multiply(temp, binomial(i - 1, j)));
