        int[] g = new int[maxn];
        f[0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                int term = mul(mul(f[j - 1], f[i - j]), mul(i + 1, C[i - 1][j - 1]));
                f[i] = add(f[i], term);

                term = mul(mul(f[j - 1], g[i - j]), mul(i + 1, C[i - 1][j - 1]));
                g[i] = add(g[i], term);

                term = mul(mul(g[j - 1], f[i - j]), mul(i + 1, C[i - 1][j - 1]));
                g[i] = add(g[i], term);

                term = mul(mul(f[j - 1], f[i - j]), mul(add(C[j][2], C[i - j + 1][2]), C[i - 1][j - 1]));
