        int f, g;

        Pt(int f, int g) {
            this.f = f;
            this.g = g;
        }

        Pt() {
            this.f = 0;
            this.g = 0;
        }
    }

    static Pt addPt(Pt x, Pt y) {
        return new Pt(addmod(x.f + y.f), addmod(x.g + y.g));
    }

    static Pt mulPt(Pt x, Pt y) {
        return new Pt(
            (int) ((long) x.f * y.f % mod),
            addmod((int) ((long) x.f * y.g % mod) + (int) ((long) x.g * y.f % mod))
        );
    }

    static int F(int x) {
        return (int) ((long) x * (x + 1) / 2 % mod);
    }

