import java.io.*;

public class Main {
    static long M;
    static long[][] newt = new long[515][515];
    static long[][] inv_newt = new long[515][515];

    static long spow(long a, long b) {
        long r = 1;
        while (b > 0) {
            if (b % 2 == 1) {
                r = (r * a) % M;
            }
            a = (a * a) % M;
            b /= 2;
        }
        return r;
    }

    static long Inv(long a) {
        long b = M - 2;
        long r = 1;
        while (b > 0) {
            if (b % 2 == 1) {
                r = (r * a) % M;
            }
            a = (a * a) % M;
            b /= 2;
        }
        return r;
    }

    static long f(int c, int p) {
        if (p == 0) {
            return 1;
        }
        return (spow(c + 1, p - 1) * ((c + 1 - p) % M + M) % M) % M;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
