import java.util.*;
import java.io.*;

public class Main {
    static int mod, n, m, i, j, k;
    static int[][] c = new int[505][505];
    static int[] f = new int[505];
    static int[] g = new int[505];
    static int[][][] dp = new int[505][505][2];
    static int ans;

    static void readInt(DataInputStream in, int[] arr) throws IOException {
        int idx = 0;
        while (idx < arr.length) {
            int v = 0, sign = 1;
            int c = in.read();
            while (c >= 0 && !Character.isDigit(c) && c != '-') {
                c = in.read();
            }
            if (c == '-') {
                sign = -1;
                c = in.read();
            } else {
                v = c - '0';
            }
            while (c >= 0 && Character.isDigit(c)) {
                v = (v << 1) + (v << 3) + (c - '0');
                c = in.read();
            }
            arr[idx++] = v * sign;
        }
    }

    public static void main(String[] args) {
        try {
            DataInputStream in = new DataInputStream(System.in);
            int[] inputs = new int[3];
            readInt(in, inputs);
            mod = inputs[0];
            n = inputs[1];
            m = inputs[2];

            c[0][0] = 1;
            for (i = 1; i <= n; i++) {
                c[i][0] = 1;
                for (j = 1; j <= i; j++) {
                    c[i][j] = (c[i-1][j] + c[i-1][j-1]) % mod;
                }
            }

            f[0] = 1;
            for (i = 1; i <= n; i++) {
                for (j = 0; j < i; j++) {
                    k = i - j - 1;
                    long term1 = (long)f[j] * f[k] % mod;
                    term1 = term1 * (i + 1) % mod;
                    term1 = term1 * c[i-1][j] % mod;
                    f[i] = (int)((f[i] + term1) % mod);

                    long term2 = (long)g[j] * f[k] % mod;
                    term2 = term2 * (i + 1) % mod;
                    term2 = term2 * c[i-1][j] % mod;
                    g[i] = (int)((g[i] + term2) % mod);

                    long term3 = (long)f[j] * g[k] % mod;
                    term3 = term3 * (i + 1) % mod;
                    term3 = term3 * c[i-1][j] % mod;
                    g[i] = (int)((g[i] + term3) % mod);

                    long term4 = (long)f[j] * f[k] % mod;
                    term4 = term4 * c[i-1][j] % mod;
                    long sum = (long)j * (j + 1) / 2 + (long)k * (k + 1) / 2;
                    term4 = term4 * sum % mod;
                    g[i] = (int)((g[i] + term4) % mod);
                }
            }

            dp[0][0][1] = 1;
            for (i = 0; i < n; i++) {
                for (j = 0; j <= i; j++) {
                    dp[i+1][j][1] = (int)((dp[i+1][j][1] + dp[i][j][0] + dp[i][j][1]) % mod);
                    for (k = 1; k <= n - i; k++) {
                        long term = (long)dp[i][j][1] * f[k] % mod;
                        term = term * c[j+k][j] % mod;
                        dp[i+k][j+k][0] = (int)((dp[i+k][j+k][0] + term) % mod);
                    }
                }
            }

            for (j = 1; j <= n; j++) {
                for (i = 1; i <= j; i++) {
                    int rem = m - (j - i + 1);
                    if (rem < 0) continue;
                    for (k = 0; k <= rem; k++) {
                        long term = (long)g[j - i + 1] * dp[i-1][k][1] % mod;
                        term = term * dp[n-j][rem-k][1] % mod;
                        term = term * c[m][rem] % mod;
                        term = term * c[rem][k] % mod;
                        ans = (int)((ans + term) % mod);
                    }
                }
            }

            System.out.println(ans);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

