import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_N = 70;
    static final int MAX_M = 50;
    static final int LIMIT = 22;

    static long[][] C = new long[MAX_N + 5][MAX_N + 5];

    static void init_binomials() {
        for (int i = 0; i < MAX_N; ++i) {
            C[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                C[i][j] = C[i-1][j-1] + C[i-1][j];
            }
        }
    }

    static int n, m, N;
    static int mid;
    static int[] fixed_constraints = new int[MAX_N + 5];

    static List<long[]>[] memo_b = new List[MAX_M + 5][MAX_M + 5];
    static Map<Long, Long>[] memo_a = new Map[MAX_M + 5][MAX_M + 5];

    static long min_abs = Long.MAX_VALUE;
    static long count_min_abs = 0;

    static void update_min(long val, long cnt) {
        if (val < min_abs) {
            min_abs = val;
            count_min_abs = cnt;
        } else if (val == min_abs) {
            count_min_abs += cnt;
        }
    }

    static void dfs_b(int pos, int cnt_a, int cnt_b, long sum) {
        if (pos == mid) {
            memo_b[cnt_a][cnt_b].add(new long[]{sum, 1});
            return;
        }
        for (int choice = 0; choice < 2; ++choice) {
            if (fixed_constraints[pos-1] != -1 && choice != fixed_constraints[pos-1]) continue;
            long contribution = 0;
            if (choice == 0 && cnt_a > 0) {
                for (int j = 0; j < n; ++j) {
                    contribution += C[cnt_a-1][n-1] * C[cnt_b][j] * C[N-pos][n-j];
                }
                dfs_b(pos-1, cnt_a-1, cnt_b, sum + contribution);
            } else if (choice == 1 && cnt_b > 0) {
                for (int j = 0; j < n; ++j) {
                    contribution -= C[cnt_b-1][n-1] * C[cnt_a][j] * C[N-pos][n-j];
                }
                dfs_b(pos-1, cnt_a, cnt_b-1, sum + contribution);
            }
        }
    }

    static void bfs_a() {
        for (int i = 0; i <= n+m; ++i) {
            for (int j = 0; j <= n+m; ++j) {
                memo_a[i][j].clear();
            }
        }
        memo_a[0][0].put(0L, 1L);

        for (int i = 0; i <= n+m; ++i) {
            for (int j = 0; j <= n+m; ++j) {
                for (Map.Entry<Long, Long> entry : memo_a[i][j].entrySet()) {
                    long cur_sum = entry.getKey();
                    long cnt = entry.getValue();
                    if (i + j == mid) {
                        List<long[]> list = memo_b[i][j];
                        long target = -cur_sum;
                        int left = 0, right = list.size(), idx = -1;
                        while (left < right) {
                            int mid_idx = (left + right) / 2;
                            if (list.get(mid_idx)[0] >= target) {
                                right = mid_idx;
                            } else {
                                left = mid_idx + 1;
                            }
                        }
                        idx = left;

                        if (idx < list.size()) {
                            update_min(Math.abs(cur_sum + list.get(idx)[0]), cnt * list.get(idx)[1]);
                        }
                        if (idx > 0) {
                            update_min(Math.abs(cur_sum + list.get(idx-1)[0]), cnt * list.get(idx-1)[1]);
                        }
                    } else {
                        int idx = i + j;
                        for (int choice = 0; choice < 2; ++choice) {
                            if (fixed_constraints[idx] != -1 && choice != fixed_constraints[idx]) continue;
                            int na = i, nb = j;
                            if (choice == 0) ++na;
                            else ++nb;
                            if (na <= n+m && nb <= n+m) {
                                long delta = 0;
                                if (choice == 0) {
                                    for (int l = 0; l < n; ++l) {
                                        delta += C[na-1][n-1] * C[nb][l] * C[N-idx-1][n-l];
                                    }
                                } else {
                                    for (int l = 0; l < n; ++l) {
                                        delta -= C[nb-1][n-1] * C[na][l] * C[N-idx-1][n-l];
                                    }
                                }
                                memo_a[na][nb].put(cur_sum + delta, memo_a[na][nb].getOrDefault(cur_sum + delta, 0L) + cnt);
                            }
                        }
                    }
                }
            }
        }
    }

    static void process() {
        for (int i = 0; i <= n+m; ++i) {
            for (int j = 0; j <= n+m; ++j) {
                memo_b[i][j].clear();
            }
        }
        dfs_b(N, n+m, n+m, 0);

        for (int i = 0; i <= n+m; ++i) {
            for (int j = 0; j <= n+m; ++j) {
                Collections.sort(memo_b[i][j], (a, b) -> Long.compare(a[0], b[0]));
                List<long[]> merged = new ArrayList<>();
                int sz = memo_b[i][j].size();
                for (int k = 0; k < sz; ) {
                    long val = memo_b[i][j].get(k)[0];
                    long total = 0;
                    while (k < sz && memo_b[i][j].get(k)[0] == val) {
                        total += memo_b[i][j].get(k)[1];
                        ++k;
                    }
                    merged.add(new long[]{val, total});
                }
                memo_b[i][j] = merged;
            }
        }
        bfs_a();
    }

    public static void main(String[] args) throws IOException {
        init_binomials();
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        n = Integer.parseInt(firstLine[0]);
        m = Integer.parseInt(firstLine[1]);
        String s = br.readLine().trim();

        for (int i = 0; i <= MAX_M; ++i) {
            for (int j = 0; j <= MAX_M; ++j) {
                memo_b[i][j] = new ArrayList<>();
                memo_a[i][j] = new HashMap<>();
            }
        }

        N = (n + m) * 2;
        mid = Math.max(0, N - LIMIT);
        Arrays.fill(fixed_constraints, -1);

        process();
        count_min_abs = 0;
        for (int i = 0; i < N; ++i) {
            if (s.charAt(i) == 'A') fixed_constraints[i] = 0;
            else if (s.charAt(i) == 'B') fixed_constraints[i] = 1;
        }
        process();
        System.out.println(count_min_abs);
    }
}

