    static int[] cntA = new int[12345];
    static int[] cntB = new int[12345];
    static Map<Long, Long> mp = new HashMap<>();

    static void dfs(long x, long y, int v1, int v2) {
        long diff = Math.abs(x - y);
        if (best <= 1 || diff - C[v1][r] * C[v2][r] >= best) return;

        if (v1 == r - 1 && v2 == r - 1) {
            long curDiff = Math.abs(x - y);
            if (curDiff < best) {
                best = curDiff;
                best_z = x;
            }
            return;
        }

        if (v1 >= r) {
            long cur1 = C[v1][r] - C[v1 - 1][r];
            long sum2 = C[v2][r];
            dfs(x, y + cur1 * sum2, v1 - 1, v2);
        }

        if (v2 >= r) {
            long sum1 = C[v1][r];
            long cur2 = C[v2][r] - C[v2 - 1][r];
            dfs(x + sum1 * cur2, y, v1, v2 - 1);
        }
    }

    static long solve(long x, long y, int v1, int v2) {
        long state = x * 10000 + v1 * 100 + v2;
        if (mp.containsKey(state)) return mp.get(state);

        long[] res = new long[1];
        long diff = Math.abs(x - y);
        if (diff - C[v1][r] * C[v2][r] > best) {
            res[0] = 0;
            mp.put(state, res[0]);
            return res[0];
        }

        if (v1 < r || v2 < r) {
            if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
                int sum = v1 + v2;
                v1 -= cntA[sum];
                v2 -= cntB[sum];
                res[0] = C[v1 + v2][v1];
                mp.put(state, res[0]);
                return res[0];
            }
            res[0] = 0;
            mp.put(state, res[0]);
            return res[0];
        }

        res[0] = 0;
        char ch = s[v1 + v2 - 1];
        if (ch != 'B') {
            long cur1 = C[v1][r] - C[v1 - 1][r];
            long sum2 = C[v2][r];
            res[0] += solve(x, y + cur1 * sum2, v1 - 1, v2);
        }

        if (ch != 'A') {
            long sum1 = C[v1][r];
            long cur2 = C[v2][r] - C[v2 - 1][r];
            res[0] += solve(x + sum1 * cur2, y, v1, v2 - 1);
        }

        mp.put(state, res[0]);
        return res[0];
    }

