            long sum_y = C[j_idx][R];
            dfs(x_val, y_val + delta_x * sum_y, i_idx - 1, j_idx);
        }

        if (j_idx >= R) {
            long sum_x = C[i_idx][R];
            long delta_y = C[j_idx][R] - C[j_idx - 1][R];
            dfs(x_val + sum_x * delta_y, y_val, i_idx, j_idx - 1);
        }
    }

    static long solve_dp(long x_val, long y_val, int i_idx, int j_idx) {
        long state = x_val * 10000 + i_idx * 100 + j_idx;
        if (memo_map.containsKey(state))
            return memo_map.get(state);

        long[] res = new long[1];
        long diff = Math.abs(x_val - y_val);
        if (diff - C[i_idx][R] * C[j_idx][R] > min_diff) {
            res[0] = 0;
            memo_map.put(state, res[0]);
            return res[0];
        }

        if (i_idx < R || j_idx < R) {
            if (i_idx >= cnt_A[i_idx + j_idx] && j_idx >= cnt_B[i_idx + j_idx]) {
                int total = i_idx + j_idx;
                i_idx -= cnt_A[total];
                j_idx -= cnt_B[total];
                res[0] = C[total][i_idx];
                memo_map.put(state, res[0]);
                return res[0];
            }
            res[0] = 0;
            memo_map.put(state, res[0]);
            return res[0];
        }

        res[0] = 0;
        char c = input_str[i_idx + j_idx - 1];
        if (c != 'B') {
            long delta_x = C[i_idx][R] - C[i_idx - 1][R];
            long sum_y = C[j_idx][R];
            res[0] += solve_dp(x_val, y_val + delta_x * sum_y, i_idx - 1, j_idx);
        }
        if (c != 'A') {
            long sum_x = C[i_idx][R];
            long delta_y = C[j_idx][R] - C[j_idx - 1][R];
            res[0] += solve_dp(x_val + sum_x * delta_y, y_val, i_idx, j_idx - 1);
        }
        memo_map.put(state, res[0]);
        return res[0];
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line1 = br.readLine().split(" ");
        R = Integer.parseInt(line1[0]);
        C_input = Integer.parseInt(line1[1]);

        for (int i = 0; i <= 2 * (R + C_input); i++) {
            for (int j = 0; j <= 2 * (R + C_input); j++) {
                if (j == 0) C[i][j] = 1;
                else if (i == 0) C[i][j] = 0;
                else C[i][j] = C[i - 1][j] + C[i - 1][j - 1];
            }
        }

        total_paths = C[R + C_input][R] * C[R + C_input][R];

        {
            long x = 0, y = 0;
            int i = R + C_input, j = R + C_input;
            while (i >= R && j >= R) {
                if (x > y) {
                    long delta_x = C[i][R] - C[i - 1][R];
                    long sum_y = C[j][R];
                    y += delta_x * sum_y;
                    i--;
                } else {
                    long sum_x = C[i][R];
                    long delta_y = C[j][R] - C[j - 1][R];
                    x += sum_x * delta_y;
                    j--;
                }
            }
            min_diff = Math.abs(x - y);
        }

        dfs(0, 0, R + C_input, R + C_input);
        input_str = br.readLine().toCharArray();
        cnt_A[0] = cnt_B[0] = 0;
        for (int i = 0; i < 2 * (R + C_input); i++) {
            cnt_A[i + 1] = cnt_A[i] + (input_str[i] == 'A' ? 1 : 0);
            cnt_B[i + 1] = cnt_B[i] + (input_str[i] == 'B' ? 1 : 0);
        }

        long result = solve_dp(0, 0, R + C_input, R + C_input);
        System.out.println(result);
    }
}

