import java.util.*;
import java.io.*;

public class Main {
    static int rows, cols, total_len, loop_idx;
    static char[] buffer = new char[70];
    static long[][] C = new long[70][70];

    static int[] cntA = new int[70];
    static int[] cntB = new int[70];
    static List<Long>[] partA = new List[70];
    static List<Long>[] partB = new List[70];

    static void init_binom() {
        for (int i = 0; i <= total_len; ++i) {
            C[i][0] = 1;
            for (int j = 1; j <= i; ++j)
                C[i][j] = C[i-1][j-1] + C[i-1][j];
        }
    }

    static long diff_calc(int pattern, int a_cnt, int b_cnt) {
        long res = 0;
        long t1, t2;

        for (int k = 0; k < cols + 1; ++k) {
            if ((pattern & (1 << k)) != 0) {
                ++b_cnt;
                t1 = C[b_cnt - 1][rows - 1];
                t2 = C[total_len - b_cnt][rows] - C[a_cnt][rows];
                res -= t1 * t2;
            } else {
                ++a_cnt;
                t1 = C[a_cnt - 1][rows - 1];
                t2 = C[total_len - a_cnt][rows] - C[b_cnt][rows];
                res += t1 * t2;
            }
        }
        return res;
    }

    static boolean is_valid(int pattern) {
        for (int k = 0; k < cols + 1; ++k) {
            if (buffer[2 * rows + cols + k] == 'A' && ((pattern >> k) & 1) == 1) return false;
            if (buffer[2 * rows + cols + k] == 'B' && ((pattern >> k) & 1) == 0) return false;
        }
        return true;
    }

    static void build_tables() {
        int max_pat = 1 << (cols + 1);

        for (int pat = 0; pat < max_pat; ++pat) {
            int b_here = Integer.bitCount(pat);
            int a_here = cols + 1 - b_here;

            if (is_valid(pat))
                partA[a_here].add(diff_calc(pat, rows + cols - a_here, rows + cols - b_here));
            else
                partB[a_here].add(diff_calc(pat, rows + cols - a_here, rows + cols - b_here));
        }

        for (int i = 0; i <= cols + 1; ++i) {
            Collections.sort(partA[i]);
            Collections.sort(partB[i]);
        }
    }

    static long get_coeff(int pattern) {
        int i, j;

        for (i = 0; i < cols + 1; ++i)
            if (((pattern >> i) & 1) != (pattern & 1))
                break;

        for (j = i; j < cols + 1; ++j) {
            if (buffer[2 * rows - 1 + j] == 'A' && (((pattern >> j) & 1) == 1)) return 0;
            if (buffer[2 * rows - 1 + j] == 'B' && (((pattern >> j) & 1) == 0)) return 0;
        }

        int set_a = rows - 1 + ((pattern & 1) == 0 ? i : 0);
        int set_b = rows - 1 + ((pattern & 1) == 1 ? i : 0);

        if (set_a < cntA[2 * rows - 2 + i]) return 0;
        if (set_b < cntB[2 * rows - 2 + i]) return 0;
        return C[set_a + set_b - cntA[2 * rows - 2 + i] - cntB[2 * rows - 2 + i]][set_a - cntA[2 * rows - 2 + i]];
    }

    static void update_min(long[] best, long[] cand) {
        if (cand[0] < 0) cand[0] = -cand[0];

        if (best[0] < cand[0]) return;
        if (best[0] > cand[0]) {
            best[0] = cand[0];
            best[1] = cand[1];
            return;
        }
        best[1] += cand[1];
    }

    static long count_equal(List<Long> vec, long val) {
        int lb = Collections.binarySearch(vec, val);
        if (lb < 0) lb = -lb - 1;
        int ub = lb;
        while (ub < vec.size() && vec.get(ub).equals(val)) ub++;
        return ub - lb;
    }

    static long solve_first() {
        int max_pat = 1 << (cols + 1);
        long[] best = new long[]{1L << 60, 0};

        for (int pat = 0; pat < max_pat; ++pat) {
            int b_here = Integer.bitCount(pat);
            int a_here = cols + 1 - b_here;
            long cur_val = diff_calc(pat, rows - 1, rows - 1);

            long coeff = get_coeff(pat);
            List<Long> listA = partA[cols + 1 - a_here];
            int idx = Collections.binarySearch(listA, -cur_val);
            if (idx < 0) idx = -idx - 1;

            if (idx < listA.size()) {
                if (best[0] >= Math.abs(listA.get(idx) + cur_val)) {
                    long c2 = count_equal(listA, listA.get(idx));
                    long[] cand = new long[]{Math.abs(listA.get(idx) + cur_val), coeff * c2};
                    update_min(best, cand);
                }
            }

            if (idx > 0) {
                idx--;
                if (best[0] >= Math.abs(listA.get(idx) + cur_val)) {
                    long c2 = count_equal(listA, listA.get(idx));
                    long[] cand = new long[]{Math.abs(listA.get(idx) + cur_val), coeff * c2};
                    update_min(best, cand);
                }
            }

            coeff = 0;
            List<Long> listB = partB[cols + 1 - a_here];
            idx = Collections.binarySearch(listB, -cur_val);
            if (idx < 0) idx = -idx - 1;

            if (idx < listB.size()) {
                if (best[0] >= Math.abs(listB.get(idx) + cur_val)) {
                    long c2 = count_equal(listB, listB.get(idx));
                    long[] cand = new long[]{Math.abs(listB.get(idx) + cur_val), coeff * c2};
                    update_min(best, cand);
                }
            }

            if (idx > 0) {
                idx--;
                if (best[0] >= Math.abs(listB.get(idx) + cur_val)) {
                    long c2 = count_equal(listB, listB.get(idx));
                    long[] cand = new long[]{Math.abs(listB.get(idx) + cur_val), coeff * c2};
                    update_min(best, cand);
                }
            }
        }

        return best[1];
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line1 = br.readLine().split(" ");
        rows = Integer.parseInt(line1[0]);
        cols = Integer.parseInt(line1[1]);
        String line2 = br.readLine();
        buffer = (" " + line2).toCharArray();

        total_len = 2 * (rows + cols);

        for (int i = 0; i < 70; i++) {
            partA[i] = new ArrayList<>();
            partB[i] = new ArrayList<>();
        }

        init_binom();

        for (loop_idx = 1; loop_idx <= total_len; ++loop_idx) {
            cntA[loop_idx] = cntA[loop_idx - 1] + (buffer[loop_idx] == 'A' ? 1 : 0);
            cntB[loop_idx] = cntB[loop_idx - 1] + (buffer[loop_idx] == 'B' ? 1 : 0);
        }

        build_tables();
        long answer = solve_first();
        System.out.println(answer);
    }
}

import java.util.*;
import java.io.*;

public class Main {
    static int R, C, N;
    static long[][] binomial = new long[66][66];
    static int[] cntA = new int[66];
    static int[] cntB = new int[66];
    static String str;
    static List<Long>[] vec_part = new List[66];
    static List<Long>[] vec_zero = new List[66];

    static void build_binomial_table() {
        for (int i = 0; i <= N; ++i) {
            binomial[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                binomial[i][j] = binomial[i-1][j-1] + binomial[i-1][j];
            }
        }
    }

    static long compute_diff(int config, int a_prev, int b_prev) {
        long total = 0;
        long t1, t2;

        for (int k = 0; k < C + 1; ++k) {
            if ((config & (1 << k)) != 0) {
                ++b_prev;
                t1 = binomial[b_prev - 1][R - 1];
                t2 = binomial[N - b_prev][R] - binomial[a_prev][R];
                total -= t1 * t2;
            } else {
                ++a_prev;
                t1 = binomial[a_prev - 1][R - 1];
                t2 = binomial[N - a_prev][R] - binomial[b_prev][R];
                total += t1 * t2;
            }
        }
        return total;
    }

    static boolean config_ok(int config) {
        for (int k = 0; k < C + 1; ++k) {
            if (str.charAt(2 * R + C + k) == 'A' && ((config >> k) & 1) == 1) return false;
            if (str.charAt(2 * R + C + k) == 'B' && ((config >> k) & 1) == 0) return false;
        }
        return true;
    }

    static void prepare_tables() {
        int max_config = 1 << (C + 1);

        for (int cfg = 0; cfg < max_config; ++cfg) {
            int b_here = Integer.bitCount(cfg);
            int a_here = C + 1 - b_here;

            if (config_ok(cfg)) {
                vec_part[a_here].add(compute_diff(cfg, R + C - a_here, R + C - b_here));
            } else {
                vec_zero[a_here].add(compute_diff(cfg, R + C - a_here, R + C - b_here));
            }
        }

        for (int i = 0; i <= C + 1; ++i) {
            Collections.sort(vec_part[i]);
            Collections.sort(vec_zero[i]);
        }
    }

    static long get_factor(int config) {
        int i, j;

        for (i = 0; i < C + 1; ++i) {
            if (((config >> i) & 1) != (config & 1)) {
                break;
            }
        }

        for (j = i; j < C + 1; ++j) {
            if (str.charAt(2 * R - 1 + j) == 'A' && (((config >> j) & 1) == 1)) return 0;
            if (str.charAt(2 * R - 1 + j) == 'B' && (((config >> j) & 1) == 0)) return 0;
        }

        int set_a = R - 1 + ((config & 1) == 0 ? i : 0);
        int set_b = R - 1 + ((config & 1) == 1 ? i : 0);

        if (set_a < cntA[2 * R - 2 + i]) return 0;
        if (set_b < cntB[2 * R - 2 + i]) return 0;
        return binomial[set_a + set_b - cntA[2 * R - 2 + i] - cntB[2 * R - 2 + i]][set_a - cntA[2 * R - 2 + i]];
    }

    static void update_best(Pair best, Pair candidate) {
        if (candidate.first < 0) candidate.first = -candidate.first;

        if (best.first < candidate.first) return;
        if (best.first > candidate.first) {
            best.first = candidate.first;
            best.second = candidate.second;
            return;
        }
        best.second += candidate.second;
    }

    static long count_occurrences(List<Long> arr, long target) {
        int lo = Collections.binarySearch(arr, target);
        if (lo < 0) lo = -lo - 1;
        int hi = lo;
        while (hi < arr.size() && arr.get(hi).equals(target)) {
            hi++;
        }
        return hi - lo;
    }

    static long compute_solution() {
        int max_config = 1 << (C + 1);
        Pair best = new Pair(1L << 60, 0);

        for (int cfg = 0; cfg < max_config; ++cfg) {
            int b_here = Integer.bitCount(cfg);
            int a_here = C + 1 - b_here;
            long current = compute_diff(cfg, R - 1, R - 1);

            long factor = get_factor(cfg);
            List<Long> list = vec_part[C + 1 - a_here];
            int idx = Collections.binarySearch(list, -current);
            if (idx < 0) idx = -idx - 1;

            if (idx < list.size()) {
                long val = list.get(idx);
                if (best.first >= Math.abs(val + current)) {
                    long factor2 = count_occurrences(list, val);
                    update_best(best, new Pair(val + current, factor * factor2));
                }
            }

            if (idx > 0) {
                idx--;
                long val = list.get(idx);
                if (best.first >= Math.abs(val + current)) {
                    long factor2 = count_occurrences(list, val);
                    update_best(best, new Pair(val + current, factor * factor2));
                }
            }

            factor = 0;
            list = vec_zero[C + 1 - a_here];
            idx = Collections.binarySearch(list, -current);
            if (idx < 0) idx = -idx - 1;

            if (idx < list.size()) {
                long val = list.get(idx);
                if (best.first >= Math.abs(val + current)) {
                    long factor2 = count_occurrences(list, val);
                    update_best(best, new Pair(val + current, factor * factor2));
                }
            }

            if (idx > 0) {
                idx--;
                long val = list.get(idx);
                if (best.first >= Math.abs(val + current)) {
                    long factor2 = count_occurrences(list, val);
                    update_best(best, new Pair(val + current, factor * factor2));
                }
            }
        }

        return best.second;
    }

    static class Pair {
        long first;
        long second;

        Pair(long f, long s) {
            first = f;
            second = s;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] line1 = br.readLine().split(" ");
        R = Integer.parseInt(line1[0]);
        C = Integer.parseInt(line1[1]);
        str = br.readLine();
        str = " " + str; // 1-indexed
        N = 2 * (R + C);

        for (int i = 0; i < 66; i++) {
            vec_part[i] = new ArrayList<>();
            vec_zero[i] = new ArrayList<>();
        }

        build_binomial_table();

        for (int loop_var = 1; loop_var <= N; ++loop_var) {
            cntA[loop_var] = cntA[loop_var - 1] + (str.charAt(loop_var) == 'A' ? 1 : 0);
            cntB[loop_var] = cntB[loop_var - 1] + (str.charAt(loop_var) == 'B' ? 1 : 0);
        }

        prepare_tables();
        long result = compute_solution();
        System.out.println(result);
    }
}

