                    }
                }

                if (step < totalSteps && x+1 <= totalSteps && y <= totalSteps) {
                    if (pattern.charAt((int)step) != 'A') {
                        long newArea = prefixSum[(int)(x+1)][(int)y] - prefixSum[(int)x][(int)y];
                        for (Map.Entry<Long, Long> kv : dp[(int)x][(int)y].entrySet()) {
                            long newTotal = kv.getKey() + newArea;
                            if (newTotal <= otherHalf) {
                                dp[(int)(x+1)][(int)y].put(newTotal, dp[(int)(x+1)][(int)y].getOrDefault(newTotal, 0L) + kv.getValue());
                            }
                        }
                    }

                    if (pattern.charAt((int)(2*totalSteps-step-1)) != 'A') {
                        long newArea = reverseSum[(int)(totalSteps-x)][(int)(totalSteps-y)] - reverseSum[(int)(totalSteps-x-1)][(int)(totalSteps-y)];
                        for (Map.Entry<Long, Long> kv : bp[(int)x][(int)y].entrySet()) {
