                            }
                        }
                    }
                }

                if (step < totalSteps) {
                    dp[(int)x][(int)y].clear();
                    bp[(int)x][(int)y].clear();
                }
            }
        }

        for (long x = 0; x <= totalSteps; x++) {
            long y = totalSteps - x;
            if (y < 0 || y > totalSteps) continue;
            for (Map.Entry<Long, Long> kv : dp[(int)x][(int)y].entrySet()) {
